css:
@property --dre-stack-occ { syntax: "<number>"; inherits: true; initial-value: 0; }

.dre-stack {
  /* re-theme with these four */
  --dre-stack-bg: oklch(0.975 0.008 85);
  --dre-stack-ink: oklch(0.25 0.02 262);
  --dre-stack-accent: oklch(0.56 0.15 38);
  --dre-stack-cool: oklch(0.6 0.08 200);
  /* expiry ramp: this year -> nine years out */
  --dre-stack-near: oklch(0.73 0.145 34);
  --dre-stack-mid: oklch(0.88 0.1 86);
  --dre-stack-far: color-mix(in oklch, var(--dre-stack-cool) 55%, white);
  /* rent vs market: under-rented (reversion) / over-rented */
  --dre-stack-under: oklch(0.79 0.085 235);
  --dre-stack-even: oklch(0.94 0.01 85);
  --dre-stack-over: oklch(0.75 0.13 12);
  /* industry */
  --dre-stack-i-legal: oklch(0.76 0.07 262);
  --dre-stack-i-fin: oklch(0.8 0.09 155);
  --dre-stack-i-tech: oklch(0.82 0.085 215);
  --dre-stack-i-health: oklch(0.82 0.08 12);
  --dre-stack-i-pro: oklch(0.87 0.095 96);
  --dre-stack-i-crea: oklch(0.8 0.1 322);
  --dre-stack-i-flex: oklch(0.84 0.1 62);
  --dre-stack-i-pub: oklch(0.78 0.035 245);
  --dre-stack-i-retail: oklch(0.84 0.11 128);
  /* derived */
  --dre-stack-card: color-mix(in oklch, var(--dre-stack-bg) 35%, white);
  --dre-stack-side: color-mix(in oklch, var(--dre-stack-bg) 94%, var(--dre-stack-ink));
  --dre-stack-line: color-mix(in oklch, var(--dre-stack-ink) 12%, transparent);
  --dre-stack-soft: color-mix(in oklch, var(--dre-stack-ink) 5%, transparent);
  --dre-stack-mute: color-mix(in oklch, var(--dre-stack-ink) 64%, var(--dre-stack-bg));
  --dre-stack-faint: color-mix(in oklch, var(--dre-stack-ink) 44%, var(--dre-stack-bg));
  --dre-stack-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dre-stack-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dre-stack-out: cubic-bezier(.16, 1, .3, 1);
  --dre-stack-spring: linear(0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 25.3%, 0.849 31.5%, 0.937 38.1%, 0.968 41.8%, 0.991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);

  width: 100%;
  height: var(--dre-stack-h, 680px);
  container-type: inline-size; container-name: dre-stack;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 16px;
  background: var(--dre-stack-bg);
  color: var(--dre-stack-ink);
  font: 13px/1.45 var(--dre-stack-sans);
  accent-color: var(--dre-stack-accent);
  box-shadow: inset 0 0 0 1px var(--dre-stack-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, ol, ul) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(button:disabled, [aria-disabled=true]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :focus-visible { outline: 2px solid var(--dre-stack-accent); outline-offset: 2px; border-radius: 6px; }
  & .dre-stack__num { font-variant-numeric: tabular-nums; }
  & .dre-stack__scroll { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dre-stack-ink) 22%, transparent) transparent; }
}

.dre-stack__shell { height: 100%; display: grid; grid-template-columns: 208px minmax(0, 1fr); grid-template-areas: "side main"; }

/* ---------- sidebar */
.dre-stack__side {
  grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 4px; padding: 18px 12px 14px;
  background: var(--dre-stack-side); border-right: 1px solid var(--dre-stack-line);
}
.dre-stack__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 18px;
  & svg { width: 30px; height: 30px; flex: none; padding: 5px; border-radius: 8px; background: var(--dre-stack-ink); fill: none; stroke: var(--dre-stack-mid); stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 15px; font-weight: 760; letter-spacing: -.02em; line-height: 1.1; }
  & small { display: block; font-size: 11px; color: var(--dre-stack-mute); }
}
.dre-stack__navh { padding: 0 8px 4px; font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dre-stack-faint); }
.dre-stack__blds {
  display: grid; gap: 2px;
  & [role=tab] {
    display: grid; grid-template-columns: 26px minmax(0, 1fr); align-items: center; gap: 2px 10px; padding: 8px; border-radius: 10px;
    color: var(--dre-stack-mute); transition: background-color .2s, color .2s, box-shadow .2s;
    &:hover { background: var(--dre-stack-soft); color: var(--dre-stack-ink); }
    &[aria-selected=true] { background: var(--dre-stack-card); color: var(--dre-stack-ink); box-shadow: 0 1px 0 var(--dre-stack-line), 0 8px 18px -12px color-mix(in oklch, var(--dre-stack-ink) 45%, transparent); }
  }
  & .dre-stack__sil { grid-row: span 2; width: 26px; height: 30px; fill: color-mix(in oklch, currentColor 14%, transparent); stroke: currentColor; stroke-width: 1.3; }
  & [aria-selected=true] .dre-stack__sil { fill: color-mix(in oklch, var(--dre-stack-accent) 22%, transparent); stroke: var(--dre-stack-accent); }
  & [role=tab] > span { display: grid; min-width: 0; }
  & b { font-weight: 650; font-size: 13px; line-height: 1.2; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { font-size: 11px; color: var(--dre-stack-faint); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.dre-stack__legend {
  margin-top: auto; padding: 12px 8px 0; border-top: 1px solid var(--dre-stack-line); display: grid; gap: 8px; font-size: 11.5px; color: var(--dre-stack-mute);
  & h4 { margin: 0; font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dre-stack-faint); }
  & .dre-stack__ramp { height: 10px; border-radius: 3px; }
  & .dre-stack__rampl { display: flex; justify-content: space-between; font-size: 10.5px; color: var(--dre-stack-faint); font-variant-numeric: tabular-nums; }
  & ul { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 8px; }
  & li { display: flex; align-items: center; gap: 6px; min-width: 0; white-space: nowrap; }
  & li i { width: 9px; height: 9px; border-radius: 2px; flex: none; background: var(--c); }
  & .dre-stack__keys { display: flex; flex-wrap: wrap; gap: 4px 12px; }
  & .dre-stack__keys span { display: inline-flex; align-items: center; gap: 5px; }
  & .is-vac { width: 12px; height: 9px; border-radius: 2px; background: repeating-linear-gradient(135deg, var(--dre-stack-line) 0 2px, transparent 2px 4px); box-shadow: inset 0 0 0 1px var(--dre-stack-line); }
  & .is-ok { width: 13px; height: 13px; border-radius: 50%; display: grid; place-items: center; background: var(--dre-stack-ink); color: var(--dre-stack-card); }
  & .is-ok svg { width: 8px; height: 8px; fill: none; stroke: currentColor; stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; }
  & .is-risk { width: 12px; height: 9px; border-radius: 2px; background: repeating-linear-gradient(45deg, var(--dre-stack-ink) 0 1.2px, var(--dre-stack-card) 1.2px 3.4px); }
}

/* ---------- main */
.dre-stack__main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto auto minmax(0, 1fr); gap: 12px; padding: 16px 18px; }
.dre-stack__head {
  display: flex; align-items: end; justify-content: space-between; gap: 12px;
  & h2 { font-size: clamp(20px, 2.4cqi, 28px); font-weight: 780; letter-spacing: -.04em; line-height: 1.05; text-wrap: balance; }
}
.dre-stack__eyebrow { font-size: 11.5px; font-weight: 560; color: var(--dre-stack-mute); margin-bottom: 4px; text-wrap: pretty; }
.dre-stack__export {
  position: relative; overflow: hidden; display: inline-flex; align-items: center; gap: 8px; padding: 8px 14px; border-radius: 10px; flex: none;
  background: var(--dre-stack-ink); color: var(--dre-stack-bg); font-weight: 620; font-size: 12.5px;
  transition: scale .3s var(--dre-stack-out), background-color .2s;
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  &:hover { background: color-mix(in oklch, var(--dre-stack-ink) 86%, var(--dre-stack-accent)); }
  &:active { scale: .97; }
  &::after { content: ""; position: absolute; inset: auto 0 0 0; height: 3px; background: var(--dre-stack-mid); transform-origin: left; scale: 0 1; }
  &[aria-busy=true]::after { animation: dre-stack-progress 1.1s var(--dre-stack-out) forwards; }
}
@keyframes dre-stack-progress { to { scale: 1 1; } }

.dre-stack__kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); grid-template-rows: auto auto auto;
  border-radius: 14px; background: var(--dre-stack-card); box-shadow: inset 0 0 0 1px var(--dre-stack-line);
  & > div { grid-row: span 3; display: grid; grid-template-rows: subgrid; row-gap: 1px; min-width: 0; padding: 10px 16px 11px; }
  & > div + div { border-left: 1px solid var(--dre-stack-line); }
  & dt { font-size: 11px; font-weight: 600; color: var(--dre-stack-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { display: flex; align-items: center; gap: 8px; font-size: clamp(18px, 2.1cqi, 25px); font-weight: 760; letter-spacing: -.035em; line-height: 1.15; }
  & small { font-size: 11.5px; color: var(--dre-stack-faint); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .dre-stack__kpi--risk dd { color: var(--dre-stack-accent); }
}
.dre-stack__ring {
  width: 20px; height: 20px; border-radius: 50%; flex: none;
  background: conic-gradient(var(--dre-stack-ink) calc(var(--dre-stack-occ) * 1turn), var(--dre-stack-line) 0);
  mask: radial-gradient(closest-side, transparent 58%, #000 61%);
  transition: --dre-stack-occ 1.1s var(--dre-stack-out);
}

.dre-stack__bar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 16px; }
.dre-stack__seg {
  display: inline-flex; padding: 3px; gap: 2px; border-radius: 10px; background: var(--dre-stack-soft); box-shadow: inset 0 0 0 1px var(--dre-stack-line);
  & [role=radio] {
    padding: 5px 11px; border-radius: 8px; font-size: 12px; font-weight: 600; color: var(--dre-stack-mute); white-space: nowrap;
    transition: background-color .2s, color .2s, box-shadow .2s;
    &:hover { color: var(--dre-stack-ink); }
    &[aria-checked=true] { background: var(--dre-stack-card); color: var(--dre-stack-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dre-stack-ink) 18%, transparent); }
  }
}
.dre-stack__horizon {
  display: inline-flex; align-items: center; gap: 6px;
  & output { min-width: 3.4em; text-align: center; font-weight: 760; font-size: 15px; letter-spacing: -.02em; }
}
.dre-stack__hl { font-size: 12px; color: var(--dre-stack-mute); margin-right: 4px; }
.dre-stack__step {
  width: 28px; height: 28px; display: grid; place-items: center; border-radius: 8px; background: var(--dre-stack-card); box-shadow: inset 0 0 0 1px var(--dre-stack-line);
  transition: background-color .2s, scale .25s var(--dre-stack-out);
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; }
  &:hover:not(:disabled) { background: var(--dre-stack-soft); }
  &:active:not(:disabled) { scale: .92; }
  &:disabled { opacity: .38; }
}

/* ---------- body */
.dre-stack__body { min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 292px; gap: 14px; }
.dre-stack__planwrap {
  position: relative; min-height: 0; padding: 12px 14px 0; border-radius: 14px; background: var(--dre-stack-card); box-shadow: inset 0 0 0 1px var(--dre-stack-line);
  display: grid; grid-template-rows: minmax(0, 1fr) auto;
}
.dre-stack__plan { display: grid; grid-auto-rows: minmax(26px, 60px); align-content: end; gap: 3px; }
.dre-stack__floor {
  display: grid; grid-template-columns: 34px minmax(0, 1fr); align-items: stretch; gap: 8px;
  animation: dre-stack-rise .7s var(--dre-stack-out) both; animation-delay: calc(var(--i) * 38ms);
}
@keyframes dre-stack-rise {
  from { opacity: 0; translate: 0 14px; clip-path: inset(100% 0 0 0); }
  to { opacity: 1; translate: 0 0; clip-path: inset(0 0 0 0); }
}
.dre-stack__fl { align-self: center; font: 600 10.5px/1 var(--dre-stack-mono); color: var(--dre-stack-faint); text-align: right; }
.dre-stack__track { display: grid; gap: 3px; width: calc(var(--w) * 100%); margin-inline: auto; }

.dre-stack__suite {
  --fill: var(--dre-stack-even);
  container-type: size; container-name: dre-stack-suite;
  position: relative; min-width: 0; min-height: 0; border-radius: 5px; overflow: hidden; cursor: pointer;
  background-color: var(--fill); color: oklch(0.22 0.02 262);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dre-stack-ink) 10%, transparent);
  transition: background-color .55s var(--dre-stack-out), opacity .3s, filter .3s, box-shadow .2s, translate .3s var(--dre-stack-out);
  transition-delay: calc(var(--r, 0) * 22ms), 0s, 0s, 0s, 0s;
  & b { flex: none; max-width: 100%; font-size: 11.5px; font-weight: 650; line-height: 1.2; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { min-width: 0; font-size: 10.5px; line-height: 1.2; opacity: .72; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  &::after {
    content: ""; position: absolute; inset: 0; pointer-events: none; opacity: 0; transition: opacity .45s;
    background: repeating-linear-gradient(45deg, color-mix(in oklch, var(--dre-stack-ink) 55%, transparent) 0 1.3px, transparent 1.3px 5px);
  }
  &[data-risk]::after { opacity: .55; }
  &:hover { translate: 0 -1px; box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dre-stack-ink) 40%, transparent), 0 6px 14px -8px color-mix(in oklch, var(--dre-stack-ink) 60%, transparent); }
  &[aria-selected=true] { z-index: 1; box-shadow: inset 0 0 0 2px var(--dre-stack-ink), 0 8px 18px -8px color-mix(in oklch, var(--dre-stack-ink) 70%, transparent); }
  &:focus-visible { outline-offset: 1px; border-radius: 5px; }
}
.dre-stack[data-color=expiry] .dre-stack__suite {
  --fill: color-mix(in oklch, color-mix(in oklch, var(--dre-stack-near), var(--dre-stack-mid) calc(min(var(--t), .5) * 200%)), var(--dre-stack-far) calc(max(var(--t) - .5, 0) * 200%));
}
.dre-stack[data-color=rent] .dre-stack__suite {
  --fill: color-mix(in oklch, color-mix(in oklch, var(--dre-stack-even), var(--dre-stack-under) calc(max(-1 * var(--m), 0) * 100%)), var(--dre-stack-over) calc(max(var(--m), 0) * 100%));
}
.dre-stack[data-color=ind] .dre-stack__suite { --fill: var(--c); }
.dre-stack .dre-stack__suite.is-vac {
  --fill: var(--dre-stack-card);
  background-image: repeating-linear-gradient(135deg, color-mix(in oklch, var(--dre-stack-ink) 9%, transparent) 0 2px, transparent 2px 6px);
  color: var(--dre-stack-mute); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dre-stack-ink) 20%, transparent);
  & b { font-weight: 600; }
}
.dre-stack .dre-stack__suite.is-lobby {
  --fill: transparent; cursor: default; color: var(--dre-stack-faint);
  box-shadow: inset 0 0 0 1px var(--dre-stack-line);
  &:hover { translate: none; box-shadow: inset 0 0 0 1px var(--dre-stack-line); }
}
.dre-stack__badge {
  position: absolute; top: 4px; right: 4px; width: 15px; height: 15px; border-radius: 50%; display: grid; place-items: center;
  background: var(--dre-stack-ink); color: var(--dre-stack-card);
  & svg { width: 9px; height: 9px; fill: none; stroke: currentColor; stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; }
  @starting-style { scale: 0; }
  transition: scale .45s var(--dre-stack-spring);
}
.dre-stack__in { height: 100%; display: flex; flex-direction: column; justify-content: center; padding: 3px 8px; min-width: 0; }
.dre-stack__suite:has(.dre-stack__badge) .dre-stack__in { padding-right: 22px; }
.dre-stack__badge { top: 50%; margin-top: -7.5px; }
@container dre-stack-suite (max-height: 40px) {
  .dre-stack__in { flex-direction: row; align-items: baseline; justify-content: start; gap: 8px; }
}
@container dre-stack-suite (max-width: 130px) {
  .dre-stack__in { flex-direction: column; align-items: start; justify-content: center; gap: 0; }
}
@container dre-stack-suite (max-width: 130px) and (max-height: 40px) {
  .dre-stack__in small { display: none; }
}
@container dre-stack-suite (max-width: 44px) {
  .dre-stack__in { padding-inline: 2px; }
  .dre-stack__in b { font-size: 0; }
  .dre-stack__badge { display: none; }
}
.dre-stack__plan[data-hl] .dre-stack__suite:not([data-hl]):not(.is-lobby) { opacity: .28; filter: saturate(.3); }
.dre-stack__plan[data-hl] .dre-stack__suite[data-hl] { box-shadow: inset 0 0 0 2px var(--dre-stack-ink); }

.dre-stack__ground {
  height: 14px; margin: 3px 0 0 42px; border-top: 2px solid var(--dre-stack-ink);
  background: repeating-linear-gradient(135deg, var(--dre-stack-line) 0 1px, transparent 1px 6px);
}

/* ---------- aside: ladder + detail */
.dre-stack__aside { min-height: 0; display: grid; align-content: start; gap: 12px; }
.dre-stack__ladderbox, .dre-stack__detail { border-radius: 14px; background: var(--dre-stack-card); box-shadow: inset 0 0 0 1px var(--dre-stack-line); padding: 12px 12px 10px; }
.dre-stack__ph {
  display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-bottom: 8px;
  & h3 { font-size: 13px; font-weight: 700; letter-spacing: -.01em; }
  & span { font-size: 11px; color: var(--dre-stack-faint); }
}
.dre-stack__ladder {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto auto; gap: 1px 0;
  & li { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; }
}
.dre-stack__rung {
  grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: center; column-gap: 8px; padding: 3px 6px; border-radius: 7px;
  transition: background-color .2s;
  &:hover { background: var(--dre-stack-soft); }
  &[aria-pressed=true] { background: color-mix(in oklch, var(--dre-stack-ink) 9%, transparent); }
  & .y { font: 600 11px/1 var(--dre-stack-mono); color: var(--dre-stack-mute); }
  & .v { font-size: 11.5px; font-weight: 650; text-align: right; font-variant-numeric: tabular-nums; }
  & .c { font-size: 10.5px; color: var(--dre-stack-faint); text-align: right; font-variant-numeric: tabular-nums; min-width: 4.4em; }
  &.is-in .y { color: var(--dre-stack-accent); }
  &.is-in .y::before { content: ""; display: inline-block; width: 5px; height: 5px; margin-right: 5px; border-radius: 50%; background: currentColor; translate: 0 -1px; }
}
.dre-stack__lbar {
  position: relative; height: 12px; border-radius: 3px; background: var(--dre-stack-soft); overflow: hidden;
  & i {
    position: absolute; inset: 0; border-radius: 3px; transform-origin: left; scale: var(--s) 1;
    background: color-mix(in oklch, color-mix(in oklch, var(--dre-stack-near), var(--dre-stack-mid) calc(min(var(--t), .5) * 200%)), var(--dre-stack-far) calc(max(var(--t) - .5, 0) * 200%));
    transition: scale .7s var(--dre-stack-out); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dre-stack-ink) 14%, transparent);
    animation: dre-stack-grow .9s var(--dre-stack-out) both; animation-delay: calc(120ms + var(--i) * 45ms);
  }
}
@keyframes dre-stack-grow { from { scale: 0 1; } }

.dre-stack__detail { display: grid; gap: 10px; }
.dre-stack__dhead {
  display: grid; gap: 3px;
  & h3 { font-size: 16px; font-weight: 760; letter-spacing: -.025em; line-height: 1.15; text-wrap: balance; }
  & p { font-size: 11.5px; color: var(--dre-stack-mute); text-wrap: pretty; }
}
.dre-stack__chip { justify-self: start; display: inline-flex; align-items: center; gap: 6px; padding: 2px 8px 2px 6px; border-radius: 99px; font-size: 10.5px; font-weight: 650; background: color-mix(in oklab, var(--c) 45%, var(--dre-stack-card)); }
.dre-stack__chip i { width: 7px; height: 7px; border-radius: 50%; background: var(--c); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dre-stack-ink) 25%, transparent); }
.dre-stack__facts {
  display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 5px 12px; font-size: 12px;
  & dt { color: var(--dre-stack-mute); }
  & dd { text-align: right; font-weight: 600; font-variant-numeric: tabular-nums; }
  & dd small { font-weight: 500; color: var(--dre-stack-faint); }
}
.dre-stack__bullet {
  position: relative; height: 26px; margin-top: 2px;
  & .tr { position: absolute; inset: 9px 0; border-radius: 4px; background: var(--dre-stack-soft); }
  & .pass { position: absolute; top: 9px; height: 8px; left: 0; width: var(--p); border-radius: 4px; background: var(--dre-stack-ink); transition: width .6s var(--dre-stack-out); }
  & .mk { position: absolute; top: 4px; bottom: 4px; left: var(--m); width: 2px; margin-left: -1px; background: var(--dre-stack-accent); transition: left .6s var(--dre-stack-out); }
  & .lb { position: absolute; top: -3px; font-size: 10px; color: var(--dre-stack-faint); white-space: nowrap; }
}
.dre-stack__note { font-size: 11.5px; color: var(--dre-stack-mute); padding: 7px 9px; border-radius: 8px; background: var(--dre-stack-soft); text-wrap: pretty; }
.dre-stack__acts {
  display: flex; flex-wrap: wrap; gap: 6px;
  & button {
    position: relative; overflow: hidden; display: inline-flex; align-items: center; gap: 6px; padding: 6px 10px; border-radius: 8px; font-size: 12px; font-weight: 620;
    background: var(--dre-stack-card); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dre-stack-ink) 22%, transparent);
    transition: background-color .2s, color .2s, box-shadow .2s;
    &:hover:not(:disabled) { background: var(--dre-stack-soft); }
    &:disabled { opacity: .5; }
    & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  }
  & [aria-pressed=true] { background: var(--dre-stack-ink); color: var(--dre-stack-card); box-shadow: none; &:hover:not(:disabled) { background: var(--dre-stack-ink); } }
  & .is-primary { background: var(--dre-stack-accent); color: white; box-shadow: none; &:hover:not(:disabled) { background: color-mix(in oklch, var(--dre-stack-accent) 85%, black); } }
  & [aria-busy=true]::after { content: ""; position: absolute; inset: auto 0 0 0; height: 2px; background: currentColor; transform-origin: left; animation: dre-stack-progress .9s var(--dre-stack-out) forwards; scale: 0 1; }
}

/* ---------- tooltip + toast */
.dre-stack__tip {
  position: absolute; left: 0; top: 0; z-index: 20; pointer-events: none; max-width: 240px; padding: 8px 10px; border-radius: 10px;
  background: var(--dre-stack-ink); color: var(--dre-stack-bg); font-size: 11.5px; line-height: 1.4;
  box-shadow: 0 10px 24px -10px color-mix(in oklch, var(--dre-stack-ink) 70%, transparent);
  opacity: 0; transition: opacity .15s;
  & b { display: block; font-size: 12px; }
  & span { display: block; opacity: .75; font-variant-numeric: tabular-nums; }
  &[data-on] { opacity: 1; }
}
.dre-stack__toasts { position: absolute; right: 16px; bottom: 16px; z-index: 30; display: grid; justify-items: end; pointer-events: none; }
.dre-stack__toast {
  max-width: 340px; padding: 10px 14px; border-radius: 12px; background: var(--dre-stack-ink); color: var(--dre-stack-bg); font-size: 12.5px; text-wrap: pretty;
  box-shadow: 0 14px 30px -12px color-mix(in oklch, var(--dre-stack-ink) 70%, transparent);
  transition: opacity .25s, translate .45s var(--dre-stack-spring);
  @starting-style { opacity: 0; translate: 0 12px; }
  & b { color: var(--dre-stack-mid); }
  &[data-out] { opacity: 0; translate: 0 8px; }
}

/* scroll-linked shadow on the aside, inside its own scroller */
@supports (animation-timeline: scroll()) {
  .dre-stack__aside { animation: dre-stack-edge linear both; animation-timeline: scroll(self); animation-range: 0 40px; }
  @keyframes dre-stack-edge { from { box-shadow: inset 0 0 0 transparent; } to { box-shadow: inset 0 10px 10px -10px color-mix(in oklch, var(--dre-stack-ink) 30%, transparent); } }
}

/* ---------- responsive */
@container dre-stack (max-width: 960px) {
  .dre-stack__shell { grid-template-columns: 64px minmax(0, 1fr); }
  .dre-stack__side { padding: 14px 8px; align-items: center; }
  .dre-stack__lbl { display: none; }
  .dre-stack__brand { padding: 0 0 14px; }
  .dre-stack__blds [role=tab] { grid-template-columns: 26px; padding: 8px; }
  .dre-stack__blds [role=tab] > span { display: none; }
  .dre-stack__body { grid-template-columns: minmax(0, 1fr) 248px; }
  .dre-stack__hl { display: none; }
}
@container dre-stack (max-width: 760px) {
  .dre-stack__shell { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side" "main"; }
  .dre-stack__side { flex-direction: row; align-items: center; gap: 8px; padding: 8px 12px; border-right: 0; border-bottom: 1px solid var(--dre-stack-line); overflow-x: auto; scrollbar-width: none; }
  .dre-stack__brand { padding: 0; }
  .dre-stack__blds { grid-auto-flow: column; }
  .dre-stack__blds [role=tab] { grid-template-columns: 22px auto; padding: 5px 10px 5px 6px; }
  .dre-stack__blds [role=tab] > span { display: grid; }
  .dre-stack__blds .dre-stack__sil { width: 22px; height: 24px; }
  .dre-stack__blds small { display: none; }
  .dre-stack__main { overflow: auto; scrollbar-width: thin; grid-template-rows: none; align-content: start; padding: 14px 12px; }
  .dre-stack__kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); grid-template-rows: repeat(6, auto); }
  .dre-stack__kpis > div:nth-child(3) { border-left: 0; }
  .dre-stack__kpis > div:nth-child(n+3) { border-top: 1px solid var(--dre-stack-line); }
  .dre-stack__body { grid-template-columns: minmax(0, 1fr); }
  .dre-stack__body, .dre-stack__planwrap, .dre-stack__aside { min-height: auto; overflow: visible; }
  .dre-stack__planwrap { grid-template-rows: auto auto; padding-bottom: 0; }
  .dre-stack__plan { grid-auto-rows: 34px; }
  .dre-stack__hl { display: inline; }
}
@container dre-stack (max-width: 460px) {
  .dre-stack__head { flex-wrap: wrap; }
  .dre-stack__export span { display: none; }
  .dre-stack__export { padding: 8px; }
  .dre-stack__hl { display: none; }
  .dre-stack__seg [role=radio] { padding: 5px 8px; }
  .dre-stack__floor { grid-template-columns: 26px minmax(0, 1fr); gap: 4px; }
  .dre-stack__track { width: 100%; }
  .dre-stack__ground { margin-left: 30px; }
}

@media (prefers-reduced-motion: reduce) {
  .dre-stack .dre-stack__floor, .dre-stack .dre-stack__lbar i, .dre-stack .dre-stack__aside { animation: none; }
  .dre-stack .dre-stack__suite, .dre-stack .dre-stack__lbar i, .dre-stack .dre-stack__ring, .dre-stack .dre-stack__toast, .dre-stack .dre-stack__badge, .dre-stack .dre-stack__bullet * { transition-duration: .01ms; transition-delay: 0s; }
  .dre-stack .dre-stack__suite:hover { translate: none; }
  .dre-stack [aria-busy=true]::after { animation: none; scale: 1 1; }
}

