const bldList = $('.dre-stack__blds');
bldList.innerHTML = B.map((b, i) => {
  const l = leased(b).reduce((a, s) => a + s.area, 0) / b.nra;
  return '<button type="button" role="tab" data-view="' + i + '" aria-selected="' + (i === S.b) + '" tabindex="' + (i === S.b ? 0 : -1) + '" title="' + esc(b.name) + '">' +
    silhouette(b) + '<span><b>' + esc(b.name) + '</b><small>' + b.floors.length + ' floors · ' + (l * 100).toFixed(1) + '% leased</small></span></button>';
}).join('');
tabs(bldList, v => {
  S.b = +v; S.pin = null; S.sel = soonest(bld()); hideTip(tip);
  renderAll();
});

function legend() {
  const L = $('.dre-stack__legend');
  const keys = '<div class="dre-stack__keys"><span><i class="is-vac"></i>Vacant</span><span><i class="is-risk"></i>Expires by ' + S.hz + '</span><span><i class="is-ok">' + CHECK + '</i>Renewal likely</span></div>';
  if (S.color === 'expiry') {
    L.innerHTML = '<h4>Lease expiry</h4><div class="dre-stack__ramp" style="background:linear-gradient(90deg,var(--dre-stack-near),var(--dre-stack-mid),var(--dre-stack-far))"></div>' +
      '<div class="dre-stack__rampl"><span>' + ASOF.getFullYear() + '</span><span>2030</span><span>2035</span></div>' + keys;
  } else if (S.color === 'rent') {
    L.innerHTML = '<h4>Passing vs market</h4><div class="dre-stack__ramp" style="background:linear-gradient(90deg,var(--dre-stack-under),var(--dre-stack-even),var(--dre-stack-over))"></div>' +
      '<div class="dre-stack__rampl"><span>−12% under</span><span>at</span><span>+12% over</span></div>' + keys;
  } else {
    const present = [...new Set(leased(bld()).map(s => s.ind))];
    L.innerHTML = '<h4>Industry</h4><ul>' + present.map(k => '<li><i style="--c:var(--dre-stack-i-' + k + ')"></i>' + IND[k] + '</li>').join('') + '</ul>' + keys;
  }
}

/* ------------------------------------------------------------------ plan */
function suiteLabel(s) {
  if (s.vac) return 'Suite ' + s.sid + ', vacant, ' + sf(s.area) + ' square feet, asking ' + usd(s.ask);
  return 'Suite ' + s.sid + ', ' + s.name + ', ' + sf(s.area) + ' square feet, expires ' + expTxt(s.exp);
}
function renderPlan() {
  const b = bld(), n = b.floors.length;
  plan.setAttribute('aria-label', 'Stacking plan, ' + b.name + '. Arrow keys move between suites, Enter selects, Escape clears a pinned year.');
  plan.innerHTML = b.floors.map(([lv], fi) => {
    const list = b.suites.filter(s => s.lv === lv), plate = list[0].plate;
    const cols = list.map(s => s.area + 'fr').join(' ');
    return '<div class="dre-stack__floor" role="row" style="--i:' + (n - 1 - fi) + '"><span class="dre-stack__fl" role="rowheader">L' + lv + '</span>' +
      '<div class="dre-stack__track" style="--w:' + (plate / b.maxPlate).toFixed(4) + ';grid-template-columns:' + cols + '">' + list.map((s, j) => {
        if (s.lobby) return '<div class="dre-stack__suite is-lobby" role="gridcell" style="--r:' + (fi + j) + '"><span class="dre-stack__in"><b>Lobby</b><small>' + sf(s.area) + ' sf</small></span></div>';
        const st = s.vac ? '' : '--t:' + clamp(s.yrs / 9, 0, 1).toFixed(3) + ';--m:' + clamp((s.rent - s.mkt) / s.mkt / 0.12, -1, 1).toFixed(3) + ';--c:var(--dre-stack-i-' + s.ind + ');';
        return '<div class="dre-stack__suite' + (s.vac ? ' is-vac' : '') + '" role="gridcell" data-k="' + s.k + '" tabindex="-1" aria-selected="false" style="' + st + '--r:' + (fi + j * 2) + '" aria-label="' + esc(suiteLabel(s)) + '">' +
          '<span class="dre-stack__in"><b>' + (s.vac ? 'Vacant' : esc(s.name)) + '</b><small>' + sf(s.area) + ' sf · ' + (s.vac ? 'ask ' + usd(s.ask) : expTxt(s.exp)) + '</small></span></div>';
      }).join('') + '</div></div>';
  }).join('');
  syncPlan();
}
const suiteEls = () => $$('.dre-stack__suite[data-k]', plan);
function isRisk(s) { return s.t && s.exp.getFullYear() <= S.hz && !S.likely.has(s.t); }
function syncPlan() {
  suiteEls().forEach(el => {
    const s = byKey.get(el.dataset.k), on = s.k === S.sel;
    el.setAttribute('aria-selected', on ? 'true' : 'false'); el.tabIndex = on ? 0 : -1;
    el.toggleAttribute('data-risk', isRisk(s));
    const mark = s.vac ? S.listed.has(s.k) : S.likely.has(s.t);
    let bd = el.querySelector('.dre-stack__badge');
    if (mark && !bd) { bd = document.createElement('span'); bd.className = 'dre-stack__badge'; bd.innerHTML = s.vac ? TAG : CHECK; bd.title = s.vac ? 'Listed' : 'Renewal likely'; el.appendChild(bd); }
    else if (!mark && bd) bd.remove();
  });
  if (!plan.querySelector('[tabindex="0"]')) { const f = suiteEls()[0]; if (f) f.tabIndex = 0; }
  highlight();
}
let hoverY = null, hoverT = null;
function highlight() {
  const y = S.pin != null ? S.pin : hoverY;
  const match = s => y === 'vac' ? s.vac : y != null ? (s.t && Math.min(2035, s.exp.getFullYear()) === y) : hoverT ? s.t === hoverT : false;
  let any = false;
  suiteEls().forEach(el => { const m = match(byKey.get(el.dataset.k)); el.toggleAttribute('data-hl', m); any = any || m; });
  plan.toggleAttribute('data-hl', y != null || (!!hoverT && any));
}
plan.addEventListener('pointermove', e => {
  const el = e.target.closest('.dre-stack__suite[data-k]');
  if (!el) { hideTip(tip); if (hoverT) { hoverT = null; highlight(); } return; }
  const s = byKey.get(el.dataset.k);
  const html = s.vac
    ? '<b>Vacant · suite ' + s.sid + '</b><span>' + sf(s.area) + ' sf on level ' + s.lv + '</span><span>Asking ' + usd(s.ask) + '/sf · ' + usd0(s.ask * s.area) + ' a year</span>'
    : '<b>' + esc(s.name) + '</b><span>Suite ' + s.sid + ' · ' + sf(s.area) + ' sf</span><span>' + usd(s.rent) + '/sf passing · market ' + usd(s.mkt) + '</span><span>Expires ' + expTxt(s.exp) + ' · ' + s.yrs.toFixed(1) + ' yrs</span>';
  placeTip(tip, html, e.clientX, e.clientY);
  const t = s.t || null;
  if (t !== hoverT) { hoverT = t; if (S.pin == null && hoverY == null) highlight(); }
});
plan.addEventListener('pointerleave', () => { hideTip(tip); hoverT = null; highlight(); });
function select(k, focus) {
  const s = byKey.get(k); if (!s || s.lobby) return;
  S.sel = k; syncPlan(); renderDetail();
  if (focus) { const el = plan.querySelector('[data-k="' + k + '"]'); if (el) el.focus(); }
  const as = $('.dre-stack__aside');
  if (as.scrollHeight > as.clientHeight + 4) as.scrollTo({ top: detail.offsetTop - 8, behavior: RM ? 'auto' : 'smooth' });
}
plan.addEventListener('click', e => { const el = e.target.closest('.dre-stack__suite[data-k]'); if (el) select(el.dataset.k); });
plan.addEventListener('keydown', e => {
  const el = e.target.closest('.dre-stack__suite[data-k]'); if (!el) return;
  const k = e.key;
  if (k === 'Enter' || k === ' ') { e.preventDefault(); select(el.dataset.k); return; }
  if (k === 'Escape') { if (S.pin != null) { S.pin = null; syncLadder(); highlight(); } return; }
  const row = el.closest('.dre-stack__track'), inRow = $$('.dre-stack__suite[data-k]', row);
  const rows = $$('.dre-stack__track', plan), ri = rows.indexOf(row);
  let next = null;
  if (k === 'ArrowRight') next = inRow[inRow.indexOf(el) + 1];
  else if (k === 'ArrowLeft') next = inRow[inRow.indexOf(el) - 1];
  else if (k === 'Home') next = inRow[0];
  else if (k === 'End') next = inRow[inRow.length - 1];
  else if (k === 'ArrowUp' || k === 'ArrowDown') {
    const r = el.getBoundingClientRect(), cx = r.left + r.width / 2;
    for (let i = ri + (k === 'ArrowUp' ? -1 : 1); i >= 0 && i < rows.length && !next; i += (k === 'ArrowUp' ? -1 : 1)) {
      const c = $$('.dre-stack__suite[data-k]', rows[i]);
      next = c.sort((a, b) => { const ra = a.getBoundingClientRect(), rb = b.getBoundingClientRect(); return Math.abs(ra.left + ra.width / 2 - cx) - Math.abs(rb.left + rb.width / 2 - cx); })[0] || null;
    }
  } else return;
  e.preventDefault();
  if (next) { suiteEls().forEach(x => { x.tabIndex = -1; }); next.tabIndex = 0; next.focus(); }
});

/* ------------------------------------------------------------------ KPIs */
function kpis() {
  const b = bld(), l = leased(b);
  const leasedSf = l.reduce((a, s) => a + s.area, 0), vac = b.suites.filter(s => s.vac);
  const walt = l.reduce((a, s) => a + s.area * Math.max(0, s.yrs), 0) / leasedSf;
  const pass = l.reduce((a, s) => a + s.area * s.rent, 0), mkt = l.reduce((a, s) => a + s.area * s.mkt, 0);
  const exp = l.filter(s => s.exp.getFullYear() <= S.hz), risk = exp.filter(s => !S.likely.has(s.t));
  const riskSf = risk.reduce((a, s) => a + s.area, 0), likelySf = exp.reduce((a, s) => a + s.area, 0) - riskSf;
  K('addr').textContent = b.addr + ' · ' + b.kind + ' · ' + b.floors.length + ' floors · as of 1 Oct 2026';
  K('name').textContent = b.name;
  root.style.setProperty('--dre-stack-occ', (leasedSf / b.nra).toFixed(4));
  countTo(K('occ'), leasedSf / b.nra * 100, v => v.toFixed(1) + '%');
  K('occ2').textContent = 'of ' + sf(b.nra) + ' sf · ' + vac.length + ' vacant suite' + (vac.length === 1 ? '' : 's');
  countTo(K('walt'), walt, v => v.toFixed(1) + ' yrs');
  K('walt2').textContent = 'area-weighted across ' + new Set(l.map(s => s.t)).size + ' tenants';
  countTo(K('rev'), (mkt - pass) / pass * 100, v => (v >= 0 ? '+' : '−') + Math.abs(v).toFixed(1) + '%');
  K('rev2').textContent = usd(pass / leasedSf) + ' passing · ' + usd(mkt / leasedSf) + ' market';
  K('risk0').textContent = 'At risk by Dec ' + S.hz;
  countTo(K('risk'), riskSf, v => sf(v) + ' sf');
  K('risk2').textContent = risk.length + ' lease' + (risk.length === 1 ? '' : 's') + ' → ' + ((leasedSf - riskSf) / b.nra * 100).toFixed(1) + '% occupied';
  K('risk2').title = sf(likelySf) + ' sf also expires by then but is judged likely to renew';
  K('hz').textContent = S.hz;
  $$('.dre-stack__step').forEach(x => {
    const d = +x.dataset.d, off = (d < 0 && S.hz <= 2026) || (d > 0 && S.hz >= 2034);
    x.disabled = off; x.title = off ? (d < 0 ? 'Already at the current year' : 'The ladder ends at 2035') : (d < 0 ? 'One year earlier' : 'One year later');
  });
}

/* ------------------------------------------------------------------ ladder */
const ladder = $('.dre-stack__ladder');
function buckets() {
  const b = bld(), out = [];
  const vac = b.suites.filter(s => s.vac);
  out.push({ y: 'vac', label: 'Vacant', area: vac.reduce((a, s) => a + s.area, 0), list: vac });
  for (let y = 2026; y <= 2035; y++) {
    const list = leased(b).filter(s => Math.min(2035, s.exp.getFullYear()) === y);
    out.push({ y, label: y === 2035 ? '2035+' : String(y), area: list.reduce((a, s) => a + s.area, 0), list });
  }
  let cum = 0; out.forEach(o => { if (o.y !== 'vac') { cum += o.area; o.cum = cum; } });
  return out;
}
function renderLadder() {
  const b = bld(), bs = buckets(), max = Math.max(...bs.map(o => o.area));
  ladder.innerHTML = bs.map((o, i) => {
    const t = o.y === 'vac' ? 0 : clamp((o.y + 0.5 - 2026.75) / 9, 0, 1);
    const fill = o.y === 'vac' ? 'background:repeating-linear-gradient(135deg,var(--dre-stack-faint) 0 1.5px,transparent 1.5px 4px)' : '';
    return '<li><button type="button" class="dre-stack__rung" data-y="' + o.y + '" aria-pressed="false" aria-label="' + o.label + ': ' + sf(o.area) + ' square feet, ' + (o.area / b.nra * 100).toFixed(1) + ' percent of NRA">' +
      '<span class="y">' + o.label + '</span><span class="dre-stack__lbar"><i style="--s:' + (o.area / max).toFixed(4) + ';--t:' + t.toFixed(3) + ';--i:' + i + ';' + fill + '"></i></span>' +
      '<span class="v">' + (o.area / b.nra * 100).toFixed(1) + '%</span><span class="c">' + (o.y === 'vac' ? o.list.length + ' suites' : 'Σ ' + (o.cum / b.nra * 100).toFixed(0) + '%') + '</span></button></li>';
  }).join('');
  ladder._b = bs;
  syncLadder();
}
function syncLadder() {
  $$('.dre-stack__rung', ladder).forEach(r => {
    const y = r.dataset.y === 'vac' ? 'vac' : +r.dataset.y;
    r.setAttribute('aria-pressed', S.pin === y ? 'true' : 'false');
    r.classList.toggle('is-in', y !== 'vac' && y <= S.hz);
  });
}
ladder.addEventListener('click', e => {
  const r = e.target.closest('.dre-stack__rung'); if (!r) return;
  const y = r.dataset.y === 'vac' ? 'vac' : +r.dataset.y;
  S.pin = S.pin === y ? null : y;
  syncLadder(); highlight();
});
ladder.addEventListener('pointermove', e => {
  const r = e.target.closest('.dre-stack__rung');
  if (!r) { if (hoverY != null) { hoverY = null; highlight(); } hideTip(tip); return; }
  const y = r.dataset.y === 'vac' ? 'vac' : +r.dataset.y, o = ladder._b.find(x => x.y === y), b = bld();
  if (hoverY !== y) { hoverY = y; highlight(); }
  const names = [...new Set(o.list.map(s => s.vac ? 'Suite ' + s.sid : s.name))];
  placeTip(tip, '<b>' + (y === 'vac' ? 'Vacant today' : 'Expiring in ' + o.label) + '</b><span>' + sf(o.area) + ' sf · ' + (o.area / b.nra * 100).toFixed(1) + '% of NRA</span>' +
    (names.length ? '<span>' + esc(names.slice(0, 4).join(', ')) + (names.length > 4 ? ' +' + (names.length - 4) : '') + '</span>' : '<span>Nothing expires</span>'), e.clientX, e.clientY);
});
ladder.addEventListener('pointerleave', () => { hoverY = null; highlight(); hideTip(tip); });
root.addEventListener('keydown', e => { if (e.key === 'Escape' && S.pin != null && $('.dre-stack__aside').contains(e.target)) { S.pin = null; syncLadder(); highlight(); } });

/* ------------------------------------------------------------------ detail */
const detail = $('.dre-stack__detail');
function renderDetail() {
  const s = byKey.get(S.sel), b = bld();
  if (!s) { detail.innerHTML = ''; return; }
  if (s.vac) {
    const listed = S.listed.has(s.k), pack = S.pack.has(s.k);
    detail.innerHTML = '<div class="dre-stack__dhead"><span class="dre-stack__chip" style="--c:var(--dre-stack-line)"><i></i>Vacant</span><h3>Suite ' + s.sid + '</h3>' +
      '<p>Level ' + s.lv + ' · ' + sf(s.area) + ' sf, ' + Math.round(s.area / s.plate * 100) + '% of the floor plate</p></div>' +
      '<dl class="dre-stack__facts"><dt>Asking rent</dt><dd>' + usd(s.ask) + ' <small>/sf</small></dd><dt>Income at asking</dt><dd>' + usd0(s.ask * s.area) + ' <small>a year</small></dd>' +
      '<dt>Share of NRA</dt><dd>' + (s.area / b.nra * 100).toFixed(1) + '%</dd></dl>' +
      '<p class="dre-stack__note">Category A finish, ready for fit-out. ' + (s.lv === 1 ? 'Street frontage with its own entrance.' : 'Open plan with core-side meeting rooms.') + '</p>' +
      '<div class="dre-stack__acts"><button type="button" data-act="pack" aria-pressed="' + pack + '">' + (pack ? CHECK : '') + 'In marketing pack</button>' +
      '<button type="button" class="is-primary" data-act="list"' + (listed ? ' disabled title="Already listed with the leasing agents"' : '') + '>' + (listed ? 'Listed' : 'Create listing') + '</button></div>';
    return;
  }
  const ten = b.suites.filter(x => x.t === s.t), tenSf = ten.reduce((a, x) => a + x.area, 0);
  const lvls = [...new Set(ten.map(x => x.lv))].sort((a, c) => a - c);
  const notice = s.flags.includes('N'), likely = S.likely.has(s.t), drafted = S.drafted.has(s.t);
  const scale = Math.max(s.rent, s.mkt) * 1.2, rev = (s.mkt - s.rent) / s.rent * 100;
  detail.innerHTML = '<div class="dre-stack__dhead"><span class="dre-stack__chip" style="--c:var(--dre-stack-i-' + s.ind + ')"><i></i>' + IND[s.ind] + '</span><h3>' + esc(s.name) + '</h3>' +
    '<p>Suite ' + s.sid + ' · ' + (ten.length > 1 ? sf(tenSf) + ' sf across ' + (lvls.length > 1 ? 'levels ' + lvls[0] + '–' + lvls[lvls.length - 1] : 'level ' + lvls[0]) : 'level ' + s.lv) + '</p></div>' +
    '<dl class="dre-stack__facts"><dt>Suite area</dt><dd>' + sf(s.area) + ' sf</dd>' +
    '<dt>Passing rent</dt><dd>' + usd(s.rent) + ' <small>/sf · ' + usd0(s.rent * s.area) + ' pa</small></dd>' +
    '<dt>Market rent</dt><dd>' + usd(s.mkt) + ' <small>/sf · ' + (rev >= 0 ? '+' : '−') + Math.abs(rev).toFixed(1) + '%</small></dd>' +
    '<dt>Expiry</dt><dd>' + expTxt(s.exp) + ' <small>· ' + s.yrs.toFixed(1) + ' yrs</small></dd></dl>' +
    '<div class="dre-stack__bullet" style="--p:' + (s.rent / scale * 100).toFixed(1) + '%;--m:' + (s.mkt / scale * 100).toFixed(1) + '%" aria-hidden="true"><span class="tr"></span><span class="pass"></span><span class="mk"></span>' +
    '<span class="lb" style="left:0">passing</span><span class="lb" style="left:calc(var(--m) + 4px)">market</span></div>' +
    '<p class="dre-stack__note">' + esc(s.note) + '</p>' +
    '<div class="dre-stack__acts">' +
    (notice
      ? '<button type="button" data-act="likely" aria-pressed="false" disabled title="The tenant has served notice to vacate">Renewal likely</button>' +
        '<button type="button" class="is-primary" data-act="relet"' + (drafted ? ' disabled title="The re-letting brief has already gone to agents"' : '') + '>' + (drafted ? 'Brief sent' : 'Start re-letting') + '</button>'
      : '<button type="button" data-act="likely" aria-pressed="' + likely + '">' + (likely ? CHECK : '') + 'Renewal likely</button>' +
        '<button type="button" class="is-primary" data-act="draft"' + (drafted ? ' disabled title="A renewal proposal is already out for this lease"' : '') + '>' + (drafted ? 'Proposal sent' : 'Draft renewal') + '</button>') +
    '</div>';
}
detail.addEventListener('click', e => {
  const btn = e.target.closest('button[data-act]'); if (!btn || btn.disabled) return;
  const s = byKey.get(S.sel), act = btn.dataset.act;
  if (act === 'likely') {
    if (S.likely.has(s.t)) S.likely.delete(s.t); else S.likely.add(s.t);
    renderDetail(); syncPlan(); kpis();
    const nb = detail.querySelector('[data-act="likely"]'); if (nb) nb.focus();
  } else if (act === 'pack') {
    if (S.pack.has(s.k)) S.pack.delete(s.k); else S.pack.add(s.k);
    renderDetail(); detail.querySelector('[data-act="pack"]').focus();
    toast(S.pack.has(s.k) ? '<b>Suite ' + s.sid + '</b> added to the ' + esc(bld().name) + ' marketing pack' : 'Suite ' + s.sid + ' removed from the marketing pack');
  } else {
    btn.setAttribute('aria-busy', 'true'); btn.textContent = act === 'list' ? 'Listing…' : act === 'relet' ? 'Sending…' : 'Drafting…';
    setTimeout(() => {
      if (!root.isConnected) return;
      if (act === 'list') { S.listed.add(s.k); toast('<b>Suite ' + s.sid + ' listed</b> · ' + sf(s.area) + ' sf at ' + usd(s.ask) + '/sf with the leasing agents'); }
      else if (act === 'relet') { S.drafted.add(s.t); toast('<b>Re-letting brief sent</b> · ' + sf(bld().suites.filter(x => x.t === s.t).reduce((a, x) => a + x.area, 0)) + ' sf freed by ' + esc(s.name)); }
      else { S.drafted.add(s.t); toast('<b>Renewal drafted</b> · ' + esc(s.name) + ', 10 years at ' + usd(s.mkt) + '/sf from ' + MON[(s.exp.getMonth() + 1) % 12] + ' ' + (s.exp.getFullYear() + (s.exp.getMonth() === 11 ? 1 : 0))); }
      if (S.sel === s.k) renderDetail();
      syncPlan();
    }, RM ? 200 : 900);
  }
});

/* ------------------------------------------------------------------ toolbar */
radioGroup($('.dre-stack__seg'), v => { S.color = v; root.dataset.color = v; legend(); });
$$('.dre-stack__step').forEach(btn => btn.addEventListener('click', () => {
  S.hz = clamp(S.hz + +btn.dataset.d, 2026, 2034);
  kpis(); syncPlan(); syncLadder(); legend();
}));
const exp = $('.dre-stack__export');
exp.addEventListener('click', () => {
  if (exp.getAttribute('aria-busy') === 'true') return;
  exp.setAttribute('aria-busy', 'true'); exp.querySelector('span').textContent = 'Exporting…';
  setTimeout(() => {
    if (!root.isConnected) return;
    exp.removeAttribute('aria-busy'); exp.querySelector('span').textContent = 'Export plan';
    const b = bld();
    toast('<b>' + esc(b.name) + '</b> stacking plan exported · ' + b.floors.length + ' floors, ' + b.suites.filter(s => !s.lobby).length + ' suites, coloured by ' + ({ expiry: 'lease expiry', rent: 'rent vs market', ind: 'industry' })[S.color]);
  }, RM ? 200 : 1100);
});

function renderAll() { renderPlan(); kpis(); renderLadder(); renderDetail(); legend(); }
renderAll();

css:
.dre-arrears {
  /* re-theme with these four */
  --dre-arrears-bg: oklch(0.205 0.008 65);
  --dre-arrears-ink: oklch(0.94 0.012 85);
  --dre-arrears-ok: oklch(0.74 0.095 152);
  --dre-arrears-bad: oklch(0.69 0.155 30);
  /* derived */
  --dre-arrears-late: color-mix(in oklch, oklch(0.8 0.14 72) 85%, var(--dre-arrears-ink));
  --dre-arrears-panel: color-mix(in oklch, var(--dre-arrears-bg) 94%, var(--dre-arrears-ink));
  --dre-arrears-raise: color-mix(in oklch, var(--dre-arrears-bg) 88%, var(--dre-arrears-ink));
  --dre-arrears-line: color-mix(in oklch, var(--dre-arrears-ink) 11%, transparent);
  --dre-arrears-soft: color-mix(in oklch, var(--dre-arrears-ink) 6%, transparent);
  --dre-arrears-mute: color-mix(in oklch, var(--dre-arrears-ink) 62%, var(--dre-arrears-bg));
  --dre-arrears-faint: color-mix(in oklch, var(--dre-arrears-ink) 40%, var(--dre-arrears-bg));
  --dre-arrears-a1: color-mix(in oklch, var(--dre-arrears-late) 70%, var(--dre-arrears-ink));
  --dre-arrears-a2: var(--dre-arrears-late);
  --dre-arrears-a3: color-mix(in oklch, var(--dre-arrears-late) 45%, var(--dre-arrears-bad));
  --dre-arrears-a4: var(--dre-arrears-bad);
  --dre-arrears-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dre-arrears-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dre-arrears-out: cubic-bezier(.16, 1, .3, 1);
  --dre-arrears-spring: linear(0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 25.3%, 0.849 31.5%, 0.937 38.1%, 0.968 41.8%, 0.991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);

  width: 100%;
  height: var(--dre-arrears-h, 680px);
  container-type: inline-size; container-name: dre-arrears;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 16px;
  background: var(--dre-arrears-bg);
  color: var(--dre-arrears-ink);
  font: 13px/1.45 var(--dre-arrears-sans);
  accent-color: var(--dre-arrears-ok);
  color-scheme: dark;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h3, h4, p, dl, dd, ol, ul) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(button:disabled) { cursor: not-allowed; }
  & :where(input, select) { font: inherit; color: inherit; }
  & :where(svg) { display: block; overflow: visible; }
  & :focus-visible { outline: 2px solid var(--dre-arrears-ink); outline-offset: 2px; border-radius: 6px; }
  & [hidden] { display: none !important; }
  & .dre-arrears__num { font-variant-numeric: tabular-nums; }
  & .dre-arrears__scroll { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dre-arrears-ink) 22%, transparent) transparent; }
}

.dre-arrears__shell { height: 100%; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); gap: 12px; padding: 14px 16px 16px; }

/* ---------- top bar */
.dre-arrears__top { display: flex; align-items: center; gap: 10px 16px; flex-wrap: wrap; }
.dre-arrears__brand {
  display: flex; align-items: center; gap: 10px; margin-right: auto;
  & svg { width: 30px; height: 30px; flex: none; padding: 5px; border-radius: 9px; background: var(--dre-arrears-ok); fill: none; stroke: var(--dre-arrears-bg); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 15px; font-weight: 720; letter-spacing: -.02em; line-height: 1.15; }
  & small { display: block; font-size: 11px; color: var(--dre-arrears-mute); }
}
.dre-arrears__blds {
  display: flex; gap: 2px; padding: 3px; border-radius: 11px; background: var(--dre-arrears-soft); overflow-x: auto; scrollbar-width: none; max-width: 100%;
  & [role=tab] {
    padding: 5px 11px; border-radius: 8px; font-size: 12px; font-weight: 600; color: var(--dre-arrears-mute); white-space: nowrap;
    transition: background-color .2s, color .2s;
    &:hover { color: var(--dre-arrears-ink); }
    &[aria-selected=true] { background: var(--dre-arrears-ink); color: var(--dre-arrears-bg); }
  }
}
.dre-arrears__seg {
  display: inline-flex; gap: 2px; padding: 3px; border-radius: 11px; background: var(--dre-arrears-soft);
  & [role=radio] {
    padding: 5px 10px; border-radius: 8px; font-size: 12px; font-weight: 600; color: var(--dre-arrears-mute); white-space: nowrap; transition: background-color .2s, color .2s;
    &:hover { color: var(--dre-arrears-ink); }
    &[aria-checked=true] { background: var(--dre-arrears-raise); color: var(--dre-arrears-ink); box-shadow: inset 0 0 0 1px var(--dre-arrears-line); }
  }
}

/* ---------- KPIs */
.dre-arrears__kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px;
  & > div { min-width: 0; padding: 10px 14px 11px; border-radius: 12px; background: var(--dre-arrears-panel); box-shadow: inset 0 0 0 1px var(--dre-arrears-line); display: grid; gap: 1px; }
  & dt { font-size: 11px; font-weight: 600; color: var(--dre-arrears-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { font: 700 clamp(18px, 2.1cqi, 24px)/1.15 var(--dre-arrears-mono); letter-spacing: -.04em; }
  & small { font-size: 11.5px; color: var(--dre-arrears-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  & .is-bad dd { color: var(--dre-arrears-bad); }
  & .is-bad { background: color-mix(in oklch, var(--dre-arrears-bad) 7%, var(--dre-arrears-panel)); }
}

/* ---------- body */
.dre-arrears__body { min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 286px; gap: 12px; }
.dre-arrears__tablebox {
  position: relative; min-height: 0; min-width: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); overflow: hidden;
  border-radius: 14px; background: var(--dre-arrears-panel); box-shadow: inset 0 0 0 1px var(--dre-arrears-line);
}
.dre-arrears__tools { display: flex; align-items: center; gap: 8px 14px; flex-wrap: wrap; padding: 10px 12px 8px; border-bottom: 1px solid var(--dre-arrears-line); }
.dre-arrears__search {
  display: flex; align-items: center; gap: 6px; padding: 0 10px; height: 30px; border-radius: 9px; background: var(--dre-arrears-soft); box-shadow: inset 0 0 0 1px var(--dre-arrears-line);
  transition: box-shadow .2s;
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--dre-arrears-ink); }
  & svg { width: 14px; height: 14px; fill: none; stroke: var(--dre-arrears-mute); stroke-width: 2; stroke-linecap: round; }
  & input { width: 150px; border: 0; background: none; outline: none; font-size: 12.5px; }
  & input::placeholder { color: var(--dre-arrears-faint); }
}
.dre-arrears__legend {
  display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: 11px; color: var(--dre-arrears-mute);
  & span { display: inline-flex; align-items: center; gap: 6px; }
}
.dre-arrears__shown { margin-left: auto; font-size: 11px; color: var(--dre-arrears-faint); }

/* payment glyphs: colour and shape both carry the state */
.dre-arrears__g {
  display: block; width: 11px; height: 11px; border-radius: 3px; flex: none;
  &.is-ok { background: var(--dre-arrears-ok); }
  &.is-late { background: var(--dre-arrears-late); clip-path: polygon(0 0, 100% 0, 100% 100%, 30% 100%, 0 70%); }
  &.is-part { background: linear-gradient(to top, var(--dre-arrears-bad) 0 50%, transparent 50%); box-shadow: inset 0 0 0 1.5px var(--dre-arrears-bad); }
  &.is-miss { box-shadow: inset 0 0 0 1.5px var(--dre-arrears-bad); }
  &.is-na { height: 2px; width: 7px; margin: 4.5px 2px; border-radius: 1px; background: var(--dre-arrears-line); }
}

.dre-arrears__tablewrap { min-height: 0; position: relative; }
.dre-arrears__table {
  width: 100%; border-collapse: separate; border-spacing: 0; font-size: 12.5px;
  & th { position: sticky; top: 0; z-index: 2; background: var(--dre-arrears-panel); text-align: left; font-size: 11px; font-weight: 600; color: var(--dre-arrears-mute); padding: 8px 8px 7px; border-bottom: 1px solid var(--dre-arrears-line); white-space: nowrap; }
  & th button { display: inline-flex; align-items: center; gap: 4px; font-weight: 600; color: inherit; padding: 2px 4px; margin: -2px -4px; border-radius: 5px; transition: color .15s, background-color .15s; }
  & th button:hover { color: var(--dre-arrears-ink); background: var(--dre-arrears-soft); }
  & th button::after { content: ""; width: 7px; height: 7px; opacity: 0; transition: opacity .15s, rotate .3s var(--dre-arrears-out); background: currentColor; clip-path: polygon(50% 15%, 100% 85%, 0 85%); }
  & th[aria-sort=ascending] button, & th[aria-sort=descending] button { color: var(--dre-arrears-ink); }
  & th[aria-sort=ascending] button::after { opacity: 1; }
  & th[aria-sort=descending] button::after { opacity: 1; rotate: 180deg; }
  & .is-r { text-align: right; }
  & .is-r button { flex-direction: row-reverse; }
  & td { padding: 6px 8px; border-bottom: 1px solid color-mix(in oklch, var(--dre-arrears-ink) 6%, transparent); white-space: nowrap; vertical-align: middle; }
  & tbody tr { transition: background-color .2s; }
  & tbody tr:hover { background: var(--dre-arrears-soft); }
  & tbody tr:has(input:checked) { background: color-mix(in oklch, var(--dre-arrears-ok) 10%, transparent); }
  & tbody tr[data-open] { background: color-mix(in oklch, var(--dre-arrears-ink) 10%, transparent); box-shadow: inset 2px 0 0 var(--dre-arrears-ink); }
}
.dre-arrears__ck { width: 34px; padding-right: 0 !important; }
.dre-arrears__ck input, .dre-arrears__table td:first-child input { width: 15px; height: 15px; margin: 0; cursor: pointer; display: block; }
.dre-arrears__unit { font: 600 11.5px var(--dre-arrears-mono); color: var(--dre-arrears-mute); }
.dre-arrears__who {
  display: grid; text-align: left; border-radius: 6px; padding: 1px 4px; margin: -1px -4px; max-width: 190px;
  & b { font-weight: 620; overflow: hidden; text-overflow: ellipsis; }
  & small { font-size: 11px; color: var(--dre-arrears-faint); }
  &:hover b { text-decoration: underline; text-decoration-color: var(--dre-arrears-faint); text-underline-offset: 3px; }
}
.dre-arrears__rent { text-align: right; font: 500 12px var(--dre-arrears-mono); color: var(--dre-arrears-mute); }
.dre-arrears__hist { display: grid; grid-auto-flow: column; grid-auto-columns: 11px; gap: 4px; align-items: center; cursor: crosshair; }
.dre-arrears__hist .dre-arrears__g { animation: dre-arrears-pop .5s var(--dre-arrears-spring) both; animation-delay: calc(var(--c) * 30ms + var(--i, 0) * 9ms); }
@keyframes dre-arrears-pop { from { opacity: 0; scale: .2; } }
.dre-arrears__mons { display: grid; grid-auto-flow: column; grid-auto-columns: 11px; gap: 4px; margin-top: 3px; font: 600 9px/1 var(--dre-arrears-mono); color: var(--dre-arrears-faint); text-align: center; }
.dre-arrears__histh > span:first-child { display: block; }
.dre-arrears__bal {
  text-align: right;
  & b { display: block; font: 650 12.5px var(--dre-arrears-mono); }
  & small { font-size: 10.5px; color: var(--dre-arrears-faint); font-variant-numeric: tabular-nums; }
  &.is-owed b { color: var(--dre-arrears-bad); }
  &.is-zero b { color: var(--dre-arrears-faint); font-weight: 500; }
}
.dre-arrears__chip {
  display: inline-flex; align-items: center; gap: 5px; padding: 2px 8px; border-radius: 99px; font-size: 11px; font-weight: 600; background: var(--dre-arrears-soft); color: var(--dre-arrears-mute);
  &[data-s=plan] { background: color-mix(in oklch, var(--dre-arrears-ok) 18%, transparent); color: var(--dre-arrears-ok); }
  &[data-s=reminded] { background: color-mix(in oklch, var(--dre-arrears-late) 16%, transparent); color: var(--dre-arrears-late); }
  &[data-s=notice] { background: color-mix(in oklch, var(--dre-arrears-bad) 20%, transparent); color: color-mix(in oklch, var(--dre-arrears-bad) 70%, var(--dre-arrears-ink)); }
  &.is-flash { animation: dre-arrears-flash 1.2s var(--dre-arrears-out); }
}
@keyframes dre-arrears-flash { from { box-shadow: 0 0 0 4px color-mix(in oklch, var(--dre-arrears-ink) 30%, transparent); } }
.dre-arrears__empty { padding: 28px 16px; text-align: center; color: var(--dre-arrears-mute); }
.dre-arrears__empty button, .dre-arrears__reset { text-decoration: underline; text-underline-offset: 3px; color: var(--dre-arrears-ink); }

/* bulk bar: shown purely by :has() on the table's checked rows */
.dre-arrears__bulk {
  position: absolute; left: 50%; bottom: 12px; z-index: 4; display: flex; align-items: center; gap: 6px; padding: 6px 6px 6px 14px; border-radius: 12px;
  background: var(--dre-arrears-ink); color: var(--dre-arrears-bg); box-shadow: 0 16px 34px -14px #000;
  translate: -50% 140%; opacity: 0; visibility: hidden;
  transition: translate .45s var(--dre-arrears-out), opacity .25s, visibility 0s .45s;
  & b { font-size: 12px; margin-right: 6px; white-space: nowrap; }
  & button { padding: 6px 10px; border-radius: 8px; font-size: 12px; font-weight: 650; white-space: nowrap; background: color-mix(in oklch, var(--dre-arrears-bg) 12%, transparent); transition: background-color .15s; }
  & button:hover:not(:disabled) { background: color-mix(in oklch, var(--dre-arrears-bg) 22%, transparent); }
  & button:disabled { opacity: .45; }
  & .is-ghost { background: none; }
  & [aria-busy=true] { opacity: .7; }
}
.dre-arrears__tablebox:has(tbody input:checked) .dre-arrears__bulk { translate: -50% 0; opacity: 1; visibility: visible; transition: translate .5s var(--dre-arrears-spring), opacity .2s, visibility 0s; }

/* ---------- rail */
.dre-arrears__rail { min-height: 0; display: grid; align-content: start; gap: 12px; }
.dre-arrears__card { padding: 12px; border-radius: 14px; background: var(--dre-arrears-panel); box-shadow: inset 0 0 0 1px var(--dre-arrears-line); }
.dre-arrears__ph {
  display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-bottom: 10px;
  & h3 { font-size: 13px; font-weight: 680; }
  & span { font-size: 11px; color: var(--dre-arrears-faint); }
  & span[data-k] { font: 650 12px var(--dre-arrears-mono); color: var(--dre-arrears-bad); }
}
.dre-arrears__agebar {
  display: flex; gap: 2px; height: 14px; border-radius: 4px; overflow: hidden; margin-bottom: 10px; background: var(--dre-arrears-soft);
  & i { flex: var(--f) 1 0; min-width: 0; background: var(--c); transition: flex-grow .7s var(--dre-arrears-out), opacity .2s; transform-origin: left; animation: dre-arrears-grow .9s var(--dre-arrears-out) both; animation-delay: calc(var(--i) * 70ms); }
}
@keyframes dre-arrears-grow { from { scale: 0 1; } }
.dre-arrears__ages {
  display: grid; grid-template-columns: 1fr 1fr; gap: 6px;
  & button {
    display: grid; grid-template-columns: auto 1fr; gap: 0 7px; align-items: center; padding: 7px 8px; border-radius: 9px; box-shadow: inset 0 0 0 1px var(--dre-arrears-line);
    transition: background-color .2s, box-shadow .2s;
    &:hover { background: var(--dre-arrears-soft); }
    &[aria-pressed=true] { background: color-mix(in oklch, var(--c) 16%, transparent); box-shadow: inset 0 0 0 1.5px var(--c); }
    & i { grid-row: span 2; width: 8px; height: 26px; border-radius: 3px; background: var(--c); }
    & span { font-size: 11px; color: var(--dre-arrears-mute); }
    & b { font: 650 12.5px var(--dre-arrears-mono); }
    & small { grid-column: 2; font-size: 10.5px; color: var(--dre-arrears-faint); }
  }
}
.dre-arrears__chart {
  width: 100%; height: 168px; cursor: crosshair;
  & .grid { stroke: var(--dre-arrears-line); }
  & .axis { font: 500 9.5px var(--dre-arrears-mono); fill: var(--dre-arrears-faint); }
  & .area { fill: color-mix(in oklch, var(--dre-arrears-ok) 13%, transparent); animation: dre-arrears-fade 1s .3s both; }
  & .line { fill: none; stroke: var(--dre-arrears-ok); stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; stroke-dasharray: 1; stroke-dashoffset: 1; animation: dre-arrears-draw 1.2s var(--dre-arrears-out) forwards; }
  & .dot { fill: var(--dre-arrears-panel); stroke: var(--dre-arrears-ok); stroke-width: 1.6; transform-box: fill-box; transform-origin: center; animation: dre-arrears-pop .5s var(--dre-arrears-spring) both; animation-delay: calc(200ms + var(--i) * 60ms); transition: r .2s var(--dre-arrears-out), fill .2s; }
  & .dot.is-low { stroke: var(--dre-arrears-bad); fill: var(--dre-arrears-bad); }
  & .dot.is-hot { r: 5px; fill: var(--dre-arrears-ink); }
  & .xh { stroke: color-mix(in oklch, var(--dre-arrears-ink) 30%, transparent); opacity: 0; transition: opacity .15s; }
  & .tgt { stroke: var(--dre-arrears-late); stroke-dasharray: 3 3; }
  & .tgtl { font: 600 9.5px var(--dre-arrears-sans); fill: var(--dre-arrears-late); }
}
@keyframes dre-arrears-draw { to { stroke-dashoffset: 0; } }
@keyframes dre-arrears-fade { from { opacity: 0; } }

/* ---------- drawer */
.dre-arrears__drawer {
  position: absolute; z-index: 10; top: 0; right: 0; bottom: 0; width: min(380px, 100%); display: grid; grid-template-rows: auto minmax(0, 1fr);
  background: var(--dre-arrears-raise); box-shadow: -1px 0 0 var(--dre-arrears-line), -24px 0 48px -20px #000;
  transition: translate .5s var(--dre-arrears-out), opacity .3s;
  @starting-style { translate: 40px 0; opacity: 0; }
  &[data-out] { translate: 40px 0; opacity: 0; }
}
.dre-arrears__dhead {
  display: flex; align-items: start; justify-content: space-between; gap: 10px; padding: 16px 16px 12px; border-bottom: 1px solid var(--dre-arrears-line);
  & h3 { font-size: 17px; font-weight: 720; letter-spacing: -.02em; text-wrap: balance; }
}
.dre-arrears__eyebrow { font-size: 11px; color: var(--dre-arrears-mute); font-variant-numeric: tabular-nums; }
.dre-arrears__x {
  width: 30px; height: 30px; display: grid; place-items: center; border-radius: 8px; flex: none; transition: background-color .15s;
  &:hover { background: var(--dre-arrears-soft); }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
}
.dre-arrears__dbody { min-height: 0; padding: 14px 16px 18px; display: grid; align-content: start; gap: 14px; }
.dre-arrears__dbal {
  display: grid; gap: 8px;
  & .big { font: 700 26px/1 var(--dre-arrears-mono); letter-spacing: -.04em; }
  & .big.is-owed { color: var(--dre-arrears-bad); }
  & .meta { font-size: 11.5px; color: var(--dre-arrears-mute); text-wrap: pretty; }
  & .buckets { display: flex; gap: 2px; height: 8px; border-radius: 3px; overflow: hidden; background: var(--dre-arrears-soft); }
  & .buckets i { flex: var(--f) 1 0; background: var(--c); transition: flex-grow .6s var(--dre-arrears-out); }
}
.dre-arrears__dacts {
  display: flex; flex-wrap: wrap; gap: 6px;
  & button { padding: 6px 10px; border-radius: 8px; font-size: 12px; font-weight: 620; box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dre-arrears-ink) 22%, transparent); transition: background-color .15s; }
  & button:hover:not(:disabled) { background: var(--dre-arrears-soft); }
  & button:disabled { opacity: .45; }
}
.dre-arrears__pay {
  display: grid; gap: 8px; padding: 12px; border-radius: 12px; background: var(--dre-arrears-soft);
  & h4 { font-size: 12px; font-weight: 680; }
  & label { display: grid; gap: 4px; font-size: 11px; color: var(--dre-arrears-mute); }
  & select, & .dre-arrears__money { height: 32px; border-radius: 8px; border: 0; background: var(--dre-arrears-bg); box-shadow: inset 0 0 0 1px var(--dre-arrears-line); color: var(--dre-arrears-ink); font-size: 12.5px; padding: 0 8px; }
  & .dre-arrears__money { display: flex; align-items: center; gap: 4px; }
  & .dre-arrears__money i { font-style: normal; color: var(--dre-arrears-faint); }
  & .dre-arrears__money input { width: 100%; border: 0; background: none; outline: none; font: 600 12.5px var(--dre-arrears-mono); }
  & .dre-arrears__money:focus-within { box-shadow: inset 0 0 0 1.5px var(--dre-arrears-ink); }
  & .dre-arrears__money:has(input[aria-invalid=true]) { box-shadow: inset 0 0 0 1.5px var(--dre-arrears-bad); }
  & button[type=submit] { justify-self: start; padding: 7px 12px; border-radius: 8px; background: var(--dre-arrears-ink); color: var(--dre-arrears-bg); font-weight: 680; font-size: 12px; transition: scale .2s var(--dre-arrears-out); }
  & button[type=submit]:active { scale: .97; }
}
