/* collection-rate line: 85–105%, target 97% */
const svg = $('.dre-arrears__chart');
function monthly() {
  const xs = scope();
  return MONTHS.slice(12 - S.P).map(m0 => {
    const m1 = new Date(m0.getFullYear(), m0.getMonth() + 1, 1);
    let billed = 0, coll = 0;
    xs.forEach(x => x.L.forEach(e => { if (e.d >= m0 && e.d < m1) { if (e.amt > 0) billed += e.amt; else if (e.kind === 'pay') coll -= e.amt; } }));
    return { m0, billed, coll, rate: billed ? coll / billed : 1 };
  });
}
let chartData = [];
function chart() {
  const W = Math.max(200, Math.round(svg.getBoundingClientRect().width)), H = 168, pl = 30, pr = 6, pt = 8, pb = 18;
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  const d = chartData = monthly(), lo = 0.84, hi = 1.06;
  const x = i => pl + (W - pl - pr) * (d.length === 1 ? 0.5 : i / (d.length - 1));
  const y = v => pt + (H - pt - pb) * (1 - (clamp(v, lo, hi) - lo) / (hi - lo));
  let s = '';
  [0.85, 0.9, 0.95, 1, 1.05].forEach(t => { s += '<line class="grid" x1="' + pl + '" x2="' + (W - pr) + '" y1="' + y(t) + '" y2="' + y(t) + '"/><text class="axis" x="' + (pl - 5) + '" y="' + (y(t) + 3) + '" text-anchor="end">' + Math.round(t * 100) + '%</text>'; });
  s += '<line class="tgt" x1="' + pl + '" x2="' + (W - pr) + '" y1="' + y(0.97) + '" y2="' + y(0.97) + '"/><text class="tgtl" x="' + (W - pr) + '" y="' + (y(0.97) - 4) + '" text-anchor="end">target 97%</text>';
  d.forEach((p, i) => { if (d.length <= 6 || i % 2 === 0 || i === d.length - 1) s += '<text class="axis" x="' + x(i) + '" y="' + (H - 4) + '" text-anchor="middle">' + MON[p.m0.getMonth()] + '</text>'; });
  const pts = d.map((p, i) => x(i).toFixed(1) + ',' + y(p.rate).toFixed(1));
  s += '<path class="area" d="M' + pts.join('L') + 'L' + x(d.length - 1) + ',' + y(lo) + 'L' + x(0) + ',' + y(lo) + 'Z"/>';
  s += '<path class="line" pathLength="1" d="M' + pts.join('L') + '"/>';
  s += '<line class="xh" y1="' + pt + '" y2="' + (H - pb) + '"/>';
  d.forEach((p, i) => { s += '<circle class="dot' + (p.rate < 0.97 ? ' is-low' : '') + '" cx="' + x(i) + '" cy="' + y(p.rate) + '" r="3.2" style="--i:' + i + '"/>'; });
  svg.innerHTML = s;
  svg._x = x;
}
svg.addEventListener('pointermove', e => {
  if (!chartData.length) return;
  const r = svg.getBoundingClientRect(), W = svg.viewBox.baseVal.width, px = (e.clientX - r.left) * W / r.width;
  let bi = 0, bd = Infinity; chartData.forEach((p, i) => { const dd = Math.abs(svg._x(i) - px); if (dd < bd) { bd = dd; bi = i; } });
  const p = chartData[bi], xh = svg.querySelector('.xh');
  xh.setAttribute('x1', svg._x(bi)); xh.setAttribute('x2', svg._x(bi)); xh.style.opacity = 1;
