  placeTip(tip, '<b>' + mtxt(p.m0) + ' · ' + (p.rate * 100).toFixed(1) + '%</b><span>Billed ' + money(p.billed) + '</span><span>Collected ' + money(p.coll) + '</span>', e.clientX, e.clientY);
});
