let planFor = [];
bulk.addEventListener('click', e => {
  const b = e.target.closest('button[data-bulk]'); if (!b || b.disabled) return;
  const sel = selected(), owing = sel.filter(x => x.bal > 0.004);
  if (b.dataset.bulk === 'clear') { $$('input', tbody).forEach(i => { i.checked = false; }); syncSel(); all.focus(); return; }
  if (b.dataset.bulk === 'remind') {
    b.setAttribute('aria-busy', 'true'); b.textContent = 'Sending ' + owing.length + '…';
    setTimeout(() => {
      if (!root.isConnected) return;
      b.removeAttribute('aria-busy'); b.textContent = 'Send reminder';
      owing.forEach(x => { x.status = { s: 'reminded', d: ASOF }; renderRow(rowOf(x.id)); rowOf(x.id).querySelector('.dre-arrears__chip').classList.add('is-flash'); });
      toast(owing.length + ' reminder' + (owing.length === 1 ? '' : 's') + ' sent by email and text · ' + money(owing.reduce((s, x) => s + x.bal, 0)) + ' owed' + (sel.length > owing.length ? ' · ' + (sel.length - owing.length) + ' skipped, nothing owed' : ''));
    }, RM ? 150 : 850);
    return;
  }
  planFor = owing; S.terms = 3;
  $$('.dre-arrears__terms [role=radio]').forEach(r => { const on = r.dataset.v === '3'; r.setAttribute('aria-checked', on); r.tabIndex = on ? 0 : -1; });
  renderPlan();
  lastFocus = b; modal.hidden = false;
  $('.dre-arrears__terms [aria-checked=true]').focus();
});
function renderPlan() {
  const tot = planFor.reduce((s, x) => s + x.bal, 0);
  $('.dre-arrears__mnote').textContent = planFor.length + ' household' + (planFor.length === 1 ? '' : 's') + ' owing ' + money(tot) + '. Each instalment is paid on top of the normal rent, starting 1 November 2026.';
  $('.dre-arrears__plist').innerHTML = planFor.map(x => '<li><span>' + esc(x.name) + ' <small>' + x.unit + ' · owes ' + money(x.bal) + '</small></span><b>+' + money(Math.ceil(x.bal / S.terms)) + '/mo</b></li>').join('');
}
radioGroup($('.dre-arrears__terms'), v => { S.terms = +v; renderPlan(); });
function closeModal() { modal.hidden = true; if (lastFocus && lastFocus.isConnected) lastFocus.focus(); }
modal.addEventListener('click', e => {
  const b = e.target.closest('button[data-m]');
  if (!b) { if (e.target === modal) closeModal(); return; }
  if (b.dataset.m === 'ok') {
    planFor.forEach(x => { x.status = { s: 'plan', n: S.terms }; renderRow(rowOf(x.id)); rowOf(x.id).querySelector('.dre-arrears__chip').classList.add('is-flash'); rowOf(x.id).querySelector('input').checked = false; });
    toast('Payment plans offered to ' + planFor.length + ' household' + (planFor.length === 1 ? '' : 's') + ' over ' + S.terms + ' months');
    kpis(); syncSel();
  }
  closeModal();
});
root.addEventListener('keydown', e => {
  if (e.key === 'Tab' && !modal.hidden) {
    const f = $$('button:not(:disabled), [tabindex="0"]', modal).filter(b => b.tabIndex >= 0);
    const i = f.indexOf(document.activeElement);
    if (e.shiftKey && i <= 0) { e.preventDefault(); f[f.length - 1].focus(); }
    else if (!e.shiftKey && i === f.length - 1) { e.preventDefault(); f[0].focus(); }
    return;
  }
  if (e.key !== 'Escape') return;
  if (!modal.hidden) { e.preventDefault(); closeModal(); }
  else if (!drawer.hidden) { e.preventDefault(); closeDrawer(); }
});

/* ------------------------------------------------------------------ boot */
function refresh(animate) {
  applyOrder(false); filterRows(); kpis(); rail(); chart();
  if (animate) $$('tr', tbody).forEach(tr => { if (!tr.hidden) renderHist(tr, true); });
}
renderMonthsHead();
refresh(false);

css:
.dre-noi {
  /* re-theme with these four */
  --dre-noi-bg: oklch(0.195 0.018 168);
  --dre-noi-ink: oklch(0.95 0.016 98);
  --dre-noi-brass: oklch(0.8 0.105 84);
  --dre-noi-rose: oklch(0.7 0.115 22);
  /* derived */
  --dre-noi-sage: oklch(0.77 0.095 152);
  --dre-noi-panel: color-mix(in oklch, var(--dre-noi-bg) 93%, var(--dre-noi-ink));
  --dre-noi-raise: color-mix(in oklch, var(--dre-noi-bg) 86%, var(--dre-noi-ink));
  --dre-noi-line: color-mix(in oklch, var(--dre-noi-ink) 11%, transparent);
  --dre-noi-soft: color-mix(in oklch, var(--dre-noi-ink) 6%, transparent);
  --dre-noi-mute: color-mix(in oklch, var(--dre-noi-ink) 62%, var(--dre-noi-bg));
  --dre-noi-faint: color-mix(in oklch, var(--dre-noi-ink) 40%, var(--dre-noi-bg));
  --dre-noi-sub: color-mix(in oklch, var(--dre-noi-rose) 72%, var(--dre-noi-bg));
  --dre-noi-add: color-mix(in oklch, var(--dre-noi-sage) 80%, var(--dre-noi-bg));
  --dre-noi-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dre-noi-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dre-noi-out: cubic-bezier(.16, 1, .3, 1);
  --dre-noi-spring: linear(0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 25.3%, 0.849 31.5%, 0.937 38.1%, 0.968 41.8%, 0.991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);

  width: 100%;
  height: var(--dre-noi-h, 680px);
  container-type: inline-size; container-name: dre-noi;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 16px;
  background: var(--dre-noi-bg);
  color: var(--dre-noi-ink);
  font: 13px/1.45 var(--dre-noi-sans);
  accent-color: var(--dre-noi-brass);
  color-scheme: dark;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, ol) { margin: 0; padding: 0; }
  & :where(ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(svg) { display: block; overflow: visible; }
  & :focus-visible { outline: 2px solid var(--dre-noi-brass); outline-offset: 2px; border-radius: 6px; }
  & .dre-noi__num { font-variant-numeric: tabular-nums; }
  & .dre-noi__scroll { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dre-noi-ink) 20%, transparent) transparent; }
}

.dre-noi__shell { height: 100%; display: grid; grid-template-columns: 224px minmax(0, 1fr); grid-template-areas: "side main"; }

/* ---------- asset rail */
.dre-noi__side { grid-area: side; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 10px; padding: 16px 10px 12px; border-right: 1px solid var(--dre-noi-line); background: color-mix(in oklch, var(--dre-noi-bg) 82%, black); }
.dre-noi__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 6px;
  & svg { width: 30px; height: 30px; flex: none; padding: 5px; border-radius: 9px; background: var(--dre-noi-brass); fill: none; stroke: var(--dre-noi-bg); stroke-width: 1.9; stroke-linejoin: round; }
  & b { display: block; font-size: 15px; font-weight: 740; letter-spacing: -.02em; line-height: 1.15; }
  & small { display: block; font-size: 11px; color: var(--dre-noi-mute); }
}
.dre-noi__sorter {
  display: flex; align-items: center; gap: 4px; padding: 0 6px; font-size: 11px; color: var(--dre-noi-faint);
  & span { margin-right: auto; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; font-size: 10px; }
  & [role=radio] { padding: 3px 8px; border-radius: 6px; font-weight: 600; color: var(--dre-noi-mute); transition: background-color .2s, color .2s; }
  & [role=radio]:hover { color: var(--dre-noi-ink); }
  & [role=radio][aria-checked=true] { background: var(--dre-noi-soft); color: var(--dre-noi-ink); }
}
.dre-noi__assets { display: grid; align-content: start; gap: 2px; min-height: 0; }
.dre-noi__asset {
  display: grid; grid-template-columns: 22px minmax(0, 1fr) auto; grid-template-areas: "ic name name" "ic val chip"; gap: 1px 9px; align-items: center;
  padding: 7px 8px; border-radius: 10px; color: var(--dre-noi-mute); transition: background-color .2s, color .2s, box-shadow .2s;
  &:hover { background: var(--dre-noi-soft); color: var(--dre-noi-ink); }
  &[aria-selected=true] { background: var(--dre-noi-panel); color: var(--dre-noi-ink); box-shadow: inset 0 0 0 1px var(--dre-noi-line), inset 3px 0 0 var(--dre-noi-brass); }
  & svg { grid-area: ic; width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  &[aria-selected=true] svg { stroke: var(--dre-noi-brass); }
  & b { grid-area: name; font-size: 12.5px; font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .v { grid-area: val; font: 500 11px var(--dre-noi-mono); color: var(--dre-noi-faint); }
  & .c { grid-area: chip; font: 600 10.5px var(--dre-noi-mono); padding: 1px 5px; border-radius: 5px; }
  &.is-port { margin-bottom: 6px; }
}
.dre-noi__fav { color: var(--dre-noi-sage); background: color-mix(in oklch, var(--dre-noi-sage) 14%, transparent); }
.dre-noi__unf { color: var(--dre-noi-rose); background: color-mix(in oklch, var(--dre-noi-rose) 14%, transparent); }

/* ---------- main */
.dre-noi__main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); gap: 12px; padding: 16px 18px; }
.dre-noi__head {
  display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 10px 16px;
  & h2 { font-size: clamp(20px, 2.3cqi, 27px); font-weight: 760; letter-spacing: -.035em; line-height: 1.05; text-wrap: balance; }
}
.dre-noi__eyebrow { font-size: 11.5px; color: var(--dre-noi-mute); margin-bottom: 4px; font-variant-numeric: tabular-nums; }
.dre-noi__ctrls { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.dre-noi__seg {
  display: inline-flex; gap: 2px; padding: 3px; border-radius: 10px; background: var(--dre-noi-soft);
  & [role=radio] { padding: 4px 10px; border-radius: 7px; font-size: 12px; font-weight: 640; color: var(--dre-noi-mute); transition: background-color .2s, color .2s; }
  & [role=radio]:hover { color: var(--dre-noi-ink); }
  & [role=radio][aria-checked=true] { background: var(--dre-noi-ink); color: var(--dre-noi-bg); }
}
.dre-noi__switch {
  display: inline-flex; align-items: center; gap: 7px; padding: 5px 10px 5px 6px; border-radius: 10px; font-size: 12px; font-weight: 620; color: var(--dre-noi-mute);
  transition: color .2s;
  & i { position: relative; width: 28px; height: 16px; border-radius: 99px; background: var(--dre-noi-line); transition: background-color .25s; }
  & i::after { content: ""; position: absolute; top: 2px; left: 2px; width: 12px; height: 12px; border-radius: 50%; background: var(--dre-noi-ink); transition: translate .35s var(--dre-noi-spring); }
  &[aria-checked=true] { color: var(--dre-noi-ink); }
  &[aria-checked=true] i { background: var(--dre-noi-brass); }
  &[aria-checked=true] i::after { translate: 12px 0; background: var(--dre-noi-bg); }
}
.dre-noi__dl {
  position: relative; overflow: hidden; display: inline-flex; align-items: center; gap: 7px; padding: 6px 11px; border-radius: 10px; font-size: 12px; font-weight: 640;
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dre-noi-ink) 22%, transparent); transition: background-color .2s;
  &:hover { background: var(--dre-noi-soft); }
  & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  &::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: var(--dre-noi-brass); transform-origin: left; scale: 0 1; }
  &[aria-busy=true]::after { animation: dre-noi-bar 1s var(--dre-noi-out) forwards; }
}
@keyframes dre-noi-bar { to { scale: 1 1; } }

.dre-noi__kpis {
  display: grid; grid-template-columns: 1.25fr repeat(3, minmax(0, 1fr)); gap: 10px;
  & > div { min-width: 0; padding: 10px 14px; border-radius: 12px; background: var(--dre-noi-panel); box-shadow: inset 0 0 0 1px var(--dre-noi-line); display: grid; gap: 1px; }
  & dt { font-size: 11px; font-weight: 600; color: var(--dre-noi-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { font-size: clamp(18px, 2cqi, 24px); font-weight: 720; letter-spacing: -.035em; line-height: 1.15; }
  & small { font-size: 11.5px; color: var(--dre-noi-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  & small b { font-weight: 650; }
  & .is-hero { background: linear-gradient(135deg, color-mix(in oklch, var(--dre-noi-brass) 16%, var(--dre-noi-panel)), var(--dre-noi-panel) 70%); }
  & .is-hero dd { color: var(--dre-noi-brass); }
}

.dre-noi__body {
  min-height: 0; display: grid; gap: 12px;
  grid-template-columns: minmax(0, 1fr) 300px; grid-template-rows: minmax(0, 1.3fr) minmax(0, 1fr);
  grid-template-areas: "bridge lines" "trend lines";
}
.dre-noi__panel { min-height: 0; min-width: 0; border-radius: 14px; background: var(--dre-noi-panel); box-shadow: inset 0 0 0 1px var(--dre-noi-line); padding: 11px 12px 8px; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.dre-noi__bridge { grid-area: bridge; }
.dre-noi__trendbox { grid-area: trend; }
.dre-noi__lines { grid-area: lines; padding: 10px 6px 6px; }
.dre-noi__ph {
  display: flex; align-items: baseline; justify-content: space-between; gap: 6px 12px; flex-wrap: wrap; margin-bottom: 4px; padding-inline: 2px;
  & h3 { font-size: 13px; font-weight: 680; text-wrap: balance; }
  & > span { font-size: 11px; color: var(--dre-noi-faint); }
}
.dre-noi__keys {
  display: flex; gap: 4px 12px; flex-wrap: wrap; font-size: 11px; color: var(--dre-noi-mute);
  & span { display: inline-flex; align-items: center; gap: 5px; }
  & i { width: 9px; height: 9px; border-radius: 2px; }
  & .is-tot { background: var(--dre-noi-brass); }
  & .is-add { background: var(--dre-noi-add); }
  & .is-sub { background: var(--dre-noi-sub); }
  & .is-bud { box-shadow: inset 0 0 0 1.2px var(--dre-noi-ink); border-radius: 1px; background: repeating-linear-gradient(90deg, transparent 0 2px, var(--dre-noi-bg) 2px 3px); }
}
.dre-noi:has(.dre-noi__switch[aria-checked=false]) .dre-noi__bkey { opacity: .3; }

/* waterfall */
.dre-noi__wf {
  width: 100%; height: 100%; min-height: 150px;
  & .grid { stroke: var(--dre-noi-line); }
  & .axis { font: 500 9.5px var(--dre-noi-mono); fill: var(--dre-noi-faint); }
  & .cat { font: 600 10px var(--dre-noi-sans); fill: var(--dre-noi-mute); }
  & .cat.is-sel { fill: var(--dre-noi-ink); }
  & .val { font: 600 9.5px var(--dre-noi-mono); fill: var(--dre-noi-ink); }
  & .conn { stroke: color-mix(in oklch, var(--dre-noi-ink) 28%, transparent); stroke-dasharray: 2 2; }
  & .bar { cursor: pointer; transition: opacity .25s, filter .25s; }
  & .bar rect.b { rx: 2.5px; }
  & .bar.is-tot rect.b { fill: var(--dre-noi-brass); }
  & .bar.is-add rect.b { fill: var(--dre-noi-add); }
  & .bar.is-sub rect.b { fill: var(--dre-noi-sub); }
  & .bar rect.hit { fill: transparent; }
  & .bar:hover rect.b { filter: brightness(1.15); }
  & .bar.is-sel rect.b { stroke: var(--dre-noi-ink); stroke-width: 1.5; }
  & .bar:focus { outline: none; }
  & .bar:focus-visible rect.hit { fill: color-mix(in oklch, var(--dre-noi-brass) 12%, transparent); stroke: var(--dre-noi-brass); stroke-width: 1.5; }
  &.is-tight .val { font-size: 8.5px; letter-spacing: -.03em; }
  & .bud { fill: none; stroke: var(--dre-noi-ink); stroke-width: 1.2; stroke-dasharray: 3 2; opacity: .8; pointer-events: none; transition: opacity .3s; }
}
.dre-noi:has(.dre-noi__switch[aria-checked=false]) .dre-noi__wf .bud { opacity: 0; }
.dre-noi__wf:has(.bar:hover) .bar:not(:hover) { opacity: .55; }

/* trend */
.dre-noi__trend {
  width: 100%; height: 100%; min-height: 110px; cursor: crosshair;
  & .grid { stroke: var(--dre-noi-line); }
  & .axis { font: 500 9.5px var(--dre-noi-mono); fill: var(--dre-noi-faint); }
  & .mb { fill: color-mix(in oklch, var(--dre-noi-ink) 26%, var(--dre-noi-panel)); transform-box: fill-box; transform-origin: 50% 100%; animation: dre-noi-rise .7s var(--dre-noi-out) both; animation-delay: calc(var(--i) * 30ms); transition: fill .2s; }
  & .mb.is-in { fill: var(--dre-noi-brass); }
  & .mb.is-neg { transform-origin: 50% 0; }
  & .mb.is-hot { fill: var(--dre-noi-ink); }
  & .bl { fill: none; stroke: var(--dre-noi-ink); stroke-width: 1.4; stroke-dasharray: 4 3; opacity: .75; transition: opacity .3s; }
  & .xh { stroke: color-mix(in oklch, var(--dre-noi-ink) 30%, transparent); opacity: 0; transition: opacity .15s; }
  & .zero { stroke: color-mix(in oklch, var(--dre-noi-ink) 35%, transparent); }
}
.dre-noi:has(.dre-noi__switch[aria-checked=false]) .dre-noi__trend .bl { opacity: 0; }
@keyframes dre-noi-rise { from { scale: 1 0; } }

/* line items: one grid, every row on subgrid columns */
.dre-noi__lhead, .dre-noi__opt { display: grid; grid-template-columns: minmax(0, 1fr) 54px 52px 48px; gap: 4px; align-items: baseline; }
.dre-noi__lhead { padding: 0 8px 6px; font-size: 10.5px; font-weight: 600; color: var(--dre-noi-faint); border-bottom: 1px solid var(--dre-noi-line); & span:not(:first-child) { text-align: right; } }
.dre-noi__list { min-height: 0; padding-top: 4px; display: grid; align-content: start; gap: 1px; }
.dre-noi__opt {
  padding: 4px 8px; border-radius: 7px; font-size: 12px; cursor: pointer; transition: background-color .2s;
  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .n { color: var(--dre-noi-mute); }
  & .a, & .bu, & .vr { font: 500 11px var(--dre-noi-mono); text-align: right; }
  & .bu { color: var(--dre-noi-faint); }
  & .vr { font-weight: 600; }
  &:hover { background: var(--dre-noi-soft); }
  &[aria-selected=true] { background: color-mix(in oklch, var(--dre-noi-brass) 15%, transparent); box-shadow: inset 2px 0 0 var(--dre-noi-brass); }
  &[aria-selected=true] .n { color: var(--dre-noi-ink); }
  &.is-sum { margin-top: 3px; padding-block: 6px; border-top: 1px solid var(--dre-noi-line); border-radius: 0 0 7px 7px; }
  &.is-sum .n, &.is-sum .a { color: var(--dre-noi-ink); font-weight: 700; }
  &.is-noi .a { color: var(--dre-noi-brass); }
}
.dre-noi__vf { color: var(--dre-noi-sage); }
.dre-noi__vu { color: var(--dre-noi-rose); }
.dre-noi:has(.dre-noi__switch[aria-checked=false]) .dre-noi__bcol,
.dre-noi:has(.dre-noi__switch[aria-checked=false]) .dre-noi__opt .bu,
.dre-noi:has(.dre-noi__switch[aria-checked=false]) .dre-noi__opt .vr { opacity: .25; }

/* ---------- tooltip + toast */
.dre-noi__tip {
  position: absolute; left: 0; top: 0; z-index: 30; pointer-events: none; min-width: 170px; max-width: 250px; padding: 8px 10px; border-radius: 10px;
  background: var(--dre-noi-ink); color: var(--dre-noi-bg); font-size: 11.5px; line-height: 1.45; box-shadow: 0 12px 28px -10px #000;
  opacity: 0; transition: opacity .15s;
  & b { display: block; font-size: 12px; }
  & span { display: flex; justify-content: space-between; gap: 12px; font-variant-numeric: tabular-nums; }
  & em { font-style: normal; opacity: .65; }
  &[data-on] { opacity: 1; }
}
.dre-noi__toasts { position: absolute; right: 16px; bottom: 16px; z-index: 40; pointer-events: none; }
.dre-noi__toast {
  max-width: 340px; padding: 10px 14px; border-radius: 12px; background: var(--dre-noi-brass); color: var(--dre-noi-bg); font-size: 12.5px; font-weight: 540; text-wrap: pretty;
  box-shadow: 0 16px 30px -12px #000; transition: opacity .25s, translate .45s var(--dre-noi-spring);
  @starting-style { opacity: 0; translate: 0 12px; }
  &[data-out] { opacity: 0; translate: 0 8px; }
}

/* ---------- responsive */
@container dre-noi (max-width: 1040px) {
  .dre-noi__body { grid-template-columns: minmax(0, 1fr) 262px; }
  .dre-noi__lhead, .dre-noi__opt { grid-template-columns: minmax(0, 1fr) 56px 50px; }
