/* ------------------------------------------------------------------ line list */
const list = $('.dre-noi__list');
list.innerHTML = L.map(l => '<li class="dre-noi__opt' + (l.sum ? ' is-sum' : '') + (l.k === 'noi' ? ' is-noi' : '') + '" role="option" data-k="' + l.k + '" aria-selected="false" tabindex="-1">' +
