@property --dre-work-p { syntax: "<number>"; inherits: false; initial-value: 0; }

.dre-work {
  /* re-theme with these four */
  --dre-work-bg: oklch(0.972 0.006 250);
  --dre-work-ink: oklch(0.24 0.025 258);
  --dre-work-signal: oklch(0.88 0.16 100);
  --dre-work-bad: oklch(0.58 0.19 27);
  /* derived */
  --dre-work-ok: oklch(0.62 0.13 152);
  --dre-work-warn: oklch(0.72 0.15 62);
  --dre-work-card: color-mix(in oklch, var(--dre-work-bg) 30%, white);
  --dre-work-railbg: var(--dre-work-ink);
  --dre-work-line: color-mix(in oklch, var(--dre-work-ink) 11%, transparent);
  --dre-work-soft: color-mix(in oklch, var(--dre-work-ink) 5%, transparent);
  --dre-work-mute: color-mix(in oklch, var(--dre-work-ink) 64%, var(--dre-work-bg));
  --dre-work-faint: color-mix(in oklch, var(--dre-work-ink) 42%, var(--dre-work-bg));
  --dre-work-p1: var(--dre-work-bad);
  --dre-work-p2: var(--dre-work-warn);
  --dre-work-p3: oklch(0.6 0.1 240);
  --dre-work-p4: color-mix(in oklch, var(--dre-work-ink) 45%, var(--dre-work-bg));
  --dre-work-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dre-work-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dre-work-out: cubic-bezier(.16, 1, .3, 1);
  --dre-work-spring: linear(0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 25.3%, 0.849 31.5%, 0.937 38.1%, 0.968 41.8%, 0.991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);

  width: 100%;
  height: var(--dre-work-h, 680px);
  container-type: inline-size; container-name: dre-work;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 16px;
  background: var(--dre-work-bg);
  color: var(--dre-work-ink);
  font: 13px/1.45 var(--dre-work-sans);
  accent-color: var(--dre-work-ink);
  box-shadow: inset 0 0 0 1px var(--dre-work-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, dl, dd, ol, ul) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(button:disabled) { cursor: not-allowed; }
  & :where(select, textarea) { font: inherit; color: inherit; }
  & :where(svg) { display: block; overflow: visible; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--dre-work-ink); outline-offset: 2px; border-radius: 6px; }
  & .dre-work__num { font-variant-numeric: tabular-nums; }
  & .dre-work__scroll { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dre-work-ink) 22%, transparent) transparent; }
}

.dre-work__shell { height: 100%; display: grid; grid-template-columns: 72px minmax(0, 1fr); }

/* ---------- dark icon rail */
.dre-work__rail { display: flex; flex-direction: column; align-items: center; gap: 14px; padding: 16px 8px 14px; background: var(--dre-work-railbg); color: color-mix(in oklch, var(--dre-work-bg) 70%, var(--dre-work-ink)); border-radius: 16px 0 0 16px; }
.dre-work__mark svg { width: 34px; height: 34px; padding: 7px; border-radius: 10px; background: var(--dre-work-signal); fill: none; stroke: var(--dre-work-ink); stroke-width: 1.9; stroke-linejoin: round; }
.dre-work__views {
  display: grid; gap: 6px; width: 100%;
  & [role=tab] {
    display: grid; justify-items: center; gap: 3px; padding: 8px 2px 6px; border-radius: 10px; font-size: 10px; font-weight: 620; letter-spacing: .01em;
    transition: background-color .2s, color .2s;
    &:hover { background: color-mix(in oklch, var(--dre-work-bg) 10%, transparent); color: var(--dre-work-bg); }
    &[aria-selected=true] { background: color-mix(in oklch, var(--dre-work-bg) 14%, transparent); color: var(--dre-work-signal); }
  }
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
}
.dre-work__me { margin-top: auto; width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; font-weight: 700; background: color-mix(in oklch, var(--dre-work-bg) 18%, transparent); color: var(--dre-work-bg); }

/* ---------- main */
.dre-work__main { min-width: 0; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto auto minmax(0, 1fr); gap: 12px; padding: 16px 18px; }
.dre-work__head {
  display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 10px 16px;
  & h2 { font-size: clamp(20px, 2.4cqi, 28px); font-weight: 780; letter-spacing: -.04em; line-height: 1.05; text-wrap: balance; }
}
.dre-work__eyebrow { font-size: 11.5px; color: var(--dre-work-mute); margin-bottom: 4px; text-wrap: pretty; }
.dre-work__clock {
  display: flex; align-items: center; gap: 6px; padding: 5px 5px 5px 12px; border-radius: 12px; background: var(--dre-work-ink); color: var(--dre-work-bg);
  & .dre-work__now { display: grid; line-height: 1.1; margin-right: 6px; min-width: 76px; }
  & b { font: 700 18px var(--dre-work-mono); letter-spacing: -.03em; color: var(--dre-work-signal); }
  & small { font-size: 10.5px; opacity: .7; }
}
.dre-work__adv, .dre-work__play {
  height: 30px; padding: 0 10px; border-radius: 8px; font: 650 12px var(--dre-work-mono); background: color-mix(in oklch, var(--dre-work-bg) 12%, transparent);
  transition: background-color .15s, scale .2s var(--dre-work-out);
  &:hover { background: color-mix(in oklch, var(--dre-work-bg) 22%, transparent); }
  &:active { scale: .94; }
}
.dre-work__play {
  width: 30px; padding: 0; display: grid; place-items: center;
  & svg { grid-area: 1 / 1; width: 14px; height: 14px; fill: currentColor; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; transition: opacity .2s, scale .3s var(--dre-work-out); }
  & .is-pause { fill: none; opacity: 0; scale: .4; }
  &[aria-pressed=true] { background: var(--dre-work-signal); color: var(--dre-work-ink); }
  &[aria-pressed=true] .is-play { opacity: 0; scale: .4; }
  &[aria-pressed=true] .is-pause { opacity: 1; scale: 1; }
}
.dre-work__tick { animation: dre-work-tick .45s var(--dre-work-out); }
@keyframes dre-work-tick { from { translate: 0 -6px; opacity: .3; } }

.dre-work__kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px;
  & > div { min-width: 0; display: grid; gap: 1px; padding: 10px 14px; border-radius: 12px; background: var(--dre-work-card); box-shadow: inset 0 0 0 1px var(--dre-work-line); position: relative; overflow: hidden; }
  & > div::before { content: ""; position: absolute; left: 0; top: 10px; bottom: 10px; width: 3px; border-radius: 0 3px 3px 0; background: transparent; }
  & .is-warn::before { background: var(--dre-work-warn); }
  & .is-bad::before { background: var(--dre-work-bad); }
  & dt { font-size: 11px; font-weight: 600; color: var(--dre-work-mute); }
  & dd { font-size: clamp(18px, 2.2cqi, 25px); font-weight: 760; letter-spacing: -.04em; line-height: 1.15; }
  & .is-bad dd { color: var(--dre-work-bad); }
  & small { font-size: 11.5px; color: var(--dre-work-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
}

.dre-work__filters { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.dre-work__pri {
  display: flex; flex-wrap: wrap; gap: 4px;
  & button {
    display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px 4px 8px; border-radius: 99px; font-size: 12px; font-weight: 620; color: var(--dre-work-faint);
    box-shadow: inset 0 0 0 1px var(--dre-work-line); transition: background-color .2s, color .2s, box-shadow .2s;
    &:hover { color: var(--dre-work-ink); }
    &[aria-pressed=true] { color: var(--dre-work-ink); background: var(--dre-work-card); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dre-work-ink) 22%, transparent); }
    & i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); opacity: .35; transition: opacity .2s; }
    &[aria-pressed=true] i { opacity: 1; }
    &[aria-disabled=true] { cursor: not-allowed; }
    & small { font-size: 11px; color: var(--dre-work-faint); font-variant-numeric: tabular-nums; }
  }
}
.dre-work__bsel { height: 28px; border-radius: 8px; border: 0; padding: 0 8px; font-size: 12px; background: var(--dre-work-card); box-shadow: inset 0 0 0 1px var(--dre-work-line); }
.dre-work__tradechip {
  display: inline-flex; align-items: center; gap: 4px; padding: 3px 4px 3px 10px; border-radius: 99px; font-size: 12px; font-weight: 620; background: var(--dre-work-ink); color: var(--dre-work-bg);
  & button { width: 20px; height: 20px; display: grid; place-items: center; border-radius: 50%; }
  & button:hover { background: color-mix(in oklch, var(--dre-work-bg) 20%, transparent); }
  & svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; }
}
.dre-work__sort {
  margin-left: auto; display: inline-flex; gap: 2px; padding: 3px; border-radius: 10px; background: var(--dre-work-soft);
  & [role=radio] { padding: 3px 9px; border-radius: 7px; font-size: 11.5px; font-weight: 620; color: var(--dre-work-mute); transition: background-color .2s, color .2s; }
  & [role=radio][aria-checked=true] { background: var(--dre-work-card); color: var(--dre-work-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dre-work-ink) 15%, transparent); }
}
.dre-work:has(.dre-work__queue[hidden]) .dre-work__sort { visibility: hidden; }

.dre-work__stage { min-height: 0; min-width: 0; position: relative; }
.dre-work__view { height: 100%; border-radius: 14px; background: var(--dre-work-card); box-shadow: inset 0 0 0 1px var(--dre-work-line); }
.dre-work__view:not([hidden]) { animation: dre-work-view .45s var(--dre-work-out); }
@keyframes dre-work-view { from { opacity: 0; translate: 0 6px; } }

/* SLA ring: one registered number drives the arc, so it eases when the clock moves */
.dre-work__ring {
  --size: 40px; --c: var(--dre-work-ok);
  position: relative; width: var(--size); height: var(--size); border-radius: 50%; flex: none; display: grid; place-items: center;
  background: conic-gradient(var(--c) calc(var(--dre-work-p) * 1turn), color-mix(in oklch, var(--dre-work-ink) 9%, transparent) 0);
  transition: --dre-work-p .9s var(--dre-work-out);
  @starting-style { --dre-work-p: 0; }
  &::before { content: ""; position: absolute; inset: 4px; border-radius: 50%; background: var(--dre-work-card); }
  & svg { position: relative; width: 15px; height: 15px; fill: none; stroke: var(--dre-work-mute); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  &[data-s=warn] { --c: var(--dre-work-warn); }
  &[data-s=risk] { --c: var(--dre-work-bad); }
  &[data-s=late] { --c: var(--dre-work-bad); background: var(--dre-work-bad); }
  &[data-s=late] svg { stroke: var(--dre-work-bad); }
  &[data-s=done] { --c: var(--dre-work-ok); background: color-mix(in oklch, var(--dre-work-ok) 22%, transparent); }
  &[data-s=done] svg { stroke: var(--dre-work-ok); }
}
.dre-work__left { font: 650 11.5px var(--dre-work-mono); letter-spacing: -.02em; white-space: nowrap; }
.dre-work__left[data-s=late] { color: var(--dre-work-bad); }
.dre-work__left[data-s=risk] { color: var(--dre-work-bad); }
.dre-work__left[data-s=warn] { color: color-mix(in oklch, var(--dre-work-warn) 75%, var(--dre-work-ink)); }

/* queue */
.dre-work__list { display: grid; padding: 6px; }
.dre-work__row {
  width: 100%; display: grid; grid-template-columns: 40px 66px minmax(0, 1fr) auto auto 28px; align-items: center; gap: 12px; padding: 8px 10px; border-radius: 10px;
  transition: background-color .2s;
  animation: dre-work-in .5s var(--dre-work-out) both; animation-delay: calc(var(--i) * 28ms);
  &:hover { background: var(--dre-work-soft); }
  &[aria-expanded=true] { background: color-mix(in oklch, var(--dre-work-signal) 30%, transparent); }
  & + .dre-work__row { box-shadow: 0 -1px 0 color-mix(in oklch, var(--dre-work-ink) 6%, transparent); }
  &.is-breach { animation: dre-work-breach .7s var(--dre-work-out); }
}
@keyframes dre-work-in { from { opacity: 0; translate: 0 8px; } }
@keyframes dre-work-breach { 0%, 100% { translate: 0; } 20% { translate: -5px 0; background: color-mix(in oklch, var(--dre-work-bad) 16%, transparent); } 40% { translate: 4px 0; } 60% { translate: -2px 0; } }
.dre-work__what {
  min-width: 0; display: grid; gap: 1px;
  & b { font-size: 13px; font-weight: 640; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { font-size: 11.5px; color: var(--dre-work-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small span { font-family: var(--dre-work-mono); font-size: 10.5px; color: var(--dre-work-faint); }
}
.dre-work__chip {
  display: inline-flex; align-items: center; gap: 5px; padding: 2px 8px; border-radius: 6px; font-size: 11px; font-weight: 650; white-space: nowrap;
  background: color-mix(in oklch, var(--c, var(--dre-work-ink)) 13%, transparent); color: color-mix(in oklch, var(--c, var(--dre-work-ink)) 80%, var(--dre-work-ink));
}
.dre-work__st { font-size: 11.5px; color: var(--dre-work-mute); white-space: nowrap; display: inline-flex; align-items: center; gap: 6px; }
.dre-work__st i { width: 7px; height: 7px; border-radius: 50%; background: var(--c); }
.dre-work__av { width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; font-size: 10px; font-weight: 700; background: var(--c, var(--dre-work-soft)); color: var(--dre-work-card); }
.dre-work__av.is-none { background: none; box-shadow: inset 0 0 0 1.5px var(--dre-work-line); color: var(--dre-work-faint); }
.dre-work__empty { padding: 40px 16px; text-align: center; color: var(--dre-work-mute); }

/* board */
.dre-work__board { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(200px, 1fr); gap: 8px; padding: 8px; align-items: start; }
.dre-work__col {
  min-height: 100%; display: grid; align-content: start; gap: 6px; padding: 8px; border-radius: 11px; background: var(--dre-work-soft);
  & > h3 { display: flex; align-items: center; justify-content: space-between; font-size: 11px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--dre-work-mute); padding: 2px 4px 4px; }
  & > h3 span { font: 600 11px var(--dre-work-mono); letter-spacing: 0; }
}
.dre-work__card {
  display: grid; gap: 8px; padding: 10px; border-radius: 10px; background: var(--dre-work-card); box-shadow: 0 1px 0 var(--dre-work-line), 0 4px 10px -8px color-mix(in oklch, var(--dre-work-ink) 50%, transparent);
  border-left: 3px solid var(--c);
  & .top { display: flex; align-items: start; gap: 8px; }
  & .top .dre-work__ring { --size: 30px; }
  & .top .dre-work__ring svg { width: 12px; height: 12px; }
  & .t { min-width: 0; font-size: 12.5px; font-weight: 640; line-height: 1.3; text-wrap: pretty; border-radius: 4px; }
  & .t:hover { text-decoration: underline; text-underline-offset: 3px; text-decoration-color: var(--dre-work-faint); }
  & .m { font-size: 11px; color: var(--dre-work-mute); }
  & .bot { display: flex; align-items: center; justify-content: space-between; gap: 6px; }
  & .bot .dre-work__av { width: 22px; height: 22px; font-size: 9px; }
  & .nx { padding: 4px 9px; border-radius: 7px; font-size: 11.5px; font-weight: 680; background: var(--dre-work-ink); color: var(--dre-work-card); transition: scale .2s var(--dre-work-out); }
  & .nx:active { scale: .95; }
  &.is-done { opacity: .7; }
}

/* hotspots */
.dre-work__heat { padding: 12px 14px; }
.dre-work__hgrid {
  display: grid; grid-template-columns: minmax(110px, 1.3fr) repeat(6, minmax(44px, 1fr)); gap: 4px; align-items: stretch;
  & .hh { font-size: 10.5px; font-weight: 650; color: var(--dre-work-mute); text-align: center; align-self: end; padding-bottom: 4px; display: grid; justify-items: center; gap: 3px; }
  & .hh svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  & .rh { font-size: 12px; font-weight: 620; display: flex; align-items: center; }
  & .rh small { margin-left: auto; font-size: 11px; color: var(--dre-work-faint); font-weight: 500; padding-right: 6px; font-variant-numeric: tabular-nums; }
  & .hc {
    min-height: 46px; border-radius: 8px; display: grid; place-items: center; font: 700 15px var(--dre-work-mono);
    --c: var(--dre-work-ok);
    background: color-mix(in oklab, var(--c) calc(var(--n) * 12% + 12%), var(--dre-work-card));
    box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--c) 35%, transparent);
    transition: scale .25s var(--dre-work-out), box-shadow .2s;
    animation: dre-work-pop .5s var(--dre-work-spring) both; animation-delay: calc(var(--i) * 18ms);
  }
  & .hc:hover:not(:disabled) { scale: 1.06; box-shadow: inset 0 0 0 2px var(--c); }
  & .hc:disabled { background: none; box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dre-work-ink) 6%, transparent); color: var(--dre-work-faint); font-weight: 400; animation: none; }
  & .hc[data-s=late] { --c: var(--dre-work-bad); background: color-mix(in oklab, var(--dre-work-bad) calc(70% + var(--n) * 10%), var(--dre-work-card)); color: oklch(0.99 0 0); }
  & .hc[data-s=risk] { --c: var(--dre-work-warn); }
}
@keyframes dre-work-pop { from { opacity: 0; scale: .7; } }
.dre-work__hnote { margin-top: 12px; font-size: 11.5px; color: var(--dre-work-mute); display: flex; flex-wrap: wrap; gap: 4px 14px; }
.dre-work__hnote span { display: inline-flex; align-items: center; gap: 6px; }
.dre-work__hnote i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); }

/* ---------- drawer */
.dre-work__drawer {
  position: absolute; z-index: 10; top: 76px; right: 10px; bottom: 10px; width: min(380px, calc(100% - 20px)); display: grid; grid-template-rows: auto minmax(0, 1fr);
  border-radius: 16px; background: var(--dre-work-card); box-shadow: 0 0 0 1px var(--dre-work-line), 0 30px 60px -24px color-mix(in oklch, var(--dre-work-ink) 55%, transparent);
  transition: translate .5s var(--dre-work-out), opacity .3s;
  @starting-style { translate: 30px 0; opacity: 0; }
  &[data-out] { translate: 30px 0; opacity: 0; }
}
.dre-work__dhead {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 12px; align-items: start; padding: 16px 14px 12px 16px; border-bottom: 1px solid var(--dre-work-line);
  & .dre-work__ring { --size: 52px; }
  & .dre-work__ring svg { width: 18px; height: 18px; }
  & h3 { font-size: 16px; font-weight: 740; letter-spacing: -.02em; line-height: 1.2; text-wrap: balance; }
}
.dre-work__dring { display: grid; justify-items: center; gap: 4px; }
.dre-work__x {
  width: 30px; height: 30px; display: grid; place-items: center; border-radius: 8px; transition: background-color .15s;
  &:hover { background: var(--dre-work-soft); }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
}
.dre-work__dbody { min-height: 0; padding: 14px 16px 18px; display: grid; align-content: start; gap: 14px; }
.dre-work__facts { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 4px 12px; font-size: 12px; & dt { color: var(--dre-work-mute); } & dd { font-weight: 600; } }
.dre-work__desc { font-size: 12.5px; line-height: 1.5; color: color-mix(in oklch, var(--dre-work-ink) 85%, var(--dre-work-bg)); padding: 10px 12px; border-radius: 10px; background: var(--dre-work-soft); text-wrap: pretty; }
.dre-work__steps {
  display: flex; flex-wrap: wrap; gap: 6px;
  & button { padding: 7px 11px; border-radius: 9px; font-size: 12px; font-weight: 660; box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dre-work-ink) 22%, transparent); transition: background-color .15s, scale .2s var(--dre-work-out); }
  & button:hover:not(:disabled) { background: var(--dre-work-soft); }
  & button:active:not(:disabled) { scale: .96; }
  & button:disabled { opacity: .4; }
  & .is-go { background: var(--dre-work-ink); color: var(--dre-work-card); box-shadow: none; }
  & .is-go:hover:not(:disabled) { background: color-mix(in oklch, var(--dre-work-ink) 85%, var(--dre-work-signal)); }
}
.dre-work__h4 { display: block; font-size: 11px; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; color: var(--dre-work-faint); margin-bottom: 6px; }
.dre-work__techs {
  display: grid; grid-template-columns: 1fr 1fr; gap: 4px;
  & [role=radio] {
    display: flex; align-items: center; gap: 8px; padding: 6px 8px; border-radius: 9px; font-size: 12px; box-shadow: inset 0 0 0 1px var(--dre-work-line); transition: background-color .15s, box-shadow .15s;
    &:hover { background: var(--dre-work-soft); }
    &[aria-checked=true] { box-shadow: inset 0 0 0 1.5px var(--dre-work-ink); background: color-mix(in oklch, var(--dre-work-signal) 28%, transparent); }
    & .dre-work__av { width: 22px; height: 22px; font-size: 9px; flex: none; }
    & span { min-width: 0; display: grid; line-height: 1.2; }
    & b { font-weight: 640; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & small { font-size: 10.5px; color: var(--dre-work-faint); white-space: nowrap; }
  }
}
.dre-work__note {
  display: grid; gap: 6px;
  & label { display: grid; }
  & textarea { resize: vertical; min-height: 54px; padding: 8px 10px; border-radius: 9px; border: 0; background: var(--dre-work-bg); box-shadow: inset 0 0 0 1px var(--dre-work-line); font-size: 12.5px; outline: none; }
  & textarea:focus { box-shadow: inset 0 0 0 1.5px var(--dre-work-ink); }
  & textarea[aria-invalid=true] { box-shadow: inset 0 0 0 1.5px var(--dre-work-bad); }
  & button { padding: 6px 12px; border-radius: 8px; font-size: 12px; font-weight: 660; background: var(--dre-work-ink); color: var(--dre-work-card); flex: none; }
}
.dre-work__nrow { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.dre-work__nerr { font-size: 11.5px; color: var(--dre-work-bad); }
.dre-work__nerr[data-ok] { color: var(--dre-work-ok); }
.dre-work__tl {
  display: grid; gap: 0; position: relative; padding-left: 16px;
  &::before { content: ""; position: absolute; left: 4px; top: 6px; bottom: 6px; width: 1.5px; background: var(--dre-work-line); }
  & li { position: relative; padding: 4px 0 8px; font-size: 12px; }
  & li::before { content: ""; position: absolute; left: -15.5px; top: 9px; width: 8px; height: 8px; border-radius: 50%; background: var(--dre-work-card); box-shadow: inset 0 0 0 2px var(--c, var(--dre-work-faint)); }
  & time { display: block; font: 500 10.5px var(--dre-work-mono); color: var(--dre-work-faint); }
  & li[data-new] { animation: dre-work-in .5s var(--dre-work-out) both; }
}

/* ---------- tooltip + toast */
.dre-work__tip {
  position: absolute; left: 0; top: 0; z-index: 30; pointer-events: none; max-width: 240px; padding: 8px 10px; border-radius: 10px;
  background: var(--dre-work-ink); color: var(--dre-work-bg); font-size: 11.5px; line-height: 1.4; opacity: 0; transition: opacity .15s;
  & b { display: block; font-size: 12px; } & span { display: block; opacity: .78; font-variant-numeric: tabular-nums; }
  &[data-on] { opacity: 1; }
}
.dre-work__toasts { position: absolute; left: 88px; bottom: 16px; z-index: 40; pointer-events: none; }
.dre-work__toast {
  max-width: 360px; padding: 10px 14px; border-radius: 12px; background: var(--dre-work-ink); color: var(--dre-work-bg); font-size: 12.5px; text-wrap: pretty;
  box-shadow: 0 16px 30px -12px color-mix(in oklch, var(--dre-work-ink) 70%, transparent); transition: opacity .25s, translate .45s var(--dre-work-spring);
  @starting-style { opacity: 0; translate: 0 12px; }
  & b { color: var(--dre-work-signal); }
  &[data-tone=bad] { background: var(--dre-work-bad); color: white; }
  &[data-tone=bad] b { color: white; }
  &[data-out] { opacity: 0; translate: 0 8px; }
}

/* ---------- responsive */
@container dre-work (max-width: 960px) {
  .dre-work__row { grid-template-columns: 40px 62px minmax(0, 1fr) auto 26px; }
  .dre-work__row .dre-work__st { display: none; }
}
@container dre-work (max-width: 760px) {
