  K('met2').textContent = m + ' of ' + c + ' closed on time · ' + done.length + ' today';
}

/* ------------------------------------------------------------------ filters */
const priBox = $('.dre-work__pri');
priBox.innerHTML = [1, 2, 3, 4].map(p => '<button type="button" aria-pressed="true" data-p="' + p + '"><i style="--c:' + PRI[p][2] + '"></i>' + PRI[p][0] + ' ' + PRI[p][1] + ' <small></small></button>').join('');
function paintPri() {
  $$('button[data-p]', priBox).forEach(b => {
    const p = +b.dataset.p, n = String(W.filter(t => t.p === p && t.status !== 'done' && inScope(t)).length), sm = b.querySelector('small');
    if (sm.textContent !== n) sm.textContent = n;
    b.setAttribute('aria-pressed', String(S.pri.has(p)));
    const last = S.pri.size === 1 && S.pri.has(p);
    b.setAttribute('aria-disabled', String(last));
    b.title = last ? 'At least one priority stays visible' : n + ' open ' + PRI[p][1].toLowerCase() + ' work orders (' + PRI[p][3] + ' SLA)';
  });
}
priBox.addEventListener('click', e => {
  const b = e.target.closest('button[data-p]'); if (!b || b.getAttribute('aria-disabled') === 'true') return;
  const p = +b.dataset.p; if (S.pri.has(p)) S.pri.delete(p); else S.pri.add(p);
  renderView();
});
const bsel = $('.dre-work__bsel');
bsel.innerHTML = '<option value="all">All buildings</option>' + BLD.map((b, i) => '<option value="' + i + '">' + b + '</option>').join('');
bsel.addEventListener('change', () => { S.bld = bsel.value; refresh(); });
const tchip = $('.dre-work__tradechip');
function paintTrade() {
  tchip.hidden = !S.trade;
  if (S.trade) tchip.innerHTML = TR[S.trade][0] + '<button type="button" aria-label="Clear the ' + TR[S.trade][0] + ' filter"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 7l10 10M17 7 7 17"/></svg></button>';
}
tchip.addEventListener('click', e => { if (e.target.closest('button')) { S.trade = null; paintTrade(); refresh(); bsel.focus(); } });
radioGroup($('.dre-work__sort'), v => { S.sort = v; renderQueue(true); });

/* ------------------------------------------------------------------ queue */
function sorted() {
  const xs = W.filter(shown);
  if (S.sort === 'due') return xs.sort((a, b) => a.due - b.due);
  if (S.sort === 'pri') return xs.sort((a, b) => a.p - b.p || a.due - b.due);
  return xs.sort((a, b) => a.b - b.b || a.due - b.due);
}
function rowHTML(t, i) {
  const x = sla(t);
  return '<li><button type="button" class="dre-work__row" data-id="' + t.id + '" style="--i:' + i + '" aria-haspopup="dialog" aria-expanded="' + (S.open === t.id) + '">' + ring(t, x) +
    '<span class="dre-work__left" data-s="' + x.s + '">' + x.txt + '</span>' +
    '<span class="dre-work__what"><b>' + esc(t.title) + '</b><small><span>WO-' + t.id + '</span> · ' + BLD[t.b] + ' · ' + esc(t.loc) + '</small></span>' +
    '<span class="dre-work__chip" style="--c:' + PRI[t.p][2] + '">' + PRI[t.p][0] + ' ' + PRI[t.p][1] + '</span>' +
    '<span class="dre-work__st"><i style="--c:' + ST[t.status][1] + '"></i>' + ST[t.status][0] + '</span>' + av(t.tech) + '</button></li>';
}
function renderQueue(animate) {
  const xs = sorted();
  if (animate && list.children.length) {
    const ids = xs.map(t => t.id);
    const same = $$('.dre-work__row', list).length === ids.length && $$('.dre-work__row', list).every(r => ids.includes(+r.dataset.id));
    if (same) { flip(() => $$('li', list), () => ids.forEach(id => list.appendChild(list.querySelector('[data-id="' + id + '"]').parentElement))); return; }
  }
  list.innerHTML = xs.map(rowHTML).join('');
  $('.dre-work__empty', root).hidden = xs.length > 0;
}
list.addEventListener('click', e => { const r = e.target.closest('.dre-work__row'); if (r) openDrawer(+r.dataset.id); });
list.addEventListener('keydown', e => {
  if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return;
  const rows = $$('.dre-work__row', list), i = rows.indexOf(e.target.closest('.dre-work__row')); if (i < 0) return;
  e.preventDefault(); const n = rows[clamp(i + (e.key === 'ArrowDown' ? 1 : -1), 0, rows.length - 1)]; n.focus();
});
list.addEventListener('pointermove', e => {
  const rg = e.target.closest('.dre-work__ring'); if (!rg) { hideTip(tip); return; }
  const t = byId.get(+rg.closest('[data-id]').dataset.id), x = sla(t);
  placeTip(tip, '<b>' + PRI[t.p][3] + ' SLA · ' + (x.s === 'late' ? x.txt.slice(1) + ' over' : x.txt + ' left') + '</b><span>Opened ' + when(t.opened) + '</span><span>Due ' + when(t.due) + '</span>', e.clientX, e.clientY);
});
list.addEventListener('pointerleave', () => hideTip(tip));
function tickAll() {
  $$('[data-id]', root).forEach(el => {
    const t = byId.get(+el.dataset.id); if (!t) return;
    const x = sla(t), rg = el.querySelector('.dre-work__ring');
    if (rg) { rg.dataset.s = x.s; rg.style.setProperty('--dre-work-p', x.p.toFixed(3)); }
    const lf = el.querySelector('.dre-work__left'); if (lf) { lf.dataset.s = x.s; lf.textContent = x.txt; }
  });
  if (S.open) paintDrawerRing();
  kpis();
  if (S.view === 'heat') renderHeat();
}

/* ------------------------------------------------------------------ board */
const COLS = ['new', 'assigned', 'progress', 'parts', 'done'];
const NEXT = { new: 'Assign', assigned: 'Start', progress: 'Complete', parts: 'Parts in' };
function cardHTML(t) {
  const x = sla(t);
  return '<article class="dre-work__card' + (t.status === 'done' ? ' is-done' : '') + '" data-id="' + t.id + '" style="--c:' + PRI[t.p][2] + '">' +
    '<div class="top">' + ring(t, x) + '<div><button type="button" class="t" aria-haspopup="dialog">' + esc(t.title) + '</button><div class="m">WO-' + t.id + ' · ' + BLD[t.b] + '</div></div></div>' +
    '<div class="bot"><span class="dre-work__left" data-s="' + x.s + '">' + x.txt + '</span>' + av(t.tech) +
    (NEXT[t.status] ? '<button type="button" class="nx" data-next="' + t.status + '">' + NEXT[t.status] + '</button>' : '') + '</div></article>';
}
function renderBoard() {
  const xs = W.filter(t => inScope(t) && S.pri.has(t.p) && (!S.trade || t.trade === S.trade));
  board.innerHTML = COLS.map(c => {
    const cs = xs.filter(t => t.status === c).sort((a, b) => c === 'done' ? b.doneAt - a.doneAt : a.due - b.due);
    return '<section class="dre-work__col" data-col="' + c + '" aria-label="' + ST[c][0] + '"><h3>' + (c === 'done' ? 'Done today' : ST[c][0]) + '<span>' + cs.length + '</span></h3>' + cs.map(cardHTML).join('') + '</section>';
  }).join('');
}
board.addEventListener('click', e => {
  const card = e.target.closest('.dre-work__card'); if (!card) return;
  const t = byId.get(+card.dataset.id), nx = e.target.closest('.nx');
  if (e.target.closest('.t')) { openDrawer(t.id); return; }
  if (!nx) return;
  if (t.status === 'new') { openDrawer(t.id); const r = $('.dre-work__techs [role=radio]'); if (r) r.focus(); return; }
  step(t, t.status === 'assigned' ? 'progress' : t.status === 'progress' ? 'done' : 'progress');
});

/* ------------------------------------------------------------------ hotspots */
/* the grid is built once; ticks and filters only repaint each cell's count and state */
heat.innerHTML = '<div class="dre-work__hgrid" role="grid" aria-label="Open work orders by building and trade"><span></span>' +
  TRK.map(k => '<span class="hh" role="columnheader">' + icon(k) + '<span>' + TR[k][1] + '</span></span>').join('') +
  BLD.map((b, bi) => '<span class="rh" role="rowheader">' + b + '<small></small></span>' +
    TRK.map((k, ki) => '<button type="button" class="hc" role="gridcell" data-b="' + bi + '" data-t="' + k + '" style="--i:' + (bi * 6 + ki) + '"></button>').join('')).join('') + '</div>' +
  '<p class="dre-work__hnote"><span><i style="--c:var(--dre-work-ok)"></i>All inside SLA</span><span><i style="--c:var(--dre-work-warn)"></i>Half or less of SLA left</span><span><i style="--c:var(--dre-work-bad)"></i>Something past SLA</span><span>Click a cell to open those jobs in the queue</span></p>';
function renderHeat() {
  const open = W.filter(t => t.status !== 'done' && S.pri.has(t.p));
  $$('.rh small', heat).forEach((sm, bi) => { sm.textContent = open.filter(t => t.b === bi).length; });
  $$('.hc', heat).forEach(c => {
    const bi = +c.dataset.b, k = c.dataset.t, b = BLD[bi];
    const cs = open.filter(t => t.b === bi && t.trade === k), xs = cs.map(sla);
    const st = xs.some(x => x.s === 'late') ? 'late' : xs.some(x => x.s === 'risk' || x.s === 'warn') ? 'risk' : 'ok';
    const txt = cs.length ? String(cs.length) : '·';
    if (c.textContent !== txt) c.textContent = txt;
    if (c.dataset.s !== st) c.dataset.s = st;
    c.style.setProperty('--n', cs.length);
    c.disabled = !cs.length;
    if (cs.length) { c.removeAttribute('title'); c.setAttribute('aria-label', b + ', ' + TR[k][0] + ': ' + cs.length + ' open' + (st === 'late' ? ', past SLA' : '') + '. Open in queue.'); }
    else { c.title = 'No open ' + TR[k][0].toLowerCase() + ' work at ' + b; c.setAttribute('aria-label', b + ', ' + TR[k][0] + ': none open'); }
  });
}
heat.addEventListener('click', e => {
  const c = e.target.closest('.hc'); if (!c || c.disabled) return;
  S.bld = c.dataset.b; bsel.value = S.bld; S.trade = c.dataset.t; paintTrade(); kpis();
  pickView($('.dre-work__views [data-view="queue"]'), true);
});
heat.addEventListener('pointermove', e => {
  const c = e.target.closest('.hc:not(:disabled)'); if (!c) { hideTip(tip); return; }
  const cs = W.filter(t => t.status !== 'done' && S.pri.has(t.p) && t.b === +c.dataset.b && t.trade === c.dataset.t);
  placeTip(tip, '<b>' + BLD[+c.dataset.b] + ' · ' + TR[c.dataset.t][0] + '</b>' + cs.map(t => '<span>WO-' + t.id + ' · ' + sla(t).txt + (sla(t).s === 'late' ? ' over' : ' left') + '</span>').join(''), e.clientX, e.clientY);
});
heat.addEventListener('pointerleave', () => hideTip(tip));

/* ------------------------------------------------------------------ views */
const views = $('.dre-work__views');
const pickView = tabs(views, v => { S.view = v; $$('.dre-work__view').forEach(s => { s.hidden = s.dataset.view !== v; }); renderView(); });
function renderView() { paintPri(); if (S.view === 'queue') renderQueue(false); else if (S.view === 'board') renderBoard(); else renderHeat(); }
function refresh() { kpis(); renderView(); }

/* ------------------------------------------------------------------ drawer */
const drawer = $('.dre-work__drawer');
const D = k => $('[data-d="' + k + '"]', drawer);
const techs = $('.dre-work__techs');
let lastFocus = null, newLog = null;
function paintDrawerRing() {
  const t = byId.get(S.open), x = sla(t);
  $('.dre-work__dring', drawer).innerHTML = ring(t, x) + '<span class="dre-work__left" data-s="' + x.s + '">' + (x.s === 'done' ? 'SLA ' + x.txt : x.txt + (x.s === 'late' ? ' over' : ' left')) + '</span>';
}
function renderDrawer() {
  const t = byId.get(S.open); if (!t) return;
  paintDrawerRing();
  D('id').textContent = 'WO-' + t.id + ' · ' + PRI[t.p][0] + ' ' + PRI[t.p][1];
  D('title').textContent = t.title;
  $('.dre-work__facts', drawer).innerHTML = '<dt>Where</dt><dd>' + BLD[t.b] + ' · ' + esc(t.loc) + '</dd><dt>Trade</dt><dd>' + TR[t.trade][0] + '</dd>' +
    '<dt>Reported</dt><dd>' + when(t.opened) + ' · ' + esc(t.by) + '</dd><dt>' + PRI[t.p][3] + ' SLA</dt><dd>due ' + when(t.due) + '</dd>' +
    '<dt>Status</dt><dd>' + ST[t.status][0] + (t.tech ? ' · ' + TECH[t.tech][0] : '') + '</dd>';
  D('desc').textContent = t.desc;
  const s = t.status, why = { new: 'Assign someone first', done: 'This work order is closed' };
  const btn = (k, label, ok, title, go) => '<button type="button" data-step="' + k + '"' + (go ? ' class="is-go"' : '') + (ok ? '' : ' disabled title="' + title + '"') + '>' + label + '</button>';
  $('.dre-work__steps', drawer).innerHTML =
    btn('progress', s === 'parts' ? 'Parts arrived' : 'Start work', s === 'assigned' || s === 'parts', why[s] || (s === 'progress' ? 'Work is already under way' : ''), s === 'assigned' || s === 'parts') +
    btn('parts', 'Waiting on parts', s === 'progress', why[s] || (s === 'parts' ? 'Already waiting on parts' : 'Start the work first')) +
    btn('done', 'Complete', s === 'progress', why[s] || (s === 'parts' ? 'Parts have not arrived' : 'Start the work first'), s === 'progress');
  techs.innerHTML = Object.keys(TECH).map(k => '<button type="button" role="radio" data-v="' + k + '" aria-checked="' + (t.tech === k) + '" tabindex="' + (t.tech === k || (!t.tech && k === 'mk') ? 0 : -1) + '"' +
    (s === 'done' ? ' aria-disabled="true" title="This work order is closed"' : '') + '>' + av(k) + '<span><b>' + TECH[k][0] + '</b><small>' + TECH[k][1] + ' · ' + W.filter(x => x.tech === k && x.status !== 'done').length + ' open</small></span></button>').join('');
  $('.dre-work__tl', drawer).innerHTML = t.log.map(l => '<li style="--c:' + l.c + '"' + (l === newLog ? ' data-new' : '') + '><time>' + when(l.at) + '</time>' + esc(l.txt) + '</li>').join('');
  newLog = null;
}
function openDrawer(id) {
  const first = drawer.hidden || drawer.dataset.out;
  if (first) lastFocus = root.contains(document.activeElement) ? document.activeElement : null;
  S.open = id; delete drawer.dataset.out; drawer.hidden = false;
  $$('.dre-work__row', list).forEach(r => r.setAttribute('aria-expanded', String(+r.dataset.id === id)));
  noteErr.textContent = ''; delete noteErr.dataset.ok; note.elements.note.removeAttribute('aria-invalid');
  renderDrawer();
  if (first) $('.dre-work__x', drawer).focus({ preventScroll: true });
}
function closeDrawer() {
  if (drawer.hidden) return;
  S.open = null;
  $$('.dre-work__row', list).forEach(r => r.setAttribute('aria-expanded', 'false'));
  if (RM) drawer.hidden = true;
  else { drawer.dataset.out = '1'; setTimeout(() => { if (!root.isConnected) return; if (drawer.dataset.out) { drawer.hidden = true; delete drawer.dataset.out; } }, 320); }
  if (lastFocus && lastFocus.isConnected) lastFocus.focus({ preventScroll: true });
}
$('.dre-work__x', drawer).addEventListener('click', closeDrawer);
root.addEventListener('keydown', e => { if (e.key === 'Escape' && !drawer.hidden) { e.preventDefault(); closeDrawer(); } });
function log(t, txt, c) { newLog = { at: new Date(S.now), txt, c }; t.log.push(newLog); }
function step(t, to) {
  const from = t.status;
  if (to === 'progress') log(t, from === 'parts' ? 'Parts arrived, work resumed' : 'Work started on site', 'var(--dre-work-ok)');
  if (to === 'parts') log(t, 'Waiting on parts', 'var(--dre-work-warn)');
  if (to === 'done') {
    t.doneAt = new Date(S.now); log(t, 'Completed', 'var(--dre-work-ok)');
    const d = t.due - t.doneAt;
    toast('<b>WO-' + t.id + ' closed</b> ' + (d >= 0 ? dur(d) + ' inside its ' : dur(d) + ' past its ') + PRI[t.p][3] + ' SLA', d >= 0 ? '' : 'bad');
  }
  t.status = to;
  if (S.view === 'board') {
    flip(() => $$('.dre-work__card', board), () => {
      const card = board.querySelector('.dre-work__card[data-id="' + t.id + '"]'), col = board.querySelector('[data-col="' + to + '"]');
      const fresh = document.createElement('div'); fresh.innerHTML = cardHTML(t);
      const nc = fresh.firstChild;
      const after = $$('.dre-work__card', col).find(c => to === 'done' ? true : byId.get(+c.dataset.id).due > t.due);
      if (after) col.insertBefore(nc, after); else col.appendChild(nc);
      if (card) card.remove();
      $$('.dre-work__col', board).forEach(c => { c.querySelector('h3 span').textContent = $$('.dre-work__card', c).length; });
    }, 520);
  } else renderView();
  kpis(); paintPri();
  if (S.open === t.id) renderDrawer();
}
drawer.addEventListener('click', e => {
  const b = e.target.closest('button[data-step]'); if (!b || b.disabled) return;
  const t = byId.get(S.open); step(t, b.dataset.step);
  const nb = drawer.querySelector('button[data-step]:not(:disabled)'); if (nb) nb.focus(); else $('.dre-work__x', drawer).focus();
});
radioGroup(techs, v => {
  const t = byId.get(S.open);
