  toast('<b>WO-' + t.id + '</b> assigned to ' + TECH[v][0] + ' · ' + sla(t).txt + (sla(t).s === 'late' ? ' past SLA' : ' left on the clock'));
  renderView(); kpis(); renderDrawer();
  const r = techs.querySelector('[data-v="' + v + '"]'); if (r) r.focus();
});
const note = $('.dre-work__note'), noteErr = $('.dre-work__nerr');
note.addEventListener('submit', e => {
  e.preventDefault();
  const ta = note.elements.note, v = ta.value.trim(), t = byId.get(S.open);
  delete noteErr.dataset.ok;
  if (v.length < 3) { noteErr.textContent = 'Write a few words first.'; ta.setAttribute('aria-invalid', 'true'); ta.focus(); return; }
  ta.removeAttribute('aria-invalid');
