/* ------------------------------------------------------------------ boot */
paintClock(); paintTrade(); kpis(); renderView();

css:
.dre-build {
  /* re-theme with these four */
  --dre-build-bg: oklch(0.215 0.006 262);
  --dre-build-ink: oklch(0.94 0.008 90);
  --dre-build-cost: oklch(0.73 0.165 52);
  --dre-build-earn: oklch(0.86 0.13 124);
  /* derived */
  --dre-build-bad: oklch(0.66 0.18 25);
  --dre-build-panel: color-mix(in oklab, var(--dre-build-bg) 94%, var(--dre-build-ink));
  --dre-build-raise: color-mix(in oklab, var(--dre-build-bg) 86%, var(--dre-build-ink));
  --dre-build-line: color-mix(in oklab, var(--dre-build-ink) 11%, transparent);
  --dre-build-soft: color-mix(in oklab, var(--dre-build-ink) 6%, transparent);
  --dre-build-mute: color-mix(in oklab, var(--dre-build-ink) 62%, var(--dre-build-bg));
  --dre-build-faint: color-mix(in oklab, var(--dre-build-ink) 40%, var(--dre-build-bg));
  --dre-build-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dre-build-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dre-build-out: cubic-bezier(.16, 1, .3, 1);
  --dre-build-spring: linear(0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 25.3%, 0.849 31.5%, 0.937 38.1%, 0.968 41.8%, 0.991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);

  width: 100%;
  height: var(--dre-build-h, 680px);
  container-type: inline-size; container-name: dre-build;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 16px;
  background: radial-gradient(120% 80% at 100% 0%, color-mix(in oklab, var(--dre-build-cost) 7%, transparent), transparent 60%), var(--dre-build-bg);
  color: var(--dre-build-ink);
  font: 13px/1.45 var(--dre-build-sans);
  accent-color: var(--dre-build-cost);
  color-scheme: dark;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, ol, ul) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(button:disabled) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--dre-build-cost); outline-offset: 2px; border-radius: 6px; }
  & .dre-build__num { font-variant-numeric: tabular-nums; }
  & .dre-build__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dre-build__scroll { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: color-mix(in oklab, var(--dre-build-ink) 22%, transparent) transparent; }
}

.dre-build__shell { height: 100%; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); gap: 12px; padding: 14px 16px 16px; }

/* ---------- header */
.dre-build__head { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; }
.dre-build__id {
  display: flex; align-items: center; gap: 12px; margin-right: auto; min-width: 0;
  & h2 { font-size: clamp(19px, 2.2cqi, 26px); font-weight: 760; letter-spacing: -.035em; line-height: 1.05; text-wrap: balance; }
}
.dre-build__mark svg { width: 38px; height: 38px; padding: 7px; border-radius: 10px; background: var(--dre-build-cost); fill: none; stroke: var(--dre-build-bg); stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
.dre-build__eyebrow { font-size: 11.5px; color: var(--dre-build-mute); margin-bottom: 3px; }
.dre-build__asof { display: flex; align-items: center; gap: 4px; padding: 4px; border-radius: 12px; background: var(--dre-build-soft); box-shadow: inset 0 0 0 1px var(--dre-build-line); }
.dre-build__step {
  width: 28px; height: 28px; display: grid; place-items: center; border-radius: 8px; transition: background-color .15s;
  &:hover:not(:disabled) { background: var(--dre-build-soft); }
  &:disabled { opacity: .35; }
