/* ------------------------------------------------------------------ the report, as at month a */
const S = { a: NOW, scope: null, sort: 'code', dir: 1, off: new Set() };
function coApproved(code, a) { return CO.filter(c => c.code === code && c.s === 'approved' && (c.dec != null ? c.dec : c.d) <= a).reduce((s, c) => s + c.amt, 0); }
function codeAt(c, a) {
  const ev = c.b0 * c.prog[a], ac = c.ac[a], pv = c.b0 * c.cum[a];
  const cpi = ac > 1 ? ev / ac : 1, co = coApproved(c.code, a);
  const eac = ac + (c.b0 - ev) / cpi + co, bac = c.b0 + co;
  const committed = c.s > a + 3 ? 0 : Math.min(bac, Math.max(ac, bac * c.cf * clamp((a - c.s + 4) / 6, 0, 1)));
  return { c, ev, ac, pv, cpi, co, eac, bac, committed, pct: c.prog[a], v: bac - eac };
}
function report(a) {
  const rows = CODES.map(c => codeAt(c, a));
  const t = k => rows.reduce((s, r) => s + r[k], 0);
  const R = { a, rows, ev: t('ev'), ac: t('ac'), pv: t('pv'), eac: t('eac'), bac: t('bac'), co: t('co'), committed: t('committed') };
  R.cpi = R.ev / R.ac; R.spi = R.ev / R.pv;
  R.over = R.eac - R.bac;                       /* base overrun the forecast already expects */
  R.head = CONT - R.co - R.over;                /* contingency still free */
  R.pend = CO.filter(c => c.s === 'pending' && c.d <= a).reduce((s, c) => s + c.amt, 0);
  /* months behind: when did the plan reach today's earned value? */
  const pvTot = m => CODES.reduce((s, c) => s + c.b0 * c.cum[m], 0);
  let t0 = a; for (let m = 0; m <= a; m++) { if (pvTot(m) >= R.ev) { const p0 = m ? pvTot(m - 1) : 0; t0 = m - 1 + (R.ev - p0) / (pvTot(m) - p0); break; } }
  R.behind = Math.max(0, a - t0);
  return R;
}

