  const free = CONT - used - over, pshow = Math.max(0, Math.min(pend, free)), left = Math.max(0, free - pshow);
  [['a', used], ['o', over], ['p', pshow], ['h', left]].forEach(([k, v]) => cbar.querySelector('.' + k).style.setProperty('--f', (v / CONT).toFixed(4)));
  K('cont').textContent = M1(CONT) + ' held';
  K('ckey').innerHTML = '<li><i style="background:var(--dre-build-cost)"></i>Approved changes<b>' + M1(R.co) + '</b></li>' +
    '<li><i style="background:var(--dre-build-bad)"></i>Forecast overrun<b>' + M1(R.over) + '</b></li>' +
    '<li><i style="background:repeating-linear-gradient(135deg,var(--dre-build-ink) 0 1.5px,transparent 1.5px 4px)"></i>Pending<b>' + M1(R.pend) + '</b></li>' +
    '<li><i style="background:var(--dre-build-earn)"></i>' + (free - pend >= 0 ? 'Free if all pass' : 'Short if all pass') + '<b class="' + (free - pend >= 0 ? '' : 'dre-build__bad') + '">' + M1(free - pend) + '</b></li>';
  const n = CO.filter(c => c.s === 'pending' && c.d <= S.a).length;
  K('pend').textContent = n ? n + ' awaiting a decision' : 'none pending';
}
function coList() {
  const vis = CO.filter(c => c.d <= S.a).sort((x, y) => (x.s === 'pending' ? 0 : 1) - (y.s === 'pending' ? 0 : 1) || y.d - x.d);
  const live = S.a === NOW, why = 'Return to ' + mlab(NOW) + ' to decide change orders';
  colist.innerHTML = vis.map(c => {
    const pk = CODES.find(x => x.code === c.code);
    const acts = c.s === 'pending'
      ? '<button type="button" class="ok" data-co="' + c.id + '" data-to="approved"' + (live ? '' : ' disabled title="' + why + '"') + '>Approve</button><button type="button" data-co="' + c.id + '" data-to="rejected"' + (live ? '' : ' disabled title="' + why + '"') + '>Reject</button>'
      : '<span class="st">' + (c.s === 'approved' ? 'Approved' : 'Rejected') + ' ' + MN[(c.dec != null ? c.dec : c.d) % 12] + '</span>' +
