}
.dre-tenant__factors {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 4px 8px; align-items: center; font-size: 11.5px;
  & dt { color: var(--dre-tenant-mute); }
  & dd { height: 6px; border-radius: 3px; background: var(--dre-tenant-soft); overflow: hidden; }
