  & .br { height: 6px; border-radius: 3px; background: var(--dre-tenant-soft); overflow: hidden; }
  & .br i { display: block; height: 100%; background: var(--rc); transform-origin: left; scale: var(--v) 1; transition: scale .6s var(--dre-tenant-out); }
  & .v { font: 650 11px var(--dre-tenant-mono); text-align: right; }
  &.is-out { display: none; }
}

/* ---------- tooltip + toast */
.dre-tenant__tip {
  position: absolute; left: 0; top: 0; z-index: 30; pointer-events: none; max-width: 250px; padding: 8px 10px; border-radius: 10px;
  background: var(--dre-tenant-ink); color: var(--dre-tenant-bg); font-size: 11.5px; line-height: 1.45; opacity: 0; transition: opacity .15s;
  box-shadow: 0 12px 26px -10px color-mix(in oklab, var(--dre-tenant-ink) 70%, transparent);
