  max-width: 360px; padding: 10px 14px; border-radius: 12px; background: var(--dre-tenant-ink); color: var(--dre-tenant-bg); font-size: 12.5px; text-wrap: pretty;
  box-shadow: 0 14px 30px -12px color-mix(in oklab, var(--dre-tenant-ink) 70%, transparent); transition: opacity .25s, translate .45s var(--dre-tenant-spring);
  @starting-style { opacity: 0; translate: 0 12px; }
  &[data-out] { opacity: 0; translate: 0 8px; }
}

/* ---------- responsive */
@container dre-tenant (max-width: 980px) {
  .dre-tenant__body { grid-template-columns: minmax(0, 1fr) 290px; }
  .dre-tenant__quads b { display: none; }
}
@container dre-tenant (max-width: 780px) {
  .dre-tenant__shell { overflow: auto; display: flex; flex-direction: column; scrollbar-width: thin; padding: 14px 12px; }
  .dre-tenant__shell > * { flex: none; }
  .dre-tenant__kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dre-tenant__kpis > div:nth-child(3) { border-left: 0; padding-left: 2px; }
  .dre-tenant__kpis > div:nth-child(n+3) { border-top: 1px solid var(--dre-tenant-line); }
  .dre-tenant__body { grid-template-columns: minmax(0, 1fr); }
  .dre-tenant__stage { grid-template-rows: auto 380px; }
  .dre-tenant__quads b { display: inline; }
  .dre-tenant__side { grid-template-rows: auto auto; }
  .dre-tenant__list { max-height: 360px; }
}
@container dre-tenant (max-width: 480px) {
  .dre-tenant__views [role=tab] svg { display: none; }
  .dre-tenant__mark { display: none; }
  .dre-tenant__stage { grid-template-rows: auto 330px; }
}

@media (prefers-reduced-motion: reduce) {
  .dre-tenant .dre-tenant__view, .dre-tenant .dre-tenant__plan .u rect { animation: none; }
  .dre-tenant .dre-tenant__scatter .tn, .dre-tenant .dre-tenant__ring, .dre-tenant .dre-tenant__factors dd i, .dre-tenant .dre-tenant__row .br i, .dre-tenant .dre-tenant__toast { transition-duration: .01ms; }
}

