/* ------------------------------------------------------------------ site plan */
const plan = $('.dre-tenant__plan');
(function buildPlan() {
  const byU = Object.fromEntries(T.map(t => [t.unit, t]));
  const rowN = ['N01', 'N02', 'N03', 'N04', 'N05', 'N06', 'N07', 'N08', 'N09', 'N10', 'N11', 'N12', 'N13'];
  const rowS = ['L1', 'S03', 'S04', 'S05', 'S06', 'L2', 'S07', 'S08', 'S09', 'S10', 'L3', 'L4'];
