  let x = 190; const nTot = rowN.reduce((a, u) => a + byU[u].sf, 0);
  rowN.forEach(u => { const w = 620 * byU[u].sf / nTot; rects.push([byU[u], x, 40, w - 3, 104]); x += w; });
  x = 20; const sTot = rowS.reduce((a, u) => a + byU[u].sf, 0);
  rowS.forEach(u => { const w = 960 * byU[u].sf / sTot, big = u[0] === 'L'; rects.push([byU[u], x, big ? 420 : 436, w - 3, big ? 120 : 104]); x += w; });
  rects.push([byU.P1, 468, 262, 64, 40]);
