    '<rect class="lot" x="190" y="170" width="620" height="216" rx="6"/>';
  for (let bx = 200; bx < 800; bx += 22) { s += '<line class="bay" x1="' + bx + '" x2="' + bx + '" y1="178" y2="226"/><line class="bay" x1="' + bx + '" x2="' + bx + '" y1="330" y2="378"/>'; }
  s += '<path class="road" d="M500 386V240"/><text class="lbl" x="250" y="292">Car park · 610 spaces</text><text class="lbl" x="500" y="556" text-anchor="middle"></text>';
  s += rects.map(([t, rx, ry, w, h], k) => '<g class="u" role="option" tabindex="-1" aria-selected="false" data-i="' + t.i + '" style="--i:' + k + '"><rect x="' + rx.toFixed(1) + '" y="' + ry + '" width="' + w.toFixed(1) + '" height="' + h + '" rx="3"/>' +
    (w > 44 ? '<text x="' + (rx + 6).toFixed(1) + '" y="' + (ry + 16) + '">' + esc((w > 110 ? t.name : t.name.split(' ')[0]).slice(0, Math.floor(w / 6.2))) + '</text><text class="s" x="' + (rx + 6).toFixed(1) + '" y="' + (ry + 29) + '"></text>' : '') +
    '<path class="flag" d="M' + (rx + w - 13).toFixed(1) + ' ' + (ry + 6) + 'v11M' + (rx + w - 13).toFixed(1) + ' ' + (ry + 6) + 'h7l-2 3 2 3h-7" style="stroke:var(--dre-tenant-accent);stroke-width:1.5;fill:var(--dre-tenant-accent)"/></g>').join('');
  plan.setAttribute('viewBox', '0 0 1000 560');
