})();
function paintPlan() {
  $$('.u', plan).forEach(g => {
    const t = T[+g.dataset.i];
    g.style.setProperty('--f', 'color-mix(in oklab, ' + ramp(t.score) + ' 72%, white)');
    const sm = g.querySelector('text.s'); if (sm) sm.textContent = t.score + ' · ' + pct(t.ocr, 0);
    g.querySelector('.flag').style.display = S.watch.has(t.i) ? '' : 'none';
    g.classList.toggle('is-dim', !visible(t) || dim(t));
