plan.addEventListener('click', e => { const g = e.target.closest('.u'); if (g) select(+g.dataset.i); });
plan.addEventListener('pointermove', e => { const g = e.target.closest('.u'); if (!g) { hideTip(tip); return; } tipFor(T[+g.dataset.i], e.clientX, e.clientY); });
plan.addEventListener('pointerleave', () => hideTip(tip));

/* shared keyboard for both SVG listboxes: move in ranking order */
function svgKeys(svgEl, sel) {
  svgEl.addEventListener('keydown', e => {
    const g = e.target.closest(sel); if (!g) return;
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(+g.dataset.i); return; }
    const order = ranked().filter(visible).map(t => t.i), k = order.indexOf(+g.dataset.i);
    let n = k;
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') n = Math.min(order.length - 1, k + 1);
    else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') n = Math.max(0, k - 1);
    else if (e.key === 'Home') n = 0; else if (e.key === 'End') n = order.length - 1; else return;
    e.preventDefault();
    const next = svgEl.querySelector(sel + '[data-i="' + order[n] + '"]');
    $$(sel, svgEl).forEach(x => x.setAttribute('tabindex', '-1')); next.setAttribute('tabindex', '0'); next.focus();
  });
}
svgKeys(sc, '.tn'); svgKeys(plan, '.u');

/* ------------------------------------------------------------------ ranking */
const list = $('.dre-tenant__list');
list.innerHTML = T.map(t => '<li class="dre-tenant__row" role="option" tabindex="-1" aria-selected="false" data-i="' + t.i + '" style="--c:' + CAT[t.cat][1] + '"><span class="rk"></span>' +
  '<span class="nm"><i></i><span>' + esc(t.name) + '</span></span><span class="br"><i></i></span><span class="v"></span></li>').join('');
function ranked() {
  const k = S.sort;
  return T.slice().sort((a, b) => k === 'score' ? b.score - a.score : k === 'ocr' ? a.ocr - b.ocr : b.wPsf - a.wPsf);
}
function paintList(animate) {
