  const rows = () => $$('.dre-tenant__row:not(.is-out)', list);
  const mutate = () => {
    let r = 0;
    order.forEach(t => {
      const li = list.querySelector('[data-i="' + t.i + '"]');
      li.classList.toggle('is-out', !visible(t));
