      const bar = li.querySelector('.br i'); bar.style.setProperty('--v', v.toFixed(3)); li.style.setProperty('--rc', S.sort === 'score' ? ramp(t.score) : S.sort === 'ocr' ? (t.ocr > OCR_T ? 'var(--dre-tenant-bad)' : 'var(--dre-tenant-good)') : CAT[t.cat][1]);
      li.querySelector('.v').textContent = S.sort === 'score' ? t.score : S.sort === 'ocr' ? pct(t.ocr) : '$' + Math.round(t.wPsf);
      const nm = li.querySelector('.nm'), fl = nm.querySelector('svg');
      if (S.watch.has(t.i) && !fl) nm.insertAdjacentHTML('beforeend', FLAG); else if (!S.watch.has(t.i) && fl) fl.remove();
      li.setAttribute('aria-label', '#' + r + ' ' + t.name + ', health ' + t.score + ', occupancy cost ' + pct(t.ocr));
      list.appendChild(li);
