}
list.addEventListener('click', e => { const li = e.target.closest('.dre-tenant__row'); if (li) select(+li.dataset.i); });
list.addEventListener('keydown', e => {
  const li = e.target.closest('.dre-tenant__row'); if (!li) return;
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(+li.dataset.i); return; }
  const it = $$('.dre-tenant__row:not(.is-out)', list), k = it.indexOf(li);
