radioGroup($('.dre-tenant__sort'), v => { S.sort = v; paintList(true); });

/* ------------------------------------------------------------------ detail card */
const card = $('.dre-tenant__card');
function paintCard() {
  const t = T[S.sel], booked = S.booked.get(t.i), w = S.watch.has(t.i);
  const fRow = (lab, v, txt) => '<dt>' + lab + '</dt><dd><i style="--v:' + v.toFixed(3) + ';--fc:' + ramp(30 + v * 50) + '"></i></dd><span>' + txt + '</span>';
  card.innerHTML = '<div class="dre-tenant__ch"><div><h3>' + esc(t.name) + '</h3></div><div class="dre-tenant__ring" style="--dre-tenant-score:' + t.score + ';--rc:' + ramp(t.score) + '"><b>' + t.score + '</b></div>' +
    '<p>' + CAT[t.cat][0] + ' · unit ' + t.unit + ' · ' + NF.format(t.sf) + ' sf · lease to ' + leaseTxt(t.lease) + ' · <b>' + QN[t.q] + '</b></p></div>' +
    '<dl class="dre-tenant__factors">' +
    fRow('Occupancy cost', t.f.ocr, pct(t.ocr)) + fRow('Sales growth ' + S.W + 'M', t.f.growth, sg(t.growth)) +
    fRow('Sales per sf', t.f.psf, '$' + t.psf + ' <small>/ $' + CAT[t.cat][2] + '</small>') + fRow('Payments', t.f.pay, t.late ? t.late + 'd late' : 'on time') + fRow('Lease term', t.f.lease, t.yrs.toFixed(1) + ' yrs') + '</dl>' +
    '<svg class="dre-tenant__spark" role="img" aria-label="Monthly sales for 24 months against monthly rent and charges"></svg>' +
    '<div class="dre-tenant__acts"><button type="button" data-a="watch" aria-pressed="' + w + '">' + FLAG.replace('aria-hidden="true"', 'aria-hidden="true" style="width:13px;height:13px;fill:currentColor"') + (w ? 'On watchlist' : 'Add to watchlist') + '</button>' +
    '<button type="button" data-a="book"' + (booked ? ' disabled title="Check-in already booked"' : '') + '><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="5.5" width="16" height="14" rx="2"/><path d="M4 10h16M8.5 3.5v4M15.5 3.5v4"/></svg>' + (booked ? 'Check-in booked' : 'Book a check-in') + '</button></div>' +
    '<p class="dre-tenant__conf">' + (booked || '') + '</p>';
