}
card.addEventListener('pointermove', e => {
  const b = e.target.closest('.dre-tenant__spark rect'); $$('.dre-tenant__spark rect', card).forEach(x => x.classList.toggle('is-hot', x === b));
  if (!b) { if (!e.target.closest('.dre-tenant__spark')) hideTip(tip); return; }
  const t = T[S.sel], m = +b.dataset.m, v = t.sales[m];
  placeTip(tip, '<b>' + MON[cal(m)] + ' ' + yr(m) + '</b><span>Sales ' + money(v) + '</span><span>Rent and charges ' + money(t.occ / 12) + ' · ' + pct(t.occ / 12 / v) + '</span>', e.clientX, e.clientY);
});
card.addEventListener('pointerleave', () => { hideTip(tip); $$('.dre-tenant__spark rect', card).forEach(x => x.classList.remove('is-hot')); });
card.addEventListener('click', e => {
  const b = e.target.closest('button[data-a]'); if (!b || b.disabled) return;
  const t = T[S.sel];
  if (b.dataset.a === 'watch') {
    if (S.watch.has(t.i)) S.watch.delete(t.i); else S.watch.add(t.i);
    toast(S.watch.has(t.i) ? '<b>' + esc(t.name) + '</b> is on the watchlist' : esc(t.name) + ' taken off the watchlist');
    paintCard(); kpis(); paintList(false); paintMarks(); paintPlan();
    card.querySelector('[data-a="watch"]').focus();
  } else {
    b.disabled = true; b.lastChild.textContent = 'Booking…';
    setTimeout(() => {
      if (!root.isConnected) return;
      const slots = ['Tue 6 Oct, 10:30', 'Wed 7 Oct, 14:00', 'Thu 8 Oct, 09:30', 'Fri 9 Oct, 11:00'];
      S.booked.set(t.i, 'Check-in booked for ' + slots[S.booked.size % slots.length] + ' with Sana Iqbal, centre manager.');
      if (S.sel === t.i) paintCard();
      toast('Check-in with <b>' + esc(t.name) + '</b> booked');
    }, RM ? 120 : 700);
  }
});

/* ------------------------------------------------------------------ selection + view */
function paintMarks() {
  $$('.tn', sc).forEach(g => {
    const t = T[+g.dataset.i], on = t.i === S.sel;
    g.setAttribute('aria-selected', String(on)); g.setAttribute('tabindex', on ? '0' : '-1');
    g.toggleAttribute('data-watch', S.watch.has(t.i));
    g.classList.toggle('is-out', !visible(t)); g.classList.toggle('is-dim', visible(t) && !!dim(t));
  });
