@property --dre-value-meter { syntax: "<number>"; inherits: true; initial-value: 0; }
@property --dre-value-prog { syntax: "<number>"; inherits: true; initial-value: 0; }

.dre-value {
  /* re-theme with these four */
  --dre-value-bg: oklch(0.205 0.02 22);
  --dre-value-ink: oklch(0.95 0.014 78);
  --dre-value-gain: oklch(0.79 0.085 186);
  --dre-value-loss: oklch(0.68 0.15 30);
  /* derived */
  --dre-value-gold: oklch(0.85 0.115 84);
  --dre-value-panel: color-mix(in oklch, var(--dre-value-bg) 94%, var(--dre-value-ink));
  --dre-value-raise: color-mix(in oklch, var(--dre-value-bg) 87%, var(--dre-value-ink));
  --dre-value-deep: color-mix(in oklch, var(--dre-value-bg) 80%, black);
  --dre-value-line: color-mix(in oklch, var(--dre-value-ink) 11%, transparent);
  --dre-value-soft: color-mix(in oklch, var(--dre-value-ink) 6%, transparent);
  --dre-value-mute: color-mix(in oklch, var(--dre-value-ink) 64%, var(--dre-value-bg));
  --dre-value-faint: color-mix(in oklch, var(--dre-value-ink) 42%, var(--dre-value-bg));
  --dre-value-cell: color-mix(in oklch, var(--dre-value-bg) 84%, var(--dre-value-ink));
  --dre-value-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dre-value-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dre-value-out: cubic-bezier(.16, 1, .3, 1);
  --dre-value-spring: linear(0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 25.3%, 0.849 31.5%, 0.937 38.1%, 0.968 41.8%, 0.991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);

  width: 100%;
  height: var(--dre-value-h, 680px);
  container-type: inline-size; container-name: dre-value;
  position: relative; isolation: isolate; overflow: hidden;
  display: grid; grid-template-rows: auto minmax(0, 1fr);
  border-radius: 16px;
  background:
    radial-gradient(90% 60% at 0% 0%, color-mix(in oklch, var(--dre-value-loss) 9%, transparent), transparent 70%),
    var(--dre-value-bg);
  color: var(--dre-value-ink);
  font: 13px/1.45 var(--dre-value-sans);
  accent-color: var(--dre-value-gold);
  color-scheme: dark;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, dl, dd, ul, fieldset, legend) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(fieldset) { border: 0; min-width: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--dre-value-gold); outline-offset: 2px; border-radius: 6px; }
  & .dre-value__num { font-variant-numeric: tabular-nums; }
  & .dre-value__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dre-value__scroll { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dre-value-ink) 20%, transparent) transparent; }
  & [hidden] { display: none !important; }
}

/* ---------- header */
.dre-value__head {
  display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: center; gap: 10px 16px;
  padding: 14px 18px 12px; border-bottom: 1px solid var(--dre-value-line);
  & h2 { font-size: clamp(19px, 2.2cqi, 26px); font-weight: 760; letter-spacing: -.035em; line-height: 1.05; text-wrap: balance; }
}
.dre-value__brand { display: flex; align-items: center; gap: 12px; min-width: 0; }
.dre-value__mark {
  flex: none; width: 38px; height: 38px; border-radius: 11px; display: grid; place-items: center;
  background: var(--dre-value-gold); color: var(--dre-value-bg);
  & svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
}
.dre-value__eyebrow { font-size: 11.5px; color: var(--dre-value-mute); margin-bottom: 3px; font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dre-value__views {
  display: inline-flex; gap: 2px; padding: 3px; border-radius: 11px; background: var(--dre-value-soft);
  & [role=tab] { padding: 6px 12px; border-radius: 8px; font-size: 12.5px; font-weight: 640; color: var(--dre-value-mute); transition: background-color .2s, color .2s; }
  & [role=tab]:hover { color: var(--dre-value-ink); }
  & [role=tab][aria-selected=true] { background: var(--dre-value-ink); color: var(--dre-value-bg); }
}
.dre-value__acts { display: flex; gap: 8px; }
.dre-value__btn {
  position: relative; overflow: hidden; display: inline-flex; align-items: center; gap: 7px; padding: 7px 12px; border-radius: 10px;
  font-size: 12.5px; font-weight: 640; white-space: nowrap;
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dre-value-ink) 22%, transparent);
  transition: background-color .2s, color .2s, box-shadow .2s, scale .3s var(--dre-value-spring);
  &:hover { background: var(--dre-value-soft); }
  &:active { scale: .97; }
  & svg { width: 15px; height: 15px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
  &.is-solid { background: var(--dre-value-gold); color: var(--dre-value-bg); box-shadow: none; }
  &.is-solid:hover { background: color-mix(in oklch, var(--dre-value-gold) 86%, white); }
  &[aria-pressed=true] { background: color-mix(in oklch, var(--dre-value-gold) 16%, transparent); box-shadow: inset 0 0 0 1px var(--dre-value-gold); color: var(--dre-value-gold); }
  &[aria-pressed=true] svg { fill: currentColor; }
  &[aria-disabled=true] { opacity: .45; cursor: not-allowed; }
  &::after { content: ""; position: absolute; left: 0; bottom: 0; height: 3px; width: 100%; background: var(--dre-value-bg); opacity: .5; transform-origin: left; transform: scaleX(var(--dre-value-prog)); }
  &[aria-busy=true] { transition: --dre-value-prog 1.3s cubic-bezier(.3, .1, .2, 1); --dre-value-prog: 1; cursor: progress; }
}

/* ---------- body */
.dre-value__body { min-height: 0; display: grid; grid-template-columns: 252px minmax(0, 1fr); grid-template-areas: "side main"; }

/* ---------- assumptions */
.dre-value__side {
  grid-area: side; min-height: 0; padding: 14px 14px 16px; display: grid; align-content: start; gap: 12px;
  border-right: 1px solid var(--dre-value-line); background: color-mix(in oklch, var(--dre-value-deep) 55%, transparent);
}
.dre-value__sc {
  display: grid; grid-template-columns: 1fr 1fr; gap: 3px; padding: 3px; border-radius: 11px; background: var(--dre-value-soft);
  & [role=radio] { padding: 6px 8px; border-radius: 8px; font-size: 12px; font-weight: 640; text-align: center; color: var(--dre-value-mute); transition: background-color .2s, color .2s; }
  & [role=radio]:hover { color: var(--dre-value-ink); }
  & [role=radio][aria-checked=true] { background: var(--dre-value-raise); color: var(--dre-value-ink); box-shadow: inset 0 0 0 1px var(--dre-value-line); }
}
.dre-value__custom {
  display: flex; align-items: center; gap: 7px; font-size: 11.5px; color: var(--dre-value-gold); margin-top: -4px;
  & i { width: 7px; height: 7px; border-radius: 50%; background: currentColor; box-shadow: 0 0 0 3px color-mix(in oklch, currentColor 22%, transparent); }
  & span { font-weight: 640; }
  & button { margin-left: auto; font-size: 11.5px; font-weight: 640; color: var(--dre-value-ink); text-decoration: underline; text-decoration-color: var(--dre-value-faint); text-underline-offset: 3px; }
  & button:hover { text-decoration-color: currentColor; }
  @starting-style { opacity: 0; translate: 0 -4px; }
  transition: opacity .25s, translate .35s var(--dre-value-out);
}
.dre-value__fs {
  display: grid; gap: 10px; align-content: start;
  animation: dre-value-rise .6s var(--dre-value-out) both; animation-delay: calc(var(--i) * 70ms + 120ms);
  & legend { font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dre-value-faint); margin-bottom: 8px; }
}
.dre-value__field {
  --t: 14px;
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 3px 8px; align-items: baseline;
  & > span:first-child { font-size: 12px; font-weight: 560; color: var(--dre-value-mute); }
  & output { font: 650 12.5px var(--dre-value-mono); font-variant-numeric: tabular-nums; color: var(--dre-value-ink); }
  & small { grid-column: 1 / -1; font-size: 10.5px; color: var(--dre-value-faint); font-variant-numeric: tabular-nums; margin-top: -1px; }
  &:has(input:focus-visible) > span:first-child, &:hover > span:first-child { color: var(--dre-value-ink); }
  &.is-off output { color: var(--dre-value-gold); }
}
.dre-value__track {
  grid-column: 1 / -1; position: relative; display: block; height: 18px;
  /* the base-case notch sits where the thumb centre would be at the base value */
  &::after {
    content: ""; position: absolute; top: 3px; width: 2px; height: 12px; border-radius: 1px; pointer-events: none;
    left: calc(var(--t) / 2 + (100% - var(--t)) * var(--b, 0) - 1px);
    background: var(--dre-value-faint); opacity: 0; transition: opacity .25s;
  }
  .dre-value__field.is-off &::after { opacity: 1; }
  & input {
    -webkit-appearance: none; appearance: none; display: block; width: 100%; height: 18px; margin: 0; background: none; cursor: pointer;
    --fill: calc(var(--t) / 2 + (100% - var(--t)) * var(--f, 0));
  }
  & input::-webkit-slider-runnable-track {
    height: 4px; border-radius: 4px;
    background: linear-gradient(to right, var(--dre-value-gold) 0 var(--fill), color-mix(in oklch, var(--dre-value-ink) 14%, transparent) 0);
  }
  & input::-moz-range-track { height: 4px; border-radius: 4px; background: color-mix(in oklch, var(--dre-value-ink) 14%, transparent); }
  & input::-moz-range-progress { height: 4px; border-radius: 4px; background: var(--dre-value-gold); }
  & input::-webkit-slider-thumb {
    -webkit-appearance: none; width: var(--t); height: var(--t); margin-top: -5px; border-radius: 50%;
    background: var(--dre-value-ink); box-shadow: 0 0 0 3px var(--dre-value-bg), 0 2px 6px #0008; transition: scale .25s var(--dre-value-spring);
  }
  & input::-moz-range-thumb { width: var(--t); height: var(--t); border: 0; border-radius: 50%; background: var(--dre-value-ink); box-shadow: 0 0 0 3px var(--dre-value-bg); }
  & input:hover::-webkit-slider-thumb, & input:active::-webkit-slider-thumb { scale: 1.18; }
  & input:focus-visible { outline: 2px solid var(--dre-value-gold); outline-offset: 3px; border-radius: 9px; }
}
.dre-value__fixed { font-size: 11px; line-height: 1.5; color: var(--dre-value-faint); text-wrap: pretty; padding-top: 10px; border-top: 1px solid var(--dre-value-line); }

/* ---------- main */
.dre-value__main { grid-area: main; min-width: 0; min-height: 0; display: grid; }
.dre-value__view { min-width: 0; min-height: 0; padding: 14px 16px 16px; }
.dre-value__model {
  display: grid; gap: 12px;
  grid-template-columns: minmax(0, 1fr) 318px; grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "kpis kpis" "cf sens";
}
.dre-value__kpis {
  grid-area: kpis; display: grid; grid-template-columns: 1.2fr repeat(4, minmax(0, 1fr)); gap: 10px;
  & > div {
    min-width: 0; padding: 10px 13px; border-radius: 12px; background: var(--dre-value-panel); box-shadow: inset 0 0 0 1px var(--dre-value-line);
    display: grid; align-content: start; gap: 1px;
    animation: dre-value-rise .55s var(--dre-value-out) both; animation-delay: calc(var(--i) * 45ms);
  }
  & dt { font-size: 11px; font-weight: 600; color: var(--dre-value-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { font-size: clamp(18px, 2cqi, 24px); font-weight: 730; letter-spacing: -.035em; line-height: 1.15; white-space: nowrap; }
  & small { font-size: 11px; color: var(--dre-value-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  & small b { font-weight: 650; color: var(--dre-value-mute); }
  & .is-hero { background: linear-gradient(135deg, color-mix(in oklch, var(--dre-value-gold) 15%, var(--dre-value-panel)), var(--dre-value-panel) 72%); }
  & .is-hero dd { color: var(--dre-value-gold); }
  & .is-hero[data-under] dd { color: var(--dre-value-loss); }
  & .is-bid dd { color: var(--dre-value-gain); }
  & .is-bid[data-under] dd { color: var(--dre-value-loss); }
}
/* IRR on a 0-20% scale with the target as a tick; the fill eases on a registered number */
.dre-value__meter {
  position: relative; display: block; height: 4px; margin: 5px 0 4px; border-radius: 4px; background: color-mix(in oklch, var(--dre-value-ink) 12%, transparent);
  & i { position: absolute; inset: 0; border-radius: inherit; background: var(--dre-value-gold); transform-origin: left; transform: scaleX(clamp(0, calc(var(--dre-value-meter) / 20), 1)); transition: --dre-value-meter .7s var(--dre-value-out); }
  & b { position: absolute; top: -3px; width: 2px; height: 10px; border-radius: 1px; background: var(--dre-value-ink); left: calc(var(--h, 50) / 20 * 100% - 1px); transition: left .45s var(--dre-value-spring); }
  [data-under] & i { background: var(--dre-value-loss); }
}

.dre-value__panel {
  min-height: 0; min-width: 0; border-radius: 14px; background: var(--dre-value-panel); box-shadow: inset 0 0 0 1px var(--dre-value-line);
  padding: 11px 12px 10px;
  animation: dre-value-rise .6s var(--dre-value-out) both; animation-delay: calc(var(--i, 0) * 45ms);
}
.dre-value__ph {
  display: flex; align-items: center; justify-content: space-between; gap: 6px 12px; flex-wrap: wrap; margin-bottom: 6px; padding-inline: 2px;
  & h3 { font-size: 13px; font-weight: 680; text-wrap: balance; }
}
.dre-value__keys {
  display: flex; gap: 4px 11px; flex-wrap: wrap; font-size: 11px; color: var(--dre-value-mute);
  & > span { display: inline-flex; align-items: center; gap: 5px; }
  & i { width: 9px; height: 9px; border-radius: 2px; flex: none; }
  & b { font-weight: 600; }
  & .k-in { background: var(--dre-value-loss); }
  & .k-dist { background: color-mix(in oklch, var(--dre-value-gain) 75%, var(--dre-value-bg)); }
  & .k-sale { background: var(--dre-value-gold); }
  & .k-cum { height: 2px; border-radius: 1px; background: var(--dre-value-ink); }
  & .k-pin { height: 0; border-top: 2px dashed var(--dre-value-mute); border-radius: 0; }
  & .k-comp { border-radius: 50%; background: var(--dre-value-gain); }
  & .k-out { border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--dre-value-faint); }
  & .k-bid { rotate: 45deg; width: 8px; height: 8px; border-radius: 1px; box-shadow: inset 0 0 0 2px var(--dre-value-gold); }
}

/* ---------- equity cash-flow chart */
.dre-value__cf { grid-area: cf; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; }
.dre-value__plot { position: relative; min-height: 0; }
.dre-value__chart, .dre-value__scat {
  position: absolute; inset: 0; width: 100%; height: 100%; touch-action: none;
  & .ax line { stroke: var(--dre-value-line); }
  & .ax .z { stroke: color-mix(in oklch, var(--dre-value-ink) 34%, transparent); }
  & text { font: 500 10.5px var(--dre-value-mono); fill: var(--dre-value-faint); font-variant-numeric: tabular-nums; }
  & .ax .xl { fill: var(--dre-value-mute); }
  & .ax .xl.is-exit { fill: var(--dre-value-gold); font-weight: 650; }
  & .band { fill: var(--dre-value-soft); opacity: 0; transition: opacity .15s; }
  & .band[data-on] { opacity: 1; }
  & .bar { transition: opacity .2s; }
  & .bar.in { fill: color-mix(in oklch, var(--dre-value-loss) 82%, var(--dre-value-bg)); }
  & .bar.dist { fill: color-mix(in oklch, var(--dre-value-gain) 75%, var(--dre-value-bg)); }
  & .bar.dist.neg { fill: color-mix(in oklch, var(--dre-value-loss) 60%, var(--dre-value-bg)); }
  & .bar.sale { fill: var(--dre-value-gold); }
  & .area.up { fill: color-mix(in oklch, var(--dre-value-gain) 16%, transparent); }
  & .area.dn { fill: color-mix(in oklch, var(--dre-value-loss) 13%, transparent); }
  & .cum { fill: none; stroke: var(--dre-value-ink); stroke-width: 2; stroke-linejoin: round; }
  & .pin { fill: none; stroke: var(--dre-value-mute); stroke-width: 1.6; stroke-dasharray: 5 4; }
  & .prev { fill: none; stroke: var(--dre-value-gold); stroke-width: 1.8; stroke-dasharray: 2 3; stroke-linecap: round; }
  & .dot { fill: var(--dre-value-bg); stroke: var(--dre-value-ink); stroke-width: 1.8; }
  & .dot.end { fill: var(--dre-value-ink); }
  & .lbl { font: 650 11px var(--dre-value-sans); fill: var(--dre-value-ink); }
  & .lbl.sub { font: 500 10.5px var(--dre-value-mono); fill: var(--dre-value-mute); }
  & .lbl.gold { fill: var(--dre-value-gold); }
  & .hit { fill: transparent; cursor: crosshair; }
}
.dre-value__chart { overflow: hidden; }

/* profit attribution */
.dre-value__attr { padding-top: 10px; margin-top: 8px; border-top: 1px solid var(--dre-value-line); display: grid; gap: 7px; }
.dre-value__ah {
  display: flex; align-items: baseline; justify-content: space-between; gap: 4px 12px; flex-wrap: wrap;
  & h4 { font-size: 12px; font-weight: 660; }
  & p { font-size: 11.5px; color: var(--dre-value-mute); font-variant-numeric: tabular-nums; }
  & p b { color: var(--dre-value-ink); font-weight: 680; }
}
.dre-value__abar {
  width: 100%; height: 40px;
  & rect { rx: 3px; }
  & .s-inc { fill: color-mix(in oklch, var(--dre-value-gain) 75%, var(--dre-value-bg)); }
  & .s-growth { fill: color-mix(in oklab, var(--dre-value-gain) 55%, var(--dre-value-ink)); }
  & .s-cap { fill: var(--dre-value-gold); }
  & .s-cap.neg, & .s-costs { fill: color-mix(in oklch, var(--dre-value-loss) 80%, var(--dre-value-bg)); }
  & .zero { stroke: color-mix(in oklch, var(--dre-value-ink) 40%, transparent); }
  & .tot { stroke: var(--dre-value-ink); stroke-width: 2; }
  & .link { stroke: var(--dre-value-faint); stroke-dasharray: 2 2; }
}
.dre-value__alist {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 4px 12px;
  & li { display: grid; grid-template-columns: 9px minmax(0, 1fr); gap: 0 6px; align-items: baseline; font-size: 11px; color: var(--dre-value-mute); min-width: 0; }
  & li i { width: 9px; height: 9px; border-radius: 2px; align-self: center; }
  & li span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & li b { grid-column: 2; font: 650 12px var(--dre-value-mono); color: var(--dre-value-ink); font-variant-numeric: tabular-nums; }
  & .s-inc { background: color-mix(in oklch, var(--dre-value-gain) 75%, var(--dre-value-bg)); }
  & .s-growth { background: color-mix(in oklab, var(--dre-value-gain) 55%, var(--dre-value-ink)); }
  & .s-cap { background: var(--dre-value-gold); }
  & .s-cap.neg, & .s-costs { background: color-mix(in oklch, var(--dre-value-loss) 80%, var(--dre-value-bg)); }
}

/* ---------- sensitivity grid */
.dre-value__sens { grid-area: sens; display: grid; grid-template-rows: auto auto minmax(200px, 1fr) auto auto; }
.dre-value__seg {
  display: inline-flex; gap: 2px; padding: 2px; border-radius: 9px; background: var(--dre-value-soft);
  & [role=radio] { padding: 3px 9px; border-radius: 7px; font-size: 11.5px; font-weight: 640; color: var(--dre-value-mute); transition: background-color .2s, color .2s; }
  & [role=radio]:hover { color: var(--dre-value-ink); }
  & [role=radio][aria-checked=true] { background: var(--dre-value-ink); color: var(--dre-value-bg); }
}
.dre-value__sbar { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 8px; flex-wrap: wrap; }
.dre-value__pair {
  font: 600 11.5px var(--dre-value-sans); color: var(--dre-value-ink); background: var(--dre-value-raise); border: 0; border-radius: 8px; padding: 5px 8px;
  box-shadow: inset 0 0 0 1px var(--dre-value-line); max-width: 100%; cursor: pointer;
}
.dre-value__hurdle {
  display: inline-flex; align-items: center; gap: 4px; font-size: 11px; color: var(--dre-value-mute);
  & b { font: 650 12px var(--dre-value-mono); color: var(--dre-value-gold); min-width: 46px; text-align: center; font-variant-numeric: tabular-nums; }
}
.dre-value__step {
  width: 22px; height: 22px; border-radius: 7px; display: grid; place-items: center; box-shadow: inset 0 0 0 1px var(--dre-value-line); transition: background-color .2s;
  &:hover { background: var(--dre-value-soft); }
  & svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; }
  &[aria-disabled=true] { opacity: .35; cursor: not-allowed; }
}
.dre-value__gwrap {
  display: grid; grid-template-columns: 14px 38px minmax(0, 1fr); grid-template-rows: auto minmax(190px, 1fr) auto;
  grid-template-areas: "y . cols" "y rows grid" ". . x"; gap: 3px 4px; min-height: 0;
}
.dre-value__ylab, .dre-value__xlab { font-size: 10px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--dre-value-faint); }
.dre-value__ylab { grid-area: y; writing-mode: vertical-rl; rotate: 180deg; text-align: center; align-self: center; }
.dre-value__xlab { grid-area: x; text-align: center; }
.dre-value__cols, .dre-value__rows { display: grid; font: 500 10.5px var(--dre-value-mono); color: var(--dre-value-mute); font-variant-numeric: tabular-nums; }
.dre-value__cols { grid-area: cols; grid-template-columns: repeat(7, minmax(0, 1fr)); text-align: center; }
.dre-value__rows { grid-area: rows; grid-template-rows: repeat(7, minmax(0, 1fr)); align-items: center; text-align: right; }
.dre-value__cols span.is-cur, .dre-value__rows span.is-cur { color: var(--dre-value-gold); font-weight: 700; }
.dre-value__gbox { grid-area: grid; position: relative; min-height: 0; }
.dre-value__grid {
  display: grid; grid-template-rows: repeat(7, minmax(26px, 1fr)); gap: 2px; height: 100%;
  & [role=row] { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 2px; }
  & [role=gridcell] {
    --m: 0;
    display: grid; place-items: center; border-radius: 5px; min-width: 0;
    font: 600 11px var(--dre-value-mono); font-variant-numeric: tabular-nums; color: var(--dre-value-ink);
    background: color-mix(in oklab, var(--dre-value-gain) calc(var(--m) * 1%), var(--dre-value-cell));
    transition: background-color .35s, color .35s, scale .3s var(--dre-value-spring), box-shadow .2s;
    animation: dre-value-pop .5s var(--dre-value-out) both; animation-delay: calc(var(--i) * 9ms + 260ms);
  }
  & [role=gridcell][data-s="-1"] { background: color-mix(in oklab, var(--dre-value-loss) calc(var(--m) * 1%), var(--dre-value-cell)); }
  & [role=gridcell][data-hi] { color: var(--dre-value-bg); }
  & [role=gridcell]:hover, & [role=gridcell]:focus-visible { scale: 1.12; z-index: 2; box-shadow: 0 6px 16px -6px #000, inset 0 0 0 1.5px var(--dre-value-ink); outline: none; }
  & [role=gridcell][aria-selected=true] { color: var(--dre-value-gold); font-weight: 750; }
  & [role=gridcell][aria-selected=true][data-hi] { color: var(--dre-value-bg); }
  & [role=gridcell].is-flash { animation: dre-value-flash .6s var(--dre-value-out); }
}
.dre-value__iso { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none;
  & path { fill: none; stroke: var(--dre-value-ink); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; vector-effect: non-scaling-stroke; stroke-dasharray: 5 3; }
}
.dre-value__here {
  position: absolute; left: 0; top: 0; width: 30px; height: 24px; margin: -12px 0 0 -15px; border-radius: 8px; pointer-events: none; z-index: 3;
  border: 2px solid var(--dre-value-gold);
  box-shadow: 0 0 0 2px color-mix(in oklch, var(--dre-value-bg) 75%, transparent), 0 0 18px -2px color-mix(in oklch, var(--dre-value-gold) 60%, transparent);
  transition: translate .55s var(--dre-value-spring);
}
.dre-value__legend {
  display: flex; align-items: center; gap: 6px; margin-top: 8px; font-size: 10.5px; color: var(--dre-value-faint);
  & > i { flex: 1; max-width: 110px; height: 6px; border-radius: 3px; background: linear-gradient(to right, var(--dre-value-loss), var(--dre-value-cell), var(--dre-value-gain)); }
  & .iso { margin-left: auto; display: inline-flex; align-items: center; gap: 5px; }
  & .iso i { width: 16px; border-top: 2px dashed var(--dre-value-ink); }
}
.dre-value__cap {
  margin-top: 6px; min-height: 34px; font-size: 11.5px; line-height: 1.45; color: var(--dre-value-mute); text-wrap: pretty; font-variant-numeric: tabular-nums;
  & b { color: var(--dre-value-ink); font-weight: 650; }
  & .up { color: var(--dre-value-gain); } & .dn { color: var(--dre-value-loss); }
}

/* ---------- comps view */
.dre-value__comps { display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 12px; }
.dre-value__csum {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)) auto; align-items: center; gap: 10px 16px;
  padding: 12px 14px; border-radius: 14px; background: var(--dre-value-panel); box-shadow: inset 0 0 0 1px var(--dre-value-line);
  animation: dre-value-rise .5s var(--dre-value-out) both;
  & > div { display: grid; min-width: 0; }
  & b { font-size: clamp(18px, 2cqi, 24px); font-weight: 730; letter-spacing: -.03em; line-height: 1.15; }
  & > div:nth-child(2) b { color: var(--dre-value-gold); }
  & small { font-size: 11px; color: var(--dre-value-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.dre-value__cgrid { min-height: 0; display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr); gap: 12px; }
.dre-value__ctab { padding: 4px 0 0; display: grid; animation-delay: 60ms; }
.dre-value__tscroll { min-height: 0; padding: 0 6px 6px; }
.dre-value__ctab table {
  font-size: 12px; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dre-value-panel); padding: 8px 6px; text-align: left; font-size: 10.5px; font-weight: 650; letter-spacing: .05em; text-transform: uppercase; color: var(--dre-value-faint); white-space: nowrap; }
  & th.r, & td.r { text-align: right; }
  & th button { font: inherit; letter-spacing: inherit; text-transform: inherit; color: inherit; display: inline-flex; align-items: center; gap: 3px; }
  & th button:hover { color: var(--dre-value-ink); }
  & th[aria-sort=ascending] button, & th[aria-sort=descending] button { color: var(--dre-value-gold); }
  & th[aria-sort=ascending] button::after { content: "\2191"; }
