/* ---------------- one path for every change: ease the displayed assumptions to the target */
function go(to, dur, src) {
  const from = Object.assign({}, S.p), tok = ++goTok;
  S.t = Object.assign({}, to);
  syncScenario();
  if (!dur || RM) { S.p = Object.assign({}, to); update(src); return; }
  tween(dur, k => {
    if (tok !== goTok) return;
    KEYS.forEach(key => { S.p[key] = from[key] + (to[key] - from[key]) * k; });
    if (k === 1) S.p = Object.assign({}, to);
