@property --dre-deals-pct { syntax: "<number>"; inherits: true; initial-value: 0; }

.dre-deals {
  /* re-theme with these four: the stage ramp runs from early to late */
  --dre-deals-bg: oklch(0.972 0.007 100);
  --dre-deals-ink: oklch(0.25 0.025 165);
  --dre-deals-early: oklch(0.87 0.075 84);
  --dre-deals-late: oklch(0.46 0.095 163);
  /* derived */
  --dre-deals-accent: oklch(0.62 0.19 33);
  --dre-deals-s0: var(--dre-deals-early);
  --dre-deals-s1: color-mix(in oklch, var(--dre-deals-late) 22%, var(--dre-deals-early));
  --dre-deals-s2: color-mix(in oklch, var(--dre-deals-late) 45%, var(--dre-deals-early));
  --dre-deals-s3: color-mix(in oklch, var(--dre-deals-late) 68%, var(--dre-deals-early));
  --dre-deals-s4: var(--dre-deals-late);
  --dre-deals-s5: var(--dre-deals-ink);
  --dre-deals-card: color-mix(in oklch, var(--dre-deals-bg) 35%, white);
  --dre-deals-line: color-mix(in oklch, var(--dre-deals-ink) 12%, transparent);
  --dre-deals-soft: color-mix(in oklch, var(--dre-deals-ink) 5%, transparent);
  --dre-deals-mute: color-mix(in oklch, var(--dre-deals-ink) 66%, var(--dre-deals-bg));
  --dre-deals-faint: color-mix(in oklch, var(--dre-deals-ink) 45%, var(--dre-deals-bg));
  --dre-deals-land: color-mix(in oklch, var(--dre-deals-bg) 86%, var(--dre-deals-early));
  --dre-deals-block: color-mix(in oklch, var(--dre-deals-land) 90%, var(--dre-deals-ink));
  --dre-deals-water: oklch(0.86 0.04 222);
  --dre-deals-park: color-mix(in oklch, var(--dre-deals-late) 22%, var(--dre-deals-land));
  --dre-deals-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dre-deals-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dre-deals-out: cubic-bezier(.16, 1, .3, 1);
  --dre-deals-spring: linear(0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 25.3%, 0.849 31.5%, 0.937 38.1%, 0.968 41.8%, 0.991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);

  width: 100%;
  height: var(--dre-deals-h, 680px);
  container-type: inline-size; container-name: dre-deals;
  position: relative; isolation: isolate; overflow: hidden;
  display: block;
  border-radius: 16px;
  background: var(--dre-deals-bg);
  color: var(--dre-deals-ink);
  font: 13px/1.45 var(--dre-deals-sans);
  accent-color: var(--dre-deals-late);
  color-scheme: light;
  box-shadow: inset 0 0 0 1px var(--dre-deals-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, dl, dd, ol, ul) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(svg) { display: block; overflow: visible; }
  & :focus-visible { outline: 2px solid var(--dre-deals-accent); outline-offset: 2px; border-radius: 6px; }
  & .dre-deals__num { font-variant-numeric: tabular-nums; }
  & .dre-deals__scroll { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dre-deals-ink) 22%, transparent) transparent; }
  & [hidden] { display: none !important; }
  & [data-st="0"] { --c: var(--dre-deals-s0); } & [data-st="1"] { --c: var(--dre-deals-s1); } & [data-st="2"] { --c: var(--dre-deals-s2); }
  & [data-st="3"] { --c: var(--dre-deals-s3); } & [data-st="4"] { --c: var(--dre-deals-s4); } & [data-st="5"] { --c: var(--dre-deals-s5); }
}

.dre-deals__shell { height: 100%; display: grid; grid-template-columns: 66px minmax(0, 1fr); grid-template-areas: "rail main"; }

/* ---------- rail */
.dre-deals__rail {
  grid-area: rail; display: grid; grid-template-rows: auto 1fr auto; justify-items: center; gap: 14px; padding: 14px 8px;
  background: var(--dre-deals-ink); color: var(--dre-deals-bg); border-radius: 16px 0 0 16px;
}
