  }
  & [role=tab]:hover { color: var(--dre-deals-bg); background: color-mix(in oklch, var(--dre-deals-bg) 8%, transparent); }
  & [role=tab][aria-selected=true] { color: var(--dre-deals-ink); background: var(--dre-deals-early); }
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
}
.dre-deals__me { width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; font-weight: 700; background: color-mix(in oklch, var(--dre-deals-bg) 14%, transparent); }

/* ---------- main */
.dre-deals__main {
  grid-area: main; min-width: 0; min-height: 0; position: relative;
  display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 12px; padding: 14px 16px 16px;
}
.dre-deals__head {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: end; gap: 6px 16px;
  & h2 { font-size: clamp(19px, 2.2cqi, 26px); font-weight: 760; letter-spacing: -.035em; line-height: 1.05; text-wrap: balance; }
}
.dre-deals__eyebrow { font-size: 11.5px; color: var(--dre-deals-mute); margin-bottom: 3px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dre-deals__filters { display: flex; flex-wrap: wrap; justify-content: end; align-items: center; gap: 8px; }
.dre-deals__types {
  display: flex; gap: 4px; flex-wrap: wrap;
  & button {
    padding: 5px 10px 5px 8px; border-radius: 99px; font-size: 12px; font-weight: 620; display: inline-flex; align-items: center; gap: 6px;
    color: var(--dre-deals-faint); box-shadow: inset 0 0 0 1px var(--dre-deals-line); transition: background-color .2s, color .2s, box-shadow .2s;
  }
  & i { width: 13px; height: 13px; border-radius: 4px; display: grid; place-items: center; box-shadow: inset 0 0 0 1.5px currentColor; transition: background-color .2s, box-shadow .2s; }
  & i svg { width: 11px; height: 11px; fill: none; stroke: var(--dre-deals-card); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 10; stroke-dashoffset: 10; transition: stroke-dashoffset .3s var(--dre-deals-out); }
  & button[aria-pressed=true] { color: var(--dre-deals-ink); background: var(--dre-deals-card); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dre-deals-ink) 22%, transparent); }
  & button[aria-pressed=true] i { background: var(--dre-deals-ink); box-shadow: none; }
  & button[aria-pressed=true] i svg { stroke-dashoffset: 0; }
  & button:hover { color: var(--dre-deals-ink); }
}
.dre-deals__seg {
  display: inline-flex; gap: 2px; padding: 3px; border-radius: 10px; background: var(--dre-deals-soft);
  & [role=radio] { padding: 4px 10px; border-radius: 7px; font-size: 12px; font-weight: 640; color: var(--dre-deals-mute); white-space: nowrap; transition: background-color .2s, color .2s, box-shadow .2s; }
  & [role=radio]:hover { color: var(--dre-deals-ink); }
  & [role=radio][aria-checked=true] { background: var(--dre-deals-card); color: var(--dre-deals-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dre-deals-ink) 18%, transparent), inset 0 0 0 1px var(--dre-deals-line); }
  &.is-small [role=radio] { padding: 3px 8px; font-size: 11.5px; }
}
.dre-deals__chips {
  grid-column: 1 / -1; display: flex; flex-wrap: wrap; gap: 6px; min-height: 0;
  &:empty { display: none; }
  & button {
    display: inline-flex; align-items: center; gap: 6px; padding: 3px 6px 3px 10px; border-radius: 99px; font-size: 11.5px; font-weight: 620;
    background: color-mix(in oklch, var(--dre-deals-accent) 12%, var(--dre-deals-card)); color: color-mix(in oklch, var(--dre-deals-accent) 70%, var(--dre-deals-ink));
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dre-deals-accent) 30%, transparent);
    transition: background-color .2s;
    @starting-style { opacity: 0; scale: .9; }
  }
  & button { transition: opacity .25s, scale .35s var(--dre-deals-spring), background-color .2s; }
  & button:hover { background: color-mix(in oklch, var(--dre-deals-accent) 20%, var(--dre-deals-card)); }
  & button svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; }
}

/* ---------- KPIs */
.dre-deals__kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px;
  & > div {
    position: relative; min-width: 0; padding: 10px 14px; border-radius: 12px; background: var(--dre-deals-card); box-shadow: inset 0 0 0 1px var(--dre-deals-line);
    display: grid; gap: 1px; animation: dre-deals-rise .55s var(--dre-deals-out) both; animation-delay: calc(var(--i) * 50ms);
  }
  & dt { font-size: 11px; font-weight: 620; color: var(--dre-deals-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { font-size: clamp(18px, 2cqi, 24px); font-weight: 740; letter-spacing: -.035em; line-height: 1.15; }
  & small { font-size: 11px; color: var(--dre-deals-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  & small b { color: var(--dre-deals-ink); font-weight: 650; }
  & .is-ring { padding-right: 58px; }
}
/* progress to target as a conic ring; the registered number eases instead of jumping */
.dre-deals__ring {
  position: absolute; right: 12px; top: 50%; translate: 0 -50%; width: 38px; height: 38px; border-radius: 50%;
  background: conic-gradient(var(--dre-deals-late) calc(var(--dre-deals-pct) * 1%), color-mix(in oklch, var(--dre-deals-ink) 9%, transparent) 0);
  mask: radial-gradient(farthest-side, transparent calc(100% - 5px), #000 calc(100% - 4.5px));
  transition: --dre-deals-pct 1s var(--dre-deals-out);
}

/* ---------- pipeline view */
.dre-deals__view { min-width: 0; min-height: 0; }
.dre-deals__pipe {
  display: grid; gap: 10px; grid-template-columns: minmax(0, 1fr) 320px; grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "strip strip" "map list";
}
.dre-deals__strip {
  grid-area: strip; display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 4px;
  & button {
    position: relative; min-width: 0; padding: 7px 10px 8px 12px; text-align: left; display: grid; gap: 0;
    background: var(--dre-deals-card); box-shadow: inset 0 0 0 1px var(--dre-deals-line);
    clip-path: polygon(0 0, calc(100% - 9px) 0, 100% 50%, calc(100% - 9px) 100%, 0 100%, 9px 50%);
    transition: background-color .2s, opacity .25s;
    animation: dre-deals-rise .5s var(--dre-deals-out) both; animation-delay: calc(var(--i) * 40ms + 120ms);
  }
  & button:first-child { clip-path: polygon(0 0, calc(100% - 9px) 0, 100% 50%, calc(100% - 9px) 100%, 0 100%); border-radius: 10px 0 0 10px; }
  & button:last-child { clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%, 9px 50%); border-radius: 0 10px 10px 0; }
  & button::before { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 3px; background: var(--c); }
  & button:hover { background: color-mix(in oklch, var(--c) 14%, var(--dre-deals-card)); }
  & button[aria-pressed=true] { background: color-mix(in oklch, var(--c) 30%, var(--dre-deals-card)); }
  &:has(button[aria-pressed=true]) button[aria-pressed=false] { opacity: .5; }
  & .n { font-size: 10.5px; font-weight: 660; color: var(--dre-deals-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; padding-left: 4px; }
  & .v { font: 680 14px var(--dre-deals-sans); letter-spacing: -.02em; font-variant-numeric: tabular-nums; padding-left: 4px; white-space: nowrap; }
  & .v small { font: 500 11px var(--dre-deals-sans); color: var(--dre-deals-faint); margin-left: 4px; }
}

.dre-deals__mapbox {
  grid-area: map; position: relative; min-height: 0; min-width: 0; border-radius: 14px; overflow: hidden;
  background: var(--dre-deals-land); box-shadow: inset 0 0 0 1px var(--dre-deals-line);
}
.dre-deals__map {
  position: absolute; inset: 0; width: 100%; height: 100%; cursor: crosshair; touch-action: none; user-select: none;
  & .bay, & .river { fill: var(--dre-deals-water); }
  & .river { fill: none; stroke: var(--dre-deals-water); stroke-width: 34; stroke-linecap: round; }
  & .riv-name { font: italic 500 13px var(--dre-deals-sans); fill: color-mix(in oklch, var(--dre-deals-water) 45%, var(--dre-deals-ink)); letter-spacing: .14em; }
  & .park { fill: var(--dre-deals-park); }
  & .park-name { font: 600 10px var(--dre-deals-sans); fill: color-mix(in oklch, var(--dre-deals-late) 70%, var(--dre-deals-ink)); letter-spacing: .08em; text-transform: uppercase; }
  & .blk { fill: var(--dre-deals-block); transition: fill .3s; }
  & .blk.is-on { fill: color-mix(in oklch, var(--dre-deals-accent) 13%, var(--dre-deals-block)); }
  & .rd-c { fill: none; stroke: color-mix(in oklch, var(--dre-deals-ink) 14%, transparent); stroke-width: 11; stroke-linecap: round; }
  & .rd { fill: none; stroke: var(--dre-deals-card); stroke-width: 8; stroke-linecap: round; }
  & .rail { fill: none; stroke: color-mix(in oklch, var(--dre-deals-ink) 32%, transparent); stroke-width: 2.4; stroke-dasharray: 10 6; }
  & .rd-name { font: 600 9.5px var(--dre-deals-sans); fill: var(--dre-deals-faint); letter-spacing: .06em; }
  & .dist { cursor: pointer; }
  & .dist rect { fill: color-mix(in oklch, var(--dre-deals-card) 75%, transparent); stroke: transparent; transition: fill .2s, stroke .2s; }
  & .dist text { font: 700 12px var(--dre-deals-sans); letter-spacing: .14em; fill: var(--dre-deals-mute); pointer-events: none; }
  & .dist:hover rect, & .dist:focus-visible rect { fill: var(--dre-deals-card); stroke: color-mix(in oklch, var(--dre-deals-ink) 25%, transparent); }
  & .dist:focus { outline: none; }
  & .dist[aria-pressed=true] rect { fill: var(--dre-deals-accent); }
  & .dist[aria-pressed=true] text { fill: white; }
  & .brush { fill: color-mix(in oklch, var(--dre-deals-accent) 12%, transparent); stroke: var(--dre-deals-accent); stroke-width: 1.6; stroke-dasharray: 6 4; vector-effect: non-scaling-stroke; pointer-events: none; opacity: 0; transition: opacity .2s; }
  & .brush[data-on] { opacity: 1; }
  & .pin { cursor: pointer; transition: opacity .35s, filter .35s; }
  & .pin:focus { outline: none; }
  & .pin:focus-visible .ring { opacity: .7; }
  & .pin .dot {
    fill: var(--c); stroke: var(--dre-deals-card); stroke-width: 2.5; vector-effect: non-scaling-stroke;
    transform-box: fill-box; transform-origin: center; transition: fill .45s, scale .4s var(--dre-deals-spring);
    animation: dre-deals-drop .7s var(--dre-deals-spring) both; animation-delay: calc(var(--i) * 28ms + 300ms);
  }
  & .pin .ring { fill: none; stroke: var(--dre-deals-accent); stroke-width: 2.5; vector-effect: non-scaling-stroke; opacity: 0; transform-box: fill-box; transform-origin: center; }
  & .pin:hover .dot, & .pin:focus-visible .dot { scale: 1.25; }
  & .pin[aria-pressed=true] .ring { opacity: 1; animation: dre-deals-pulse 1.8s var(--dre-deals-out) infinite; }
  & .pin[aria-pressed=true] .dot { stroke: var(--dre-deals-accent); }
  & .pin.is-out { opacity: 0; pointer-events: none; }
  & .pin.is-dim { opacity: .18; filter: grayscale(1); }
  & .pin.is-lost .dot { fill: var(--dre-deals-card); stroke: var(--dre-deals-faint); stroke-dasharray: 3 3; }
  & .pin .lab { font: 700 13px var(--dre-deals-mono); fill: var(--dre-deals-ink); paint-order: stroke; stroke: var(--dre-deals-card); stroke-width: 4px; stroke-linejoin: round; opacity: 0; transition: opacity .2s; pointer-events: none; }
  & .pin[aria-pressed=true] .lab, & .pin:hover .lab { opacity: 1; }
}
.dre-deals__hint {
  position: absolute; left: 10px; bottom: 10px; display: inline-flex; align-items: center; gap: 6px; padding: 4px 9px 4px 7px; border-radius: 8px;
  font-size: 11px; color: var(--dre-deals-mute); background: color-mix(in oklch, var(--dre-deals-card) 85%, transparent); pointer-events: none;
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
}
.dre-deals__legend {
  position: absolute; right: 10px; bottom: 10px; display: flex; gap: 8px; padding: 5px 9px; border-radius: 8px; pointer-events: none;
  background: color-mix(in oklch, var(--dre-deals-card) 85%, transparent); font-size: 10.5px; color: var(--dre-deals-mute);
  & li { display: inline-flex; align-items: center; gap: 4px; white-space: nowrap; }
  & i { width: 9px; height: 9px; border-radius: 50%; background: var(--c); box-shadow: 0 0 0 1px color-mix(in oklch, var(--dre-deals-ink) 15%, transparent); }
}

.dre-deals__listbox {
  grid-area: list; position: relative; min-height: 0; min-width: 0; display: grid; grid-template-rows: auto minmax(0, 1fr);
  border-radius: 14px; background: var(--dre-deals-card); box-shadow: inset 0 0 0 1px var(--dre-deals-line); overflow: hidden;
}
.dre-deals__lh {
  display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 10px 10px 8px 14px; border-bottom: 1px solid var(--dre-deals-line);
  & h3 { font-size: 13px; font-weight: 680; white-space: nowrap; }
}
.dre-deals__list { min-height: 0; padding: 4px; }
.dre-deals__row {
  display: grid; grid-template-columns: 10px minmax(0, 1fr) auto; grid-template-areas: "dot name fee" "dot meta when"; gap: 0 10px; align-items: center;
  padding: 7px 10px; border-radius: 9px; cursor: pointer; transition: background-color .2s, opacity .3s;
  &:hover { background: var(--dre-deals-soft); }
  &[aria-selected=true] { background: color-mix(in oklch, var(--dre-deals-accent) 10%, var(--dre-deals-card)); box-shadow: inset 2px 0 0 var(--dre-deals-accent); }
  &:focus-visible { outline-offset: -2px; }
  & .d { grid-area: dot; width: 10px; height: 10px; border-radius: 50%; background: var(--c); box-shadow: 0 0 0 1px color-mix(in oklch, var(--dre-deals-ink) 15%, transparent); }
  & b { grid-area: name; font-size: 12.5px; font-weight: 640; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .m { grid-area: meta; font-size: 11px; color: var(--dre-deals-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .f { grid-area: fee; font: 650 12px var(--dre-deals-mono); font-variant-numeric: tabular-nums; }
  & .w { grid-area: when; font: 500 10.5px var(--dre-deals-mono); color: var(--dre-deals-faint); text-align: right; white-space: nowrap; }
  &.is-lost { opacity: .5; }
  &.is-lost b { text-decoration: line-through; text-decoration-color: var(--dre-deals-faint); }
}
@supports (animation-timeline: view()) {
  .dre-deals__row { animation: dre-deals-in linear both; animation-timeline: view(); animation-range: entry 0% entry 70%; }
}
.dre-deals__empty { padding: 26px 16px; text-align: center; color: var(--dre-deals-faint); font-size: 12px; text-wrap: balance; }

/* deal drawer: slides over the list inside the component */
.dre-deals__drawer {
  position: absolute; inset: 0; z-index: 5; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; background: var(--dre-deals-card);
  transition: translate .45s var(--dre-deals-spring), opacity .25s;
  @starting-style { translate: 24px 0; opacity: 0; }
}
.dre-deals__dh {
  padding: 12px 14px 10px; border-bottom: 1px solid var(--dre-deals-line); display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 10px;
  & h3 { font-size: 15px; font-weight: 720; letter-spacing: -.02em; line-height: 1.25; text-wrap: balance; }
  & p { grid-column: 1; font-size: 11.5px; color: var(--dre-deals-mute); }
  & .x { grid-row: 1 / span 2; grid-column: 2; width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; box-shadow: inset 0 0 0 1px var(--dre-deals-line); }
  & .x:hover { background: var(--dre-deals-soft); }
  & .x svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
}
.dre-deals__db { min-height: 0; padding: 12px 14px; display: grid; align-content: start; gap: 12px; }
.dre-deals__stages {
  display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 3px;
  & li { display: grid; gap: 4px; font-size: 9.5px; font-weight: 640; color: var(--dre-deals-faint); text-align: center; }
  & li::before { content: ""; height: 6px; border-radius: 3px; background: color-mix(in oklch, var(--dre-deals-ink) 9%, transparent); transition: background-color .4s; }
  & li.is-done::before { background: var(--c); }
  & li.is-now { color: var(--dre-deals-ink); }
  & li.is-now::before { box-shadow: 0 0 0 2px var(--dre-deals-card), 0 0 0 3.5px var(--c); }
}
.dre-deals__facts {
  display: grid; grid-template-columns: 1fr 1fr; gap: 8px;
  & div { padding: 8px 10px; border-radius: 9px; background: var(--dre-deals-soft); min-width: 0; }
  & dt { font-size: 10.5px; color: var(--dre-deals-faint); font-weight: 600; }
  & dd { font: 650 13px var(--dre-deals-mono); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.dre-deals__log {
  display: grid; gap: 6px; font-size: 11.5px;
  & li { display: grid; grid-template-columns: 56px minmax(0, 1fr); gap: 8px; color: var(--dre-deals-mute); }
  & li span { font: 500 10.5px var(--dre-deals-mono); color: var(--dre-deals-faint); padding-top: 1px; }
  & li.is-new { animation: dre-deals-rise .45s var(--dre-deals-out); color: var(--dre-deals-ink); }
}
.dre-deals__db h4 { font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--dre-deals-faint); }
.dre-deals__da { padding: 10px 14px 12px; border-top: 1px solid var(--dre-deals-line); display: flex; flex-wrap: wrap; gap: 6px; }
.dre-deals__btn {
  display: inline-flex; align-items: center; gap: 6px; padding: 7px 11px; border-radius: 9px; font-size: 12px; font-weight: 650;
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dre-deals-ink) 20%, transparent); transition: background-color .2s, scale .3s var(--dre-deals-spring);
  &:hover { background: var(--dre-deals-soft); }
  &:active { scale: .97; }
  &.is-solid { background: var(--dre-deals-ink); color: var(--dre-deals-bg); box-shadow: none; }
  &.is-solid:hover { background: color-mix(in oklch, var(--dre-deals-ink) 85%, var(--dre-deals-late)); }
  &[aria-disabled=true] { opacity: .45; cursor: not-allowed; }
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
}

/* ---------- forecast */
.dre-deals__fc { display: grid; grid-template-columns: minmax(0, 1fr) 290px; gap: 10px; }
.dre-deals__panel { min-height: 0; min-width: 0; border-radius: 14px; background: var(--dre-deals-card); box-shadow: inset 0 0 0 1px var(--dre-deals-line); padding: 12px 14px; animation: dre-deals-rise .5s var(--dre-deals-out) both; }
.dre-deals__fcp { display: grid; grid-template-rows: auto minmax(0, 1fr); }
.dre-deals__ph { display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap; margin-bottom: 6px; & h3 { font-size: 13px; font-weight: 680; } }
.dre-deals__plot { position: relative; min-height: 0; }
.dre-deals__fchart {
  position: absolute; inset: 0; width: 100%; height: 100%;
  & .ax line { stroke: var(--dre-deals-line); }
  & text { font: 500 10.5px var(--dre-deals-mono); fill: var(--dre-deals-faint); font-variant-numeric: tabular-nums; }
  & .yr { font: 700 10.5px var(--dre-deals-sans); fill: var(--dre-deals-mute); letter-spacing: .06em; }
  & .now { stroke: var(--dre-deals-accent); stroke-width: 1.5; stroke-dasharray: 3 3; }
  & .nowl { fill: var(--dre-deals-accent); font-weight: 700; }
  & .col { fill: transparent; }
  & .col[data-on] { fill: var(--dre-deals-soft); }
  & rect.b { fill: var(--c); }
  & rect.b[data-st="5"] { fill: var(--dre-deals-ink); }
  & rect.hit { fill: transparent; cursor: crosshair; }
}
.dre-deals__land {
  display: grid; align-content: start; gap: 6px; animation-delay: 80ms;
  & h3 { font-size: 13px; font-weight: 680; }
  & h4 { margin-top: 10px; font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--dre-deals-faint); }
}
.dre-deals__big { font-size: clamp(26px, 3.2cqi, 34px); font-weight: 760; letter-spacing: -.04em; line-height: 1.05; }
.dre-deals__lsub { font-size: 12px; color: var(--dre-deals-mute); text-wrap: pretty; & b { color: var(--dre-deals-ink); } }
.dre-deals__bullet {
  width: 100%; height: 34px; margin-top: 6px;
  & .bg { fill: var(--dre-deals-soft); }
  & .closed { fill: var(--dre-deals-ink); }
  & .weighted { fill: var(--dre-deals-late); }
