/* ---------------- forecast */
const fchart = $('.dre-deals__fchart'), fplot = fchart.parentElement;
let fPrev = null, fHover = -1, fGeo = null;
function fSeries() {
  /* per month (Jan 2026 to Jun 2027), stacked by stage; closed fees are actuals */
  const out = [];
  for (let m = 0; m < 18; m++) {
    const seg = [0, 0, 0, 0, 0, 0];
    DEALS.forEach(d => { if (d.m !== m || d.lost || !base(d)) return; seg[d.stage] += d.stage === 5 ? d.fee : (S.basis === 'w' ? wOf(d) : d.fee); });
    out.push(seg);
  }
  return out;
}
function drawForecast(k) {
  if (S.view !== 'fc') return;
  const W = fplot.clientWidth, H = fplot.clientHeight; if (W < 60 || H < 60) return;
  fchart.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  const cur = fSeries(), prev = fPrev && k < 1 ? fPrev : null;
  const ser = cur.map((seg, m) => seg.map((v, s) => prev ? prev[m][s] + (v - prev[m][s]) * k : v * (fPrev ? 1 : k)));
  const max = Math.max(0.3, ...cur.map(s => s.reduce((a, b) => a + b, 0)));
  const ticks = niceTicks(0, max * 1.08, 4), top = ticks[ticks.length - 1];
  const pl = 46, pr = 8, pt = 14, pb = 38, iw = W - pl - pr, ih = H - pt - pb, bw = iw / 18;
  const Y = v => pt + ih - v / top * ih;
  fGeo = { pl, bw, pt, ih, W };
  let s = '<g class="ax">' + ticks.map(t => '<line x1="' + pl + '" x2="' + (W - pr) + '" y1="' + Y(t).toFixed(1) + '" y2="' + Y(t).toFixed(1) + '"/><text x="' + (pl - 7) + '" y="' + (Y(t) + 3.5).toFixed(1) + '" text-anchor="end">' + (t ? (t >= 1 ? '$' + t.toFixed(t % 1 ? 1 : 0) + 'M' : '$' + Math.round(t * 1000) + 'k') : '0') + '</text>').join('') + '</g>';
  s += '<rect class="col"' + (fHover > -1 ? ' data-on="" x="' + (pl + fHover * bw).toFixed(1) + '"' : ' x="0"') + ' y="' + pt + '" width="' + bw.toFixed(1) + '" height="' + ih + '"/>';
  ser.forEach((seg, m) => {
    let acc = 0; const x = pl + m * bw + bw * 0.18, w = bw * 0.64;
    [5, 4, 3, 2, 1, 0].forEach(st => {
      const v = seg[st]; if (v <= 0.0004) return;
      s += '<rect class="b" data-st="' + st + '" x="' + x.toFixed(1) + '" y="' + Y(acc + v).toFixed(1) + '" width="' + w.toFixed(1) + '" height="' + Math.max(0.5, Y(acc) - Y(acc + v)).toFixed(1) + '" rx="2"/>';
      acc += v;
    });
    s += '<text x="' + (pl + (m + 0.5) * bw).toFixed(1) + '" y="' + (H - pb + 14) + '" text-anchor="middle">' + (bw < 26 ? MON[m % 12][0] : MON[m % 12]) + '</text>';
  });
  s += '<text class="yr" x="' + pl + '" y="' + (H - 6) + '">2026</text><text class="yr" x="' + (pl + 12 * bw).toFixed(1) + '" y="' + (H - 6) + '">2027</text>';
  const nx = pl + NOW * bw;
  s += '<line class="now" x1="' + nx.toFixed(1) + '" x2="' + nx.toFixed(1) + '" y1="' + (pt - 6) + '" y2="' + (pt + ih) + '"/><text class="nowl" x="' + (nx + 5).toFixed(1) + '" y="' + (pt + 4) + '">today</text>';
  s += '<rect class="hit" x="' + pl + '" y="' + pt + '" width="' + iw.toFixed(1) + '" height="' + ih + '"/>';
  fchart.innerHTML = s;
  if (k >= 1) fPrev = cur;
}
function animateForecast() { if (S.view !== 'fc') return; tween(700, k => drawForecast(k)); }
fchart.addEventListener('pointermove', e => {
  if (!fGeo) return;
  const b = fchart.getBoundingClientRect(), m = Math.floor((e.clientX - b.left - fGeo.pl) / fGeo.bw);
  if (m < 0 || m > 17) { fLeave(); return; }
  fShow(m, e.clientX, e.clientY);
});
function fShow(m, cx, cy) {
  if (m !== fHover) { fHover = m; drawForecast(1); }
  const ds = DEALS.filter(d => d.m === m && !d.lost && base(d)).sort((a, c) => wOf(c) - wOf(a));
  const tot = ds.reduce((a, d) => a + (d.stage === 5 ? d.fee : S.basis === 'w' ? wOf(d) : d.fee), 0);
  placeTip(tip, '<b>' + mName(m) + ' · ' + fK(tot) + (m < NOW ? ' closed' : S.basis === 'w' ? ' weighted' : ' best case') + '</b>' +
    (ds.length ? ds.slice(0, 5).map(d => '<span><em>' + esc(d.name.length > 24 ? d.name.slice(0, 23) + '…' : d.name) + '</em>' + fK(d.stage === 5 ? d.fee : S.basis === 'w' ? wOf(d) : d.fee) + '</span>').join('') + (ds.length > 5 ? '<span><em>and ' + (ds.length - 5) + ' more</em></span>' : '') : '<span><em>No deals this month</em></span>'), cx, cy);
}
fchart.setAttribute('tabindex', '0');
fchart.setAttribute('aria-label', 'Closed and forecast fees by month. Left and right arrow keys read each month.');
fchart.addEventListener('keydown', e => {
  if (!fGeo) return;
  let m = fHover;
  if (e.key === 'ArrowRight') m = m < 0 ? NOW : Math.min(17, m + 1); else if (e.key === 'ArrowLeft') m = m < 0 ? NOW : Math.max(0, m - 1);
  else if (e.key === 'Home') m = 0; else if (e.key === 'End') m = 17; else return;
  e.preventDefault();
  const b = fchart.getBoundingClientRect();
  fShow(m, b.left + fGeo.pl + (m + 0.5) * fGeo.bw, b.top + fGeo.pt + fGeo.ih * 0.4);
});
fchart.addEventListener('blur', fLeave);
function fLeave() { if (fHover > -1) { fHover = -1; drawForecast(1); } hideTip(tip); }
fchart.addEventListener('pointerleave', fLeave);
radioGroup($('.dre-deals__fcp .dre-deals__seg'), v => { S.basis = v; animateForecast(); });

/* 2026 landing: closed + weighted Q4, with the unweighted upside shown separately */
function paintLanding() {
  const B = DEALS.filter(base);
  const cf = B.filter(d => d.stage === 5 && !d.lost && d.m < 12).reduce((a, d) => a + d.fee, 0);
  const q4o = B.filter(d => open(d) && d.m <= 11), q4w = q4o.reduce((a, d) => a + wOf(d), 0), q4f = q4o.reduce((a, d) => a + d.fee, 0);
  const land = cf + q4w, pct = Math.round(land / S.target * 100);
  countTo(k$('land'), land, fK);
  k$('land2').innerHTML = '<b>' + pct + '%</b> of the ' + fK(S.target) + ' target: ' + fK(cf) + ' closed plus ' + fK(q4w) + ' weighted to close by December.';
  k$('tgt').textContent = fK(S.target);
  const bul = $('.dre-deals__bullet'), W = bul.clientWidth || 260, max = Math.max(S.target, cf + q4f) * 1.08, x = v => v / max * W;
  bul.setAttribute('viewBox', '0 0 ' + W + ' 34');
  bul.innerHTML = '<rect class="bg" x="0" y="10" width="' + W + '" height="16" rx="4"/>' +
    '<rect class="best" x="' + x(cf + q4w).toFixed(1) + '" y="10" width="' + x(q4f - q4w).toFixed(1) + '" height="16"/>' +
    '<rect class="weighted" x="' + x(cf).toFixed(1) + '" y="10" width="' + x(q4w).toFixed(1) + '" height="16"/>' +
    '<rect class="closed" x="0" y="10" width="' + x(cf).toFixed(1) + '" height="16" rx="4"/>' +
    '<line class="tgt" x1="' + x(S.target).toFixed(1) + '" x2="' + x(S.target).toFixed(1) + '" y1="4" y2="32"/><text x="' + (x(S.target) - 4).toFixed(1) + '" y="7" text-anchor="end">target</text>';
  $('.dre-deals__lk').innerHTML =
    '<li><i style="background:var(--dre-deals-ink)"></i>Closed, ' + B.filter(d => d.stage === 5 && !d.lost && d.m < 12).length + ' deals<b>' + fK(cf) + '</b></li>' +
    '<li><i style="background:var(--dre-deals-late)"></i>Weighted Q4, ' + q4o.length + ' deals<b>' + fK(q4w) + '</b></li>' +
    '<li><i style="background:color-mix(in oklch, var(--dre-deals-early) 80%, white)"></i>Upside if all Q4 deals close<b>' + fK(q4f - q4w) + '</b></li>';
  const sw = q4o.slice().sort((a, b) => (b.fee - wOf(b)) - (a.fee - wOf(a))).slice(0, 4);
  $('.dre-deals__swing').innerHTML = sw.length ? sw.map(d => '<li><button type="button" data-i="' + d.i + '" data-st="' + d.stage + '"><i aria-hidden="true"></i><span>' + esc(d.name) + '</span><b>+' + fK(d.fee - wOf(d)) + '</b></button></li>').join('') : '<li class="dre-deals__empty">No open deals close this year under these filters.</li>';
  $$('.dre-deals__step').forEach(b => {
    const off = +b.dataset.d < 0 ? S.target <= 1.5 + 1e-9 : S.target >= 4 - 1e-9;
    if (off) { b.setAttribute('aria-disabled', 'true'); b.title = 'The target stays between $1.50M and $4.00M'; } else { b.removeAttribute('aria-disabled'); b.removeAttribute('title'); }
  });
}
$$('.dre-deals__step').forEach(b => b.addEventListener('click', () => {
  if (b.getAttribute('aria-disabled') === 'true') return;
  S.target = Math.round((S.target + +b.dataset.d * 0.1) * 10) / 10;
  paintLanding(); kpis();
}));
$('.dre-deals__swing').addEventListener('click', e => {
