/* ---------------- team */
const blist = $('.dre-deals__brokers');
function brokerStats() {
  return Object.keys(BROKERS).map(k => {
    const ds = DEALS.filter(d => d.br === k && S.types.has(d.type) && inArea(d) && !d.lost);
    const seg = [0, 1, 2, 3, 4].map(st => ds.filter(d => d.stage === st && inWin(d)).reduce((a, d) => a + wOf(d), 0));
    return { k, seg, w: seg.reduce((a, b) => a + b, 0), c: ds.filter(d => d.stage === 5 && d.m < 12).reduce((a, d) => a + d.fee, 0), n: ds.filter(d => d.stage < 5 && inWin(d)).length, nc: ds.filter(d => d.stage === 5).length };
  });
}
function paintTeam(animate) {
  const st = brokerStats().sort((a, b) => b[S.rank] - a[S.rank]), max = Math.max(0.01, ...st.map(s => s.w));
  const fill = () => {
    st.forEach((s, idx) => {
      let li = $('li[data-b="' + s.k + '"]', blist);
      if (!li) { li = document.createElement('li'); li.dataset.b = s.k; }
      li.innerHTML = '<button type="button" class="dre-deals__br" style="--i:' + idx + '" aria-label="Show ' + BROKERS[s.k] + '’s deals on the map"><span class="av">' + s.k + '</span><span class="nm"><b>' + BROKERS[s.k] + '</b><small>' + s.n + ' open · ' + s.nc + ' closed</small></span>' +
        '<span class="bar" aria-hidden="true">' + s.seg.map((v, i) => v > 0 ? '<i data-st="' + i + '" style="width:' + (v / max * 100).toFixed(2) + '%"></i>' : '').join('') + '</span>' +
        '<span class="k">' + fK(s.w) + '<small>weighted</small></span><span class="k">' + fK(s.c) + '<small>closed 2026</small></span>' +
        '<span class="go" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M9 4 3.5 6v14L9 18l6 2 5.5-2V4L15 6z"/><path d="M9 4v14M15 6v14"/></svg></span></button>';
      blist.appendChild(li);
    });
  };
  if (animate) flip(() => $$('li', blist), fill, 480); else fill();
}
